INSERT INTO `sv_songs` (`id`, `fid`, `fname`, `filename`, `filetype`, `cid`, `group_id`, `upload_date`, `down_counts`, `view_counts`, `author`, `description`, `status`, `trash`) VALUES
(17748, 400, '108.jpg', '', 'image/jpeg', 17, 17746, '2019-03-27 09:59:21', 0, 0, 'System', 'மள்ள ரன்ன மரவந் தழீஇ<br/>\r\nமகளி ரன்ன வாடுகொடி நுடங்கு<br/>\r\nமரும்பதங் கொண்ட பெரும்பத வேனிற்<br/>\r\nகாதல் புணர்ந்தன ளாகி யாய்கழல்<br/>\r\nவெஞ்சின விறல்வேற் காளையொ<br/>\r\nடின்றுபுகு தருமென வந்தன்று தூதே', 1, 0),
(17747, 399, '108.jpg', '', 'image/jpeg', 17, 17746, '2019-03-27 09:59:21', 0, 0, 'System', 'நும்மனைச் சிலம்பு கழீஇ யயரினு<br/>\r\nமெம்மனை வதுவை நன்மணங் கழிகெனச்<br/>\r\nசொல்லி னெவனோ மற்றே வென்வேன்<br/>\r\nமையற விளங்கிய கழலடிப்<br/>\r\nபொய்வல் காளையை யீன்ற தாய்க்கே', 1, 0),
(17746, 398, '108.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 09:59:21', 0, 0, 'System', 'புள்ளு மறியாப் பல்பழம் பழுனி<br/>\r\nமடமா னறியாத் தடநீர் நிலைஇச்<br/>\r\nசுரநனி யினிய வாகுக வென்று<br/>\r\nநினைத்தொறுங் கலிழு மென்னினு<br/>\r\nமிகப்பெரிது புலம்பின்று தோழிநம் மூரே', 1, 0),
(17745, 397, '107.jpg', '', 'image/jpeg', 17, 17740, '2019-03-27 09:57:32', 0, 0, 'System', 'கவிழ்மயி ரெருத்திற் செந்நா யேற்றை<br/>\r\nகுருளைப் பன்றி கொள்ளாது கழியுஞ்<br/>\r\nசுரநனி வாரா நின்றன ளென்பது<br/>\r\nமுன்னுற விரைந்தநீ ருரைமி<br/>\r\nனின்னகை முறுவலென் னாயத் தோர்க்கே', 1, 0),
(17744, 396, '107.jpg', '', 'image/jpeg', 17, 17740, '2019-03-27 09:57:32', 0, 0, 'System', 'புலிப்பொறி வேங்கைப் பொன்னிணர் கொய்துநின்<br/>\r\nகதுப்பய லணியு மளவை பைபயச்<br/>\r\nசுரத்திடை யயர்ச்சியை யாறுக மடந்தை<br/>\r\nகல்கெழு சிறப்பி னம்மூ<br/>\r\nரெல்விருந் தாகிப் புகுக நாமே', 1, 0),
(17743, 395, '107.jpg', '', 'image/jpeg', 17, 17740, '2019-03-27 09:57:32', 0, 0, 'System', 'முளிவயிர்ப் பிறந்த வளிவளர் கூரெரிச்<br/>\r\nசுடர்விடு நெடுங்கொடி விடர்முகை முழங்கு<br/>\r\nமின்னா வருஞ்சுரந் தீர்ந்தன மென்மெல<br/>\r\nவேகுமதி வாழியோ குறுமகள் போதுகலந்து<br/>\r\nகறங்கிசை யருவி வீழும்<br/>\r\nபிறங்கிருஞ் சோலைநம் மலைகெழு நாட்டே', 1, 0),
(17742, 394, '107.jpg', '', 'image/jpeg', 17, 17740, '2019-03-27 09:57:32', 0, 0, 'System', 'மாண்பில் கொள்கையொடு மயங்குதுயர் செய்த<br/>\r\nவன்பி லறனு மருளிற்று மன்ற<br/>\r\nவெஞ்சுர மிறந்த வஞ்சி லோதிப்<br/>\r\nபெருமட மான்பிணை யலைத்த<br/>\r\nசிறுநுதற் குறுமகட் காட்டிய வம்மே', 1, 0),
(17741, 393, '107.jpg', '', 'image/jpeg', 17, 17740, '2019-03-27 09:57:32', 0, 0, 'System', 'துறந்ததற் கொண்டு துயரடச் சாஅ<br/>\r\nயறம்புலந்து பழிக்கு மளைக ணாட்டி<br/>\r\nயெவ்வ நெஞ்சிற் கேம மாக<br/>\r\nவந்தன ளோநின் மகளே<br/>\r\nவெந்திறல் வெள்வேல் விடலைமுந் துறவே', 1, 0),
(17740, 392, '107.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 09:57:32', 0, 0, 'System', 'வேய்வனப் பிழந்த தோளும் வெயிறெற<br/>\r\nவாய்கவின் றொலைந்த நுதலு நோக்கிப்<br/>\r\nபரியல் வாழி தோழி பரியி<br/>\r\nனெல்லையி லிடும்பை தரூஉ<br/>\r\nநல்வரை நாடனொடு வந்த மாறே', 1, 0),
(17739, 391, '106.jpg', '', 'image/jpeg', 17, 17735, '2019-03-27 09:43:39', 0, 0, 'System', 'மறுவி றூவிச் சிறுகருங் காக்கை<br/>\r\nயன்புடை மரபினின் கிளையோ டாரப்<br/>\r\nபச்சூன் பெய்த பைந்நிண வல்சி<br/>\r\nபொலம்புனை கலத்திற் றருகுவென் மாதோ<br/>\r\nவெஞ்சின விறல்வேற் காளையொ<br/>\r\nடஞ்சி லோதியை வரக்கரைந் தீமே', 1, 0),
(17738, 390, '106.jpg', '', 'image/jpeg', 17, 17735, '2019-03-27 09:43:39', 0, 0, 'System', 'நல்லோ ராங்கட் பரந்துகை தொழுது<br/>\r\nபல்லூழ் மறுகி வினவு வோயே<br/>\r\nதிண்டோள் வல்விற் காளையொடு<br/>\r\nகண்டனெ மன்ற சுரத்திடை யாமே', 1, 0),
(17737, 389, '106.jpg', '', 'image/jpeg', 17, 17735, '2019-03-27 09:43:39', 0, 0, 'System', 'செய்வினைப் பொலிந்த செறிகழ னோன்றாண்<br/>\r\nமையணற் காளையொடு பைய வியலிப்<br/>\r\nபாவை யன்னவென் னாய்தொடி மடந்தை<br/>\r\nசென்றன ளென்றி ரைய<br/>\r\nவொன்றின வோவவ ளஞ்சிலம் படியே', 1, 0),
(17736, 388, '106.jpg', '', 'image/jpeg', 17, 17735, '2019-03-27 09:43:39', 0, 0, 'System', 'நெருப்பவிர் கனலி யுருப்புச்சினந் தணியக்<br/>\r\nகருங்கால் யாத்து வரிநிழ லிரீஇச்<br/>\r\nசிறுவரை யிறப்பிற் காண்குவை செறிதொடிப்<br/>\r\nபொன்னேர் மேனி மடந்தையொடு<br/>\r\nவென்வேல் விடலை முன்னிய சுரனே', 1, 0),
(17735, 387, '106.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 09:43:39', 0, 0, 'System', 'அறம்புரி யருமறை நவின்ற நாவிற்<br/>\r\nறிறம்புரி கொள்கை யந்தணிர் தொழுவலென்<br/>\r\nறொண்டொடி வினவும் பேதையம் பெண்டே<br/>\r\nகண்டென மம்ம சுரத்திடை யவளை<br/>\r\nயின்றுணை யினிதுபா ராட்டக்<br/>\r\nகுன்றுயர் பிறங்கன் மலையிறந் தோளே', 1, 0),
(17734, 386, '105.jpg', '', 'image/jpeg', 17, 17730, '2019-03-27 09:41:52', 0, 0, 'System', 'புன்கண் யானையொடு புலிவழங் கத்த<br/>\r\nநயந்த காதலற் புணர்ந்துசென் றனளே<br/>\r\nநெடுஞ்சுவர் நல்லின் மருண்ட<br/>\r\nவிடும்பை யுறுவிநின் கடுஞ்சூன் மகளே', 1, 0),
(17733, 385, '105.jpg', '', 'image/jpeg', 17, 17730, '2019-03-27 09:41:52', 0, 0, 'System', 'கடுங்கட் காளையொடு நெடுந்தே ரேறிக்<br/>\r\nகோள்வல் வேங்கை மலைபிறக் கொழிய<br/>\r\nவேறுபல் லருஞ்சுர மிறந்தன ளவளெனக்<br/>\r\nகூறுமின் வாழியோ வாறுசென் மாக்க<br/>\r\nணற்றோ ணயந்துபா ராட்டி<br/>\r\nயெற்கெடுத் திருந்த வறனில் யாய்க்கே', 1, 0),
(17732, 384, '105.jpg', '', 'image/jpeg', 17, 17730, '2019-03-27 09:41:52', 0, 0, 'System', 'சேட்புல முன்னிய வசைநடை யந்தணிர்<br/>\r\nநும்மொன் றிரந்தனென் மொழிவ லெம்மூர்<br/>\r\nயாய்நயந் தெடுத்த வாய்நலங் கவின<br/>\r\nவாரிடை யிறந்தன ளென்மி<br/>\r\nனேரிறை முன்கையென் னாயத் தோர்க்கே', 1, 0),
(17731, 383, '105.jpg', '', 'image/jpeg', 17, 17730, '2019-03-27 09:41:52', 0, 0, 'System', 'கோட்சுரும் பரற்று நாட்சுரத் தமன்ற<br/>\r\nநெடுங்கான் மராஅத்துக் குறுஞ்சினை பற்றி<br/>\r\nவலஞ்சுரி வாலிணர் கொய்தற்கு நின்ற<br/>\r\nமள்ள னுள்ள மகிழ்கூர்ந் தன்றே<br/>\r\nபஞ்சாய்ப் பாவைக்குந் தனக்கு<br/>\r\nமஞ்சாய் கூந்த லாய்வது கண்டே', 1, 0),
(17730, 382, '105.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 09:41:52', 0, 0, 'System', 'புள்ளொலிக் கமர்த்த கண்ணள் வெள்வேற்<br/>\r\nறிருந்துகழற் காளையொ டருஞ்சுரங் கழிவோ<br/>\r\nளெல்லிடை யசைந்த கல்லென் சீறூர்ப்<br/>\r\nபுனையிழை மகளிர்ப் பயந்த<br/>\r\nமனைகெழு பெண்டிர்க்கு நோவுமார் பெரிதே', 1, 0),
(17729, 381, '104.jpg', '', 'image/jpeg', 17, 17725, '2019-03-27 09:40:03', 0, 0, 'System', 'பைங்காய் நெல்லி பலவுடன் மிசைந்து<br/>\r\nசெங்கான் மராஅத்த வரிநிழ லிருந்தோர்<br/>\r\nயார்கொ லளியர் தாமே வார்சிறைக்<br/>\r\nகுறுங்கான் மகன்றி லன்ன<br/>\r\nவுடன்புணர் கொள்கைக் காத லோரே', 1, 0),
(17728, 380, '104.jpg', '', 'image/jpeg', 17, 17725, '2019-03-27 09:40:03', 0, 0, 'System', 'அத்த நீளிடை யவனொடு போகிய<br/>\r\nமுத்தேர் வெண்பன் முகிழ்நகை மடவர<br/>\r\nறாய ரென்னும் பெயரே வல்லா<br/>\r\nறெடுத்தேன் மன்ற யானே<br/>\r\nகொடுத்தோர் மன்றவவ ளாயத் தோரே', 1, 0),
(17727, 379, '104.jpg', '', 'image/jpeg', 17, 17725, '2019-03-27 09:40:03', 0, 0, 'System', 'தன்னம ராயமொடு நன்மண நுகர்ச்சியி<br/>\r\nனினிதாங் கொல்லோ தனக்கே பனிவரை<br/>\r\nயினக்களிறு வழங்குஞ் சோலை<br/>\r\nவயக்குறு வெள்வே லவற்புணர்ந்து செலவே', 1, 0),
(17726, 378, '104.jpg', '', 'image/jpeg', 17, 17725, '2019-03-27 09:40:03', 0, 0, 'System', 'செல்லிய முயலிப் பாஅய சிறகர்<br/>\r\nவாவ லுகக்கு மாலையாம் புலம்பப்<br/>\r\nபோகிய வவட்கோ நோவேன் றேமொழித்<br/>\r\nதுணையிலள் கலிழு3 நெஞ்சி<br/>\r\nனிணையே ருண்க ணிவட்குநோ வதுவே', 1, 0),
(17725, 377, '104.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 09:40:03', 0, 0, 'System', 'நீர்நசைக் கூக்கிய வுயவல் யானை<br/>\r\nயியம்புணர் தூம்பி னுயிர்க்கு மத்தஞ்<br/>\r\nசென்றனண் மன்றவென் மகளே<br/>\r\nபந்தும் பாவையும் கழங்குமெமக் கொழித்தே\r\n', 1, 0),
(17724, 376, '103.jpg', '', 'image/jpeg', 17, 17718, '2019-03-27 09:37:04', 0, 0, 'System', 'நாடொறுங் கலிழு மென்னினு மிடைநின்று<br/>\r\nகாடுபடு தீயிற் கனலியர் மாதோ<br/>\r\nநல்வினை நெடுநகர் கல்லெனக் கலங்கப்<br/>\r\nபூப்புரை யுண்கண் மடவரற்<br/>\r\nபோக்கிய புணர்த்த வறனில் பாலே', 1, 0),
(17723, 375, '103.jpg', '', 'image/jpeg', 17, 17718, '2019-03-27 09:37:04', 0, 0, 'System', 'இதுவென் பாவை பாவை யிதுவென்<br/>\r\nனலமரு நோக்கி னலம்வரும் சுடர்நுதற்<br/>\r\nபைங்கிளி யெடுத்த பைங்கிளி யென்றிவை<br/>\r\nகாண்டொறுங் காண்டொறுங் கலங்க<br/>\r\nநீங்கின ளோவென் பூங்க ணோளே', 1, 0),
(17722, 374, '103.jpg', '', 'image/jpeg', 17, 17718, '2019-03-27 09:37:04', 0, 0, 'System', 'பல்லூழ் நினைப்பினு நல்லென் றூழ<br/>\r\nமீளி முன்பிற் காளை காப்ப<br/>\r\nமுடியகம் புகாஅக் கூந்தலள்<br/>\r\nகடுவனு மறியாக் காடிறந் தோளே', 1, 0),
(17721, 373, '103.jpg', '', 'image/jpeg', 17, 17718, '2019-03-27 09:37:04', 0, 0, 'System', ' நினைத்தொறுங் கலிழு மிடும்பை யெய்துக<br/>\r\nபுலிக்கோட் பிழைத்த கவைக்கோட்டு முதுகலை<br/>\r\nமான்பிணை யணைதர வாண்குரல் விளிக்கும்<br/>\r\nவெஞ்சுர மென்மக ளுய்த்த<br/>\r\nவம்பமை வல்வில் விடலை தாயே', 1, 0),
(17720, 372, '103.jpg', '', 'image/jpeg', 17, 17718, '2019-03-27 09:37:04', 0, 0, 'System', 'என்னு முள்ளினள் கொல்லோ தன்னை<br/>\r\nநெஞ்சுணத் தேற்றிய வஞ்சினக் காளையொ<br/>\r\nடழுங்கன் மூதூ ரலரெழச்<br/>\r\nசெழும்பல் குன்ற மிறந்தவென் மகளே', 1, 0),
(17719, 371, '103.jpg', '', 'image/jpeg', 17, 17718, '2019-03-27 09:37:04', 0, 0, 'System', 'மள்ளர் கொட்டின் மஞ்ஞை யாலு<br/>\r\nமுயர்நெடுங் குன்றம் படுமழை தலைஇச்<br/>\r\nசுரநனி யினிய வாகுக தில்ல<br/>\r\nவறநெறி யிதுவெனத் தெளிந்தவென்<br/>\r\nபிறைநுதற் குறுமகள் போகிய சுரனே', 1, 0),
(17718, 370, '103.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 09:37:04', 0, 0, 'System', 'வண்சினைக் கோங்கின் றண்கமழ் படலை<br/>\r\nயிருஞ்சிறை வண்டின் பெருங்கிளை மொய்ப்ப<br/>\r\nநீநயந் துறையப் பட்டோள்<br/>\r\nயாவ ளோவெம் மறையா தீமே', 1, 0),
(17717, 369, '102.jpg', '', 'image/jpeg', 17, 17712, '2019-03-27 07:54:29', 0, 0, 'System', 'வளமலர் ததைந்த வண்டுபடு நறும்பொழின்<br/>\r\nமுளைநிரை முறுவ லொருத்தியொடு நெருநற்<br/>\r\nகுறிநீ செய்தனை யென்ப வலரே<br/>\r\nகுரவ நீள்சினை யுறையும்<br/>\r\nபருவ மாக்குயிற் கௌவையிற் பெரிதே', 1, 0),
(17716, 368, '102.jpg', '', 'image/jpeg', 17, 17712, '2019-03-27 07:54:29', 0, 0, 'System', 'எரிப்பூ விலவத் தூழ்கழி பன்மலர்<br/>\r\nபொரிப்பூம் புன்கின் புகர்நிழல் வரிக்குந்<br/>\r\nதண்பத வேனி லின்ப நுகர்ச்சி<br/>\r\nயெம்மொடு கொண்மோ பெருமநின்<br/>\r\nனம்மெ லோதி யழிவில ளெனினே', 1, 0),
(17715, 367, '102.jpg', '', 'image/jpeg', 17, 17712, '2019-03-27 07:54:29', 0, 0, 'System', 'பொரியரைக் கோங்கின் பொன்மருள் பசுவீ<br/>\r\nவிரியிணர் வேங்கையொடு வேறுபட மிலைச்சி<br/>\r\nவிரவுமல ரணிந்த வேனிற்கான் யாற்றுத்<br/>\r\nதேரொடு குறுக வந்தோன்<br/>\r\nபேரொடு புணர்ந்தன் றன்னை யிவளுயிரே', 1, 0),
(17714, 366, '102.jpg', '', 'image/jpeg', 17, 17712, '2019-03-27 07:54:29', 0, 0, 'System', 'அன்னாய் வாழிவேண் டன்னையென் றோழி<br/>\r\nபசந்தனள் பெரிதெனச் சிவந்த கண்ணை<br/>\r\nகொன்னே கடவுதி யாயி னென்னதூஉ<br/>\r\nமறிய வாகுமோ மற்றே<br/>\r\nமுறியிணர்க் கோங்கம் பயந்த மாறே', 1, 0),
(17713, 365, '102.jpg', '', 'image/jpeg', 17, 17712, '2019-03-27 07:54:29', 0, 0, 'System', 'கணமா தொலைச்சித் தன்னையர் தந்த<br/>\r\nநிணவூன் வல்சிப் படுபுள் ளோப்பு<br/>\r\nநலமா ணெயிற்றி போலப் பலமிகு<br/>\r\nநன்னல நயவர வுடையை<br/>\r\nயென்னோற் றனையோ மாவின் றளிரே', 1, 0),
(17712, 364, '102.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 07:54:29', 0, 0, 'System', 'முளமா வல்சி யெயினர் தங்கை<br/>\r\nயிளமா வெயிற்றிக்கு மிந்நிலை யறியச்<br/>\r\nசொல்லினே னிரக்கு மளவை<br/>\r\nவெள்வேல்3 விடலை விரையா தீமே', 1, 0),
(17711, 363, '101.jpg', '', 'image/jpeg', 17, 17708, '2019-03-27 07:51:52', 0, 0, 'System', 'சிலைவிற் பகழிச் செந்துவ ராடைக்<br/>\r\nகொலைவி லெயினர் தங்கைநின் முலைய<br/>\r\nசுணங்கென நினைதி நீயே<br/>\r\nயணங்கென நினையுமென் னணங்குறு நெஞ்சே', 1, 0),
(17710, 362, '101.jpg', '', 'image/jpeg', 17, 17708, '2019-03-27 07:51:52', 0, 0, 'System', 'பதுக்கைத் தாய வொதுக்கருங் கவலைச்<br/>\r\nசிறுகண் யானை யுறுபகை நினையா<br/>\r\nதியாங்குவந் தனையோ பூந்தார் மார்ப<br/>\r\nவருள்புரி நெஞ்ச முய்த்தர<br/>\r\nவிருள்பொர நின்ற விரவி னானே', 1, 0),
(17709, 361, '101.jpg', '', 'image/jpeg', 17, 17708, '2019-03-27 07:51:52', 0, 0, 'System', 'உயர்கரைக் கான்யாற் றவிர்மண லகன்றுறை<br/>\r\nவேனிற் பாதிரி விரிமலர் குவைஇத்<br/>\r\nதொடலை தைஇய மடவரன் மகளே<br/>\r\nகண்ணினுங் கதவநின் முலையே<br/>\r\nமுலையினுங் கதவநின் றடமென் றோளே', 1, 0),
(17708, 360, '101.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 07:51:52', 0, 0, 'System', 'எரிகவர்ந் துண்ட வென்றூழ் நீளிடை<br/>\r\nயரிய வாயினு மெளிய வன்றே<br/>\r\nயவவுறு நெஞ்சங் கவவுநனி விரும்பிக்<br/>\r\nகடுமான் றிண்டேர் கடைஇ<br/>\r\nநெடுமா னோக்கிநின் னுள்ளியாம் வரவே', 1, 0),
(17707, 359, '100.jpg', '', 'image/jpeg', 17, 17702, '2019-03-27 07:49:18', 0, 0, 'System', 'அரும்பொருள் வேட்கைய மாகிநிற் றுறந்து<br/>\r\nபெருங்க லதரிடைப் பிரிந்த காலைத்<br/>\r\nதவநனி நெடிய வாயின வினியே<br/>\r\nயணியிழை யுள்ளியாம் வருதலி<br/>\r\nனணிய வாயின சுரத்திடை யாறே', 1, 0),
(17706, 358, '100.jpg', '', 'image/jpeg', 17, 17702, '2019-03-27 07:49:18', 0, 0, 'System', 'கோடுயர் பன்மலை யிறந்தன ராயினு<br/>\r\nநீட விடுமோ மற்றே நீடுநினைந்து<br/>\r\nதுடைத்தொறுந் துடைத்தொறுங் கலங்கி<br/>\r\nயுடைத்தெழு வெள்ள மாகிய கண்ணே', 1, 0),
(17705, 357, '100.jpg', '', 'image/jpeg', 17, 17702, '2019-03-27 07:49:18', 0, 0, 'System', 'குரவ மலர மரவம் பூப்பச்<br/>\r\nசுரனணி கொண்ட கானங் காணூஉ<br/>\r\nவழுங்குக செய்பொருட் செலவென விரும்பிநின்<br/>\r\nனங்கலிழ் மாமை கவின<br/>\r\nவந்தனர் தோழிநங் காத லோரே', 1, 0),
(17704, 356, '100.jpg', '', 'image/jpeg', 17, 17702, '2019-03-27 07:49:18', 0, 0, 'System', 'உள்ளுதற் கினிய மன்ற செல்வர்<br/>\r\nயானை பிணித்த பொன்புனை கயிற்றி<br/>\r\nனொள்ளெரி மேய்ந்த சுரத்திடை<br/>\r\nயுள்ளம் வாங்கத் தந்தநின் குணனே', 1, 0),
(17703, 355, '100.jpg', '', 'image/jpeg', 17, 17702, '2019-03-27 07:49:18', 0, 0, 'System', 'திருந்திழை யரிவை நின்னல முள்ளி<br/>\r\nயருஞ்செயற் பொருட்பிணி பெருந்திரு வுறுகெனச்<br/>\r\nசொல்லாது பெயர்தந் தேனே பல்பொறிச்<br/>\r\nசிறுகண் யானை திரிதரு<br/>\r\nநெறிவிலங் கதர கானத் தானே', 1, 0),
(17702, 354, '100.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 07:49:18', 0, 0, 'System', 'ஈர்ம்பிணவு புணர்ந்த செந்நா யேற்றை<br/>\r\nமறியுடை மான்பிணை கொள்ளாது கழியு<br/>\r\nமரிய சுரன்வந் தனரே<br/>\r\nதெரியிழை யரிவைநின் பண்புதர விரைந்தே', 1, 0),
(17701, 353, '99.jpg', '', 'image/jpeg', 17, 17692, '2019-03-27 07:47:21', 0, 0, 'System', 'எரிக்கொடிக் கவைஇய செவ்வரை போலச்<br/>\r\nசுடர்ப்பூண் விளங்கு மேந்தெழி லகல<br/>\r\nநீயினிது முயங்க வந்தனர்<br/>\r\nமாயிருஞ் சோலை மலையிறந் தோரே', 1, 0),
(17700, 352, '99.jpg', '', 'image/jpeg', 17, 17692, '2019-03-27 07:47:21', 0, 0, 'System', 'விழுத்தொடை மறவர் வில்லிடத் தொலைந்தோ<br/>\r\nரெழுத்துடை நடுக லன்ன விழுப்பிணர்ப்<br/>\r\nபெருங்கை யானை யிருஞ்சின முறைக்கும்<br/>\r\nவெஞ்சுர மரிய வென்னார்<br/>\r\nவந்தனர் தோழிநங் காத லோரே', 1, 0),
(17699, 351, '99.jpg', '', 'image/jpeg', 17, 17692, '2019-03-27 07:47:21', 0, 0, 'System', 'அத்தப் பலவின் வெயிறின் சிறுகா<br/>\r\nயருஞ் சுரஞ் செல்வோ ரருந்தினர் கழியுங்<br/>\r\nகாடுபின் னொழிய வந்தனர் தீர்கினிப்<br/>\r\nபல்லித ழுண்கண் மடந்தைநின்<br/>\r\nனல்லெழி லல்குல் வாடிய நிலையே', 1, 0),
(17698, 350, '99.jpg', '', 'image/jpeg', 17, 17692, '2019-03-27 07:47:21', 0, 0, 'System', 'அவரோ வாரார் தான்வந் தன்றே<br/>\r\nவேம்பி னொண்பூ வுறைப்பத்<br/>\r\nதேம்படு கிளவியவர் தெளிக்கும் பொழுதே', 1, 0),
(17697, 349, '99.jpg', '', 'image/jpeg', 17, 17692, '2019-03-27 07:47:21', 0, 0, 'System', 'அவரோ வாரார் தான்வந் தன்றே<br/>\r\nபொரிகான் மாஞ்சினை புதைய<br/>\r\nவெரிகா லிளந்தளி ரீனும் பொழுதே', 1, 0),
(17695, 347, '99.jpg', '', 'image/jpeg', 17, 17692, '2019-03-27 07:47:21', 0, 0, 'System', 'அவரோ வாரார் தான்வந் தன்றே<br/>\r\nயெழிற்றகை யிளமுலை பொலியப்<br/>\r\nபொரிப்பூம் புன்கின் முறிதிமிர் பொழுதே', 1, 0),
(17696, 348, '99.jpg', '', 'image/jpeg', 17, 17692, '2019-03-27 07:47:21', 0, 0, 'System', 'அவரோ வாரார் தான்வந் தன்றே<br/>\r\nவலஞ்சுரி மராஅம் வேய்ந்துநம்<br/>\r\nமணங்கமழ் தண்பொழின் மலரும் பொழுதே', 1, 0),
(17694, 346, '99.jpg', '', 'image/jpeg', 17, 17692, '2019-03-27 07:47:21', 0, 0, 'System', 'அவரோ வாரார் தான்வந் தன்றே<br/>\r\nயஞ்சினைப் பாதிரி யலர்ந்தெனச்<br/>\r\nசெங்க ணிருங்குயி லறையும் பொழுதே', 1, 0),
(17693, 345, '99.jpg', '', 'image/jpeg', 17, 17692, '2019-03-27 07:47:21', 0, 0, 'System', 'அவரோ வாரார் தான்வந் தன்றே<br/>\r\nபுதுப்பூ வதிர றாஅய்க்<br/>\r\nகதுப்பற லணியுங் காமர் பொழுதே', 1, 0),
(17692, 344, '99.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 07:47:21', 0, 0, 'System', 'அவரோ வாரார் தான்வந் தன்றே<br/>\r\nநறும்பூங் குரவம் பயந்த<br/>\r\nசெய்யாப் பாவை கொய்யும் பொழுதே', 1, 0),
(17690, 342, '98.jpg', '', 'image/jpeg', 17, 17686, '2019-03-27 07:43:50', 0, 0, 'System', 'அவரோ வாரார் தான்வந் தன்றே<br/>\r\nசுரும்புகளித் தாலு மிருஞ்சினைக்<br/>\r\nகருங்கா னுணவங் கமழும் பொழுதே', 1, 0),
(17691, 343, '98.jpg', '', 'image/jpeg', 17, 17686, '2019-03-27 07:43:50', 0, 0, 'System', 'அவரோ வாரார் தான்வந் தன்றே<br/>\r\nதிணிநிலைக் கோங்கம் பயந்த<br/>\r\nவணிமிகு கொழுமுகை யுடையும் பொழுதே', 1, 0),
(17689, 341, '98.jpg', '', 'image/jpeg', 17, 17686, '2019-03-27 07:43:50', 0, 0, 'System', 'அவரோ வாரார் தான்வந் தன்றே<br/>\r\nகுயிற்பெடை யின்குர லகவ<br/>\r\nவயிர்க்கேழ் நுண்ணற னுடங்கு பொழுதே', 1, 0),
(17688, 340, '98.jpg', '', 'image/jpeg', 17, 17686, '2019-03-27 07:43:50', 0, 0, 'System', 'அம்ம வாழி தோழி காதல<br/>\r\nருள்ளார் கொன்னா மருளுற்  றனங்கொல்<br/>\r\nவிட்டுச் சென்றனர் நம்மே<br/>\r\nதட்டைத் தீயி னூரல ரெழவே', 1, 0),
(17687, 339, '98.jpg', '', 'image/jpeg', 17, 17686, '2019-03-27 07:43:50', 0, 0, 'System', 'அம்ம வாழி தோழி சிறியிலைக்<br/>\r\nகுறுஞ்சினை வேம்பி னறும்பழ முணீஇய<br/>\r\nவாவ லுகக்கு மாலையு<br/>\r\nமின்றுகொல் காதலவர் சென்ற நாட்டே', 1, 0),
(17686, 338, '98.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 07:43:50', 0, 0, 'System', 'அம்ம வாழி தோழி சார<br/>\r\nலிலையில மலர்ந்த வோங்குநிலை யிலவ<br/>\r\nமலையுறு தீயிற் சுரமுதற் றோன்றும்<br/>\r\nபிரிவருங் காலையும் பிரித<br/>\r\nலரிது வல் லுநநங் காத லோரே', 1, 0),
(17685, 337, '97.jpg', '', 'image/jpeg', 17, 17680, '2019-03-27 07:41:37', 0, 0, 'System', 'அம்ம வாழி தோழி நம்வயின்<br/>\r\nமெய்யுற விரும்பிய கைகவர் முயக்கினு<br/>\r\nமினிய மன்ற தாமே<br/>\r\nபனியிருங் குன்றஞ்சென் றோர்க்குப் பொருளே', 1, 0),
(17684, 336, '97.jpg', '', 'image/jpeg', 17, 17680, '2019-03-27 07:41:37', 0, 0, 'System', 'அம்ம வாழி தோழி நம்வயிற்<br/>\r\nபிரியலர் போலப் புணர்ந்தோர் மன்ற<br/>\r\nநின்றதில் பொருட்பிணி முற்றிய<br/>\r\nவென்றூழ் நீடிய சுரனிறந் தோரே', 1, 0),
(17683, 335, '97.jpg', '', 'image/jpeg', 17, 17680, '2019-03-27 07:41:37', 0, 0, 'System', 'அம்ம வாழி தோழி நம்வயி<br/>\r\nனெய்த்தோ ரன்ன செவிய வெருவை<br/>\r\nகற்புடை மருங்கிற் கடுமுடை யார்க்குங்<br/>\r\nகாடுநனி கடிய வென்ப<br/>\r\nநீடியிவண் வருநர் சென்ற வாறே', 1, 0),
(17682, 334, '97.jpg', '', 'image/jpeg', 17, 17680, '2019-03-27 07:41:37', 0, 0, 'System', 'அம்ம வாழி தோழி சிறியிலை<br/>\r\nநெல்லி நீடிய கல்காய் கடத்திடைப்<br/>\r\nபேதை நெஞ்சம் பின்செலச் சென்றோர்<br/>\r\nகல்லினும் வலியர் மன்ற<br/>\r\nபல்லித ழுண்க ணழப்பிரிந் தோரே', 1, 0),
(17681, 333, '97.jpg', '', 'image/jpeg', 17, 17680, '2019-03-27 07:41:37', 0, 0, 'System', 'அம்ம வாழி தோழி யாவதும்<br/>\r\nவல்லா கொல்லோ தாமே யவண<br/>\r\nகல்லுடை நன்னாட்டுப் புள்ளினப் பெருந்தோ<br/>\r\nடியாஅந் துணைபுணர்ந் துறைதும்<br/>\r\nயாங்குப் பிரிந் துறைதி யென்னா தவ்வே', 1, 0),
(17680, 332, '97.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 07:41:37', 0, 0, 'System', 'அம்ம வாழி தோழி யென்னதூஉம்<br/>\r\nமறனில மன்ற தாமே விறன்மிசைக்<br/>\r\nகுன்றுகெழு கானத்த பண்பின் மாக்கணங்<br/>\r\nகொடிதே காதலிப் பிரிதல்<br/>\r\nசெல்ல லைய வென்னா தவ்வே', 1, 0),
(17679, 331, '96.jpg', '', 'image/jpeg', 17, 17675, '2019-03-27 07:39:21', 0, 0, 'System', 'அம்ம வாழி தோழி யவிழிணர்க்<br/>\r\nகருங்கான் மராஅத்து வைகுசினை வான்பூ<br/>\r\nவருஞ்சுரஞ் செல்லுந ரொழிந்தோ ருள்ள<br/>\r\nவினிய கமழும் வெற்பி<br/>\r\nனின்னா தென்பவவர் சென்ற வாறே', 1, 0),
(17678, 330, '96.jpg', '', 'image/jpeg', 17, 17675, '2019-03-27 07:39:21', 0, 0, 'System', 'வெந்துக ளாகிய வெயிற்கட நீந்தி<br/>\r\nவந்தன மாயினு மொழிகினிச் செலவே<br/>\r\nயழுத கண்ண ளாய்நலஞ் சிதையக்<br/>\r\nகதிர்தெறு வெஞ்சுர நினைக்கு<br/>\r\nமவிர்கோ லாய்தொடி யுள்ளத்துப் படரே', 1, 0),
(17677, 329, '96.jpg', '', 'image/jpeg', 17, 17675, '2019-03-27 07:39:21', 0, 0, 'System', 'ஆள்வழக் கற்ற பாழ்படு நனந்தலை<br/>\r\nவெம்முனை யருஞ்சுர நீந்தி நம்மொடு<br/>\r\nமறுதரு வதுகொ றானே செறிதொடி<br/>\r\nகழிந்துகு நிலைய வாக<br/>\r\nவொழிந்தோள் கொண்டவெ னுரங்கெழு நெஞ்சே', 1, 0),
(17676, 328, '96.jpg', '', 'image/jpeg', 17, 17675, '2019-03-27 07:39:21', 0, 0, 'System', 'நுண்மழை தளித்தென நறுமலர் தாஅய்த்<br/>\r\nதண்ணிய வாயினும் வெய்ய மன்ற<br/>\r\nமடவர லின்றுணை யொழியக்<br/>\r\nகடமுதிர் சோலைய காடிறந் தேற்கே', 1, 0),
(17675, 327, '96.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 07:39:21', 0, 0, 'System', 'பொறிவரித் தடக்கை வேத லஞ்சிச்<br/>\r\nசிறுகண் யானை நிலந்தொடல் செல்லா<br/>\r\nவெயின்முளி சோலைய வேயுயர் சுரனே<br/>\r\nயன்ன வாரிடை யானுந்<br/>\r\nதண்மை செய்தவித் தகையோள் பண்பே', 1, 0),
(17674, 326, '95.jpg', '', '', 17, 17670, '2019-03-27 07:34:27', 0, 0, 'System', 'அழலவிர் நனந்தலை நிழலிடம் பெறாது<br/>\r\nமடமா னம்பிணை மறியொடு திரங்க<br/>\r\nநீர்மருங் கறுத்த நிரம்பா வியவி<br/>\r\nனின்னா மன்ற சுரமே<br/>\r\nயினிய மன்றயா னொழிந்தோள் பண்பே', 1, 0),
(17673, 325, '95.jpg', '', '', 17, 17670, '2019-03-27 07:34:27', 0, 0, 'System', 'வேனி லரையத் திலையொலி வொஇப்<br/>\r\nபோகில்புகா வுண்ணாது பிறிதுபுலம் படரும்<br/>\r\nவெம்பலை யருஞ்சுர நலியா<br/>\r\nதெம்வெங் காதலி பண்புதுணைப் பெற்றே', 1, 0),
(17672, 324, '95.jpg', '', '', 17, 17670, '2019-03-27 07:34:27', 0, 0, 'System', 'எரிகவர்ந் துண்ட வென்றூழ் நீளிடைச்<br/>\r\nசிறிதுகண் படுப்பினுங் காண்குவென் மன்ற<br/>\r\nநள்ளென் கங்கு னளிமனை நெடுநகர்<br/>\r\nவேங்கை வென்ற சுணங்கிற்<br/>\r\nறேம்பாய் கூந்தன் மாஅ யோளே', 1, 0),
(17671, 323, '95.jpg', '', '', 17, 17670, '2019-03-27 07:34:27', 0, 0, 'System', 'வள்ளெயிற்றுச் செந்நாய் வயவுறு பிணவிற்குக்<br/>\r\nகள்ளியங் கடத்திடைக் கேழல் பார்க்கும்<br/>\r\nவெஞ்சுரக் கவலை நீந்தி<br/>\r\nவந்த நெஞ்சநீ நயந்தோள் பண்பே', 1, 0),
(17670, 322, '95.jpg', '', '', 17, 0, '2019-03-27 07:34:27', 0, 0, 'System', 'நெடுங்கழை முளிய வேனி னீடிக்<br/>\r\nகடுங்கதிர் ஞாயிறு கல்பகத் தெறுதலின்<br/>\r\nவெய்ய வாயின முன்னே யினியே<br/>\r\nயொண்ணுத லரிவையை யுள்ளுதொறுந்<br/>\r\nதண்ணிய வாயின சுரத்திடை யாறே', 1, 0),
(17669, 321, '94.jpg', '', 'image/jpeg', 17, 17666, '2019-03-27 07:31:58', 0, 0, 'System', 'உலறுதலைப் பருந்தி னுளிவாய்ப் பேடை<br/>\r\nயலறுதலை யோமை யங்கவட் டேறிப்<br/>\r\nபுலம்புகொள விளிக்கு நிலங்காய் கானத்து<br/>\r\nமொழிபெயர் பன்மலை யிறப்பினு<br/>\r\nமொழிதல் செல்லா தொண்டொடி குணனே', 1, 0),
(17668, 320, '94.jpg', '', 'image/jpeg', 17, 17666, '2019-03-27 07:31:58', 0, 0, 'System', 'முள்ளரை யிலவத் தொள்ளிணர் வான்பூ<br/>\r\nமுழங்கழ லசைவளி யெடுப்ப வானத்<br/>\r\nதுருமுப்படு கனலி னிருநிலத் துறைக்குங்<br/>\r\nகவலை யருஞ்சுரம் போயினர்<br/>\r\nதவலி லருநோய் தலைத்தந் தோரே', 1, 0),
(17667, 319, '94.jpg', '', 'image/jpeg', 17, 17666, '2019-03-27 07:31:58', 0, 0, 'System', 'கண்பொர விளங்கிய கதிர்தெறு வைப்பின்<br/>\r\nமண்புரை பெருகிய மரமுளி கான<br/>\r\nமிறந்தன ரோநங் காதலர்<br/>\r\nமறந்தன ரோதின் மறவா நம்மே', 1, 0),
(17666, 318, '94.jpg', '', 'image/jpeg', 17, 0, '2019-03-27 07:31:58', 0, 0, 'System', 'ஆய்நலம் பசப்ப வரும்படர் நலிய<br/>\r\nவேய்மருள் பணைத்தோள் வில்லிழை நெகிழ<br/>\r\nநசைநனி கொன்றோர் மன்ற விசைநிமிர்ந்<br/>\r\nதோடெரி நடந்த வைப்பிற்<br/>\r\nகோடுயர் பிறங்கன் மலையிறந் தோரே', 1, 0),
(17665, 317, '93.jpg', '', 'image/jpeg', 17, 17661, '2019-03-27 07:30:22', 0, 0, 'System', 'சூழ்கம் வம்மோ தோழிபாழ் பட்டுப்<br/>\r\nபைதற வெந்த பாலை வெங்காட்<br/>\r\nடருஞ்சுர மிறந்தோர் தேஎத்துச்<br/>\r\nசென்ற நெஞ்ச நீடிய பொருளே', 1, 0),
(17664, 316, '93.jpg', '', 'image/jpeg', 17, 17661, '2019-03-27 07:30:22', 0, 0, 'System', 'பொன்செய் பாண்டிற் பொலங்கல நந்தத்<br/>\r\nதேரக லல்கு லவ்வரி வாட<br/>\r\nவிறந்தோர் மன்ற தாமே பிறங்குமலைப்<br/>\r\nபுல்லரை யோமை நீடிய<br/>\r\nபுலிவழங் கதர கானத் தானே', 1, 0),
(17663, 315, '93.jpg', '', 'image/jpeg', 17, 17661, '2019-03-27 07:30:22', 0, 0, 'System', 'பாயல் கொண்ட பனிமலர் நெடுங்கட்<br/>\r\nபூசல் கேளார் சேய ரென்ப<br/>\r\nவிழைநெகிழ் செல்ல லுறீஇக்<br/>\r\nகழைமுதிர் சோலைக் காடிறந் தோரே', 1, 0),
(17662, 314, '93.jpg', '', 'image/jpeg', 17, 17661, '2019-03-27 07:30:22', 0, 0, 'System', 'அவிர்தொடி கொட்பக் கழுதுபுக வயரக்<br/>\r\nகருங்கட் காக்கையொடு கழுகுவிசும் பகவச்<br/>\r\nசிறுகண் யானை யாள்வீழ்த்துத் திரிதரு<br/>\r\nநீளிடை யருஞ்சுர மென்பநந்<br/>\r\nதோளிடை முனிநர் சென்ற வாறே', 1, 0),
