(18884, 244, '27.jpg', '', 'image/jpeg', 23, 18881, '2020-11-19 12:11:30', 0, 0, 'System', 'மன்னுயிர் ஓம்பி அருளாள்வார்க்கு இல்லென்ப<br/>\r\nதன்னுயிர் அஞ்சும் வினை', 1, 0),
(18885, 245, '27.jpg', '', 'image/jpeg', 23, 18881, '2020-11-19 12:11:30', 0, 0, 'System', 'அல்லல் அருளாள்வார்க்கு இல்லை வளிவழங்கும்<br/>\r\nமல்லன்மா ஞாலங் கரி', 1, 0),
(18886, 246, '27.jpg', '', 'image/jpeg', 23, 18881, '2020-11-19 12:11:30', 0, 0, 'System', 'பொருள்நீங்கிப் பொச்சாந்தார் என்பர் அருள்நீங்கி<br/>\r\nஅல்லவை செய்தொழுகு வார்', 1, 0),
(18887, 247, '27.jpg', '', 'image/jpeg', 23, 18881, '2020-11-19 12:11:30', 0, 0, 'System', 'அருளில்லார்க்கு அவ்வுலகம் இல்லை பொருளில்லார்க்கு<br/>\r\nஇவ்வுலகம் இல்லாகி யாங்கு', 1, 0),
(18888, 248, '27.jpg', '', 'image/jpeg', 23, 18881, '2020-11-19 12:11:30', 0, 0, 'System', 'பொருளற்றார் பூப்பர் ஒருகால் அருளற்றார்<br/>\r\nஅற்றார்மற் றாதல் அரிது', 1, 0),
(18889, 249, '27.jpg', '', 'image/jpeg', 23, 18881, '2020-11-19 12:11:30', 0, 0, 'System', 'தெருளாதான் மெய்ப்பொருள் கண்டற்றால் தேரின்<br/>\r\nஅருளாதான் செய்யும் அறம்', 1, 0),
(18890, 250, '27.jpg', '', 'image/jpeg', 23, 18881, '2020-11-19 12:11:30', 0, 0, 'System', 'வலியார்முன் தன்னை நினைக்கதான் தன்னின்<br/>\r\nமெலியார்மேல் செல்லு மிடத்து', 1, 0),
(18891, 251, '28.jpg', '', 'image/jpeg', 23, 0, '2020-11-19 02:34:50', 0, 0, 'System', 'தன்னூன் பெருக்கற்குத் தான்பிறிது ஊனுண்பான்<br/>\r\nஎங்ஙனம் ஆளும் அருள்', 1, 0),
(18892, 252, '28.jpg', '', 'image/jpeg', 23, 18891, '2020-11-19 02:34:50', 0, 0, 'System', 'பொருளாட்சி போற்றாதார்க்கு இல்லை அருளாட்சி<br/>\r\nஆங்கில்லை ஊன்தின் பவர்க்கு', 1, 0),
(18893, 253, '28.jpg', '', 'image/jpeg', 23, 18891, '2020-11-19 02:34:50', 0, 0, 'System', 'படைகொண்டார் நெஞ்சம்போல் நன்னூக்காது ஒன்றன்<br/>\r\nஉடல்சுவை உண்டார் மனம்', 1, 0),
(18894, 254, '28.jpg', '', 'image/jpeg', 23, 18891, '2020-11-19 02:34:50', 0, 0, 'System', 'அருளல்லது யாதெனின் கொல்லாமை கோறல்<br/>\r\nபொருளல்லது அவ்வூன் தினல்', 1, 0),
(18895, 255, '28.jpg', '', 'image/jpeg', 23, 18891, '2020-11-19 02:34:50', 0, 0, 'System', 'உண்ணாமை உள்ளது உயிர்நிலை ஊனுண்ண<br/>\r\nஅண்ணாத்தல் செய்யாது அளறு', 1, 0),
(18896, 256, '28.jpg', '', 'image/jpeg', 23, 18891, '2020-11-19 02:34:50', 0, 0, 'System', 'தினற்பொருட்டால் கொல்லாது உலகெனின் யாரும்<br/>\r\nவிலைப்பொருட்டால் ஊன்றருவா ரில்', 1, 0),
(18897, 257, '28.jpg', '', 'image/jpeg', 23, 18891, '2020-11-19 02:34:50', 0, 0, 'System', 'உண்ணாமை வேண்டும் புலாஅல் பிறிதொன்றன்<br/>\r\nபுண்ணது உணர்வார்ப் பெறின்', 1, 0),
(18898, 258, '28.jpg', '', 'image/jpeg', 23, 18891, '2020-11-19 02:34:50', 0, 0, 'System', 'செயிரின் தலைப்பிரிந்த காட்சியார் உண்ணார்<br/>\r\nஉயிரின் தலைப்பிரிந்த ஊன்', 1, 0),
(18899, 259, '28.jpg', '', 'image/jpeg', 23, 18891, '2020-11-19 02:34:50', 0, 0, 'System', 'அவிசொரிந் தாயிரம் வேட்டலின் ஒன்றன்<br/>\r\nஉயிர்செகுத் துண்ணாமை நன்று', 1, 0),
(18900, 260, '28.jpg', '', 'image/jpeg', 23, 18891, '2020-11-19 02:34:50', 0, 0, 'System', 'கொல்லான் புலாலை மறுத்தானைக் கைகூப்பி<br/>\r\nஎல்லா உயிருந் தொழும்', 1, 0),
(18901, 261, '29.jpg', '', 'image/jpeg', 23, 0, '2020-11-19 03:12:06', 0, 0, 'System', 'உற்றநோய் நோன்றல் உயிர்க்குறுகண் செய்யாமை<br/>\r\nஅற்றே தவத்திற் குரு', 1, 0),
(18902, 262, '29.jpg', '', 'image/jpeg', 23, 18901, '2020-11-19 03:12:06', 0, 0, 'System', 'தவமும் தவமுடையார்க்கு ஆகும் அதனை<br/>\r\nஅஃதிலார் மேற்கொள் வது', 1, 0),
(18903, 263, '29.jpg', '', 'image/jpeg', 23, 18901, '2020-11-19 03:12:06', 0, 0, 'System', 'துறந்தார்க்குத் துப்புரவு வேண்டி மறந்தார்கொல்<br/>\r\nமற்றை யவர்கள் தவம்', 1, 0),
(18904, 264, '29.jpg', '', 'image/jpeg', 23, 18901, '2020-11-19 03:12:06', 0, 0, 'System', 'ஒன்னார்த் தெறலும் உவந்தாரை ஆக்கலும்<br/>\r\nஎண்ணின் தவத்தான் வரும்', 1, 0),
(18905, 265, '29.jpg', '', 'image/jpeg', 23, 18901, '2020-11-19 03:12:06', 0, 0, 'System', 'வேண்டிய வேண்டியாங் கெய்தலால் செய்தவம்<br/>\r\nஈண்டு முயலப் படும்', 1, 0),
(18906, 266, '29.jpg', '', 'image/jpeg', 23, 18901, '2020-11-19 03:12:06', 0, 0, 'System', 'தவஞ்செய்வார் தங்கருமஞ் செய்வார்மற் றல்லார்<br/>\r\nஅவஞ்செய்வார் ஆசையுட் பட்டு', 1, 0),
(18907, 267, '29.jpg', '', 'image/jpeg', 23, 18901, '2020-11-19 03:12:06', 0, 0, 'System', 'சுடச்சுடரும் பொன்போல் ஒளிவிடும் துன்பஞ்<br/>\r\nசுடச்சுட நோற்கிற் பவர்க்கு', 1, 0),
(18908, 268, '29.jpg', '', 'image/jpeg', 23, 18901, '2020-11-19 03:12:06', 0, 0, 'System', 'தன்னுயிர் தான்அறப் பெற்றானை ஏனைய<br/>\r\nமன்னுயி ரெல்லாந் தொழும்', 1, 0),
(18909, 269, '29.jpg', '', 'image/jpeg', 23, 18901, '2020-11-19 03:12:06', 0, 0, 'System', 'கூற்றம் குதித்தலும் கைகூடும் நோற்றலின்<br/>\r\nஆற்றல் தலைப்பட் டவர்க்குல்', 1, 0);
INSERT INTO `sv_songs` (`id`, `fid`, `fname`, `filename`, `filetype`, `cid`, `group_id`, `upload_date`, `down_counts`, `view_counts`, `author`, `description`, `status`, `trash`) VALUES
(18910, 270, '29.jpg', '', 'image/jpeg', 23, 18901, '2020-11-19 03:12:06', 0, 0, 'System', 'இலர்பல ராகிய காரணம் நோற்பார்<br/>\r\nசிலர்பலர் நோலா தவர்', 1, 0),
(18911, 271, '30.jpg', '', 'image/jpeg', 23, 0, '2020-11-19 03:53:44', 0, 0, 'System', 'வஞ்ச மனத்தான் படிற்றொழுக்கம் பூதங்கள்<br/>\r\nஐந்தும் அகத்தே நகும்', 1, 0),
(18912, 272, '30.jpg', '', 'image/jpeg', 23, 18911, '2020-11-19 03:53:44', 0, 0, 'System', 'வானுயர் தோற்றம் எவன்செய்யும் தன்னெஞ்சம்<br/>\r\nதான்அறி குற்றப் படின்', 1, 0),
(18913, 273, '30.jpg', '', 'image/jpeg', 23, 18911, '2020-11-19 03:53:44', 0, 0, 'System', 'வலியில் நிலைமையான் வல்லுருவம் பெற்றம்<br/>\r\nபுலியின்தோல் போர்த்துமேய்ந் தற்று', 1, 0),
(18914, 274, '30.jpg', '', 'image/jpeg', 23, 18911, '2020-11-19 03:53:44', 0, 0, 'System', 'தவமறைந்து அல்லவை செய்தல் புதல்மறைந்து<br/>\r\nவேட்டுவன் புள்சிமிழ்த் தற்று', 1, 0),
(18915, 275, '30.jpg', '', 'image/jpeg', 23, 18911, '2020-11-19 03:53:44', 0, 0, 'System', 'பற்றற்றேம் என்பார் படிற்றொழுக்கம் எற்றெற்றென்று<br/>\r\nஏதம் பலவுந் தரும்', 1, 0),
(18916, 276, '30.jpg', '', 'image/jpeg', 23, 18911, '2020-11-19 03:53:44', 0, 0, 'System', 'நெஞ்சின் துறவார் துறந்தார்போல் வஞ்சித்து<br/>\r\nவாழ்வாரின் வன்கணார் இல்', 1, 0),
(18917, 277, '30.jpg', '', 'image/jpeg', 23, 18911, '2020-11-19 03:53:44', 0, 0, 'System', 'புறங்குன்றி கண்டனைய ரேனும் அகங்குன்றி<br/>\r\nமுக்கிற் கரியார் உடைத்து', 1, 0),
(18918, 278, '30.jpg', '', 'image/jpeg', 23, 18911, '2020-11-19 03:53:44', 0, 0, 'System', 'மனத்தது மாசாக மாண்டார் நீராடி<br/>\r\nமறைந்தொழுகு மாந்தர் பலர்', 1, 0),
(18919, 279, '30.jpg', '', 'image/jpeg', 23, 18911, '2020-11-19 03:53:44', 0, 0, 'System', 'கணைகொடிது யாழ்கோடு செவ்விதுஆங் கன்ன<br/>\r\nவினைபடு பாலால் கொளல்', 1, 0),
(18920, 280, '30.jpg', '', 'image/jpeg', 23, 18911, '2020-11-19 03:53:44', 0, 0, 'System', 'மழித்தலும் நீட்டலும் வேண்டா உலகம்<br/>\r\nபழித்தது ஒழித்து விடின்', 1, 0),
(18921, 281, '31.jpg', '', 'image/jpeg', 23, 0, '2020-11-19 05:22:39', 0, 0, 'System', 'எள்ளாமை வேண்டுவான் என்பான் எனைத்தொன்றும்<br/>\r\nகள்ளாமை காக்கதன் நெஞ்சு', 1, 0),
(18922, 282, '31.jpg', '', 'image/jpeg', 23, 18921, '2020-11-19 05:22:39', 0, 0, 'System', 'உள்ளத்தால் உள்ளலும் தீதே பிறன்பொருளைக்<br/>\r\nகள்ளத்தால் கள்வேம் எனல்', 1, 0),
(18923, 283, '31.jpg', '', 'image/jpeg', 23, 18921, '2020-11-19 05:22:39', 0, 0, 'System', 'களவினால் ஆகிய ஆக்கம் அளவிறந்து<br/>\r\nஆவது போலக் கெடும்', 1, 0),
(18924, 284, '31.jpg', '', 'image/jpeg', 23, 18921, '2020-11-19 05:22:39', 0, 0, 'System', 'களவின்கண் கன்றிய காதல் விளைவின்கண்<br/>\r\nவீயா விழுமம் தரும்', 1, 0),
(18925, 285, '31.jpg', '', 'image/jpeg', 23, 18921, '2020-11-19 05:22:39', 0, 0, 'System', 'அருள்கருதி அன்புடைய ராதல் பொருள்கருதிப்<br/>\r\nபொச்சாப்புப் பார்ப்பார்கண் இல்', 1, 0),
(18926, 286, '31.jpg', '', 'image/jpeg', 23, 18921, '2020-11-19 05:22:39', 0, 0, 'System', 'அளவின்கண் நின்றொழுகல் ஆற்றார் களவின்கண்<br/>\r\nகன்றிய காத லவர்', 1, 0),
(18927, 287, '31.jpg', '', 'image/jpeg', 23, 18921, '2020-11-19 05:22:39', 0, 0, 'System', 'களவென்னும் காரறி வாண்மை அளவென்னும்<br/>\r\nஆற்றல் புரிந்தார்கண்ட இல்', 1, 0),
(18928, 288, '31.jpg', '', 'image/jpeg', 23, 18921, '2020-11-19 05:22:39', 0, 0, 'System', 'அளவறாந்தார் நெஞ்சத் தறம்போல நிற்கும்<br/>\r\nகளவறிந்தார் நெஞ்சில் கரவு', 1, 0),
(18929, 289, '31.jpg', '', 'image/jpeg', 23, 18921, '2020-11-19 05:22:39', 0, 0, 'System', 'அளவல்ல செய்தாங்கே வீவர் களவல்ல<br/>\r\nமற்றைய தேற்றா தவர்', 1, 0),
(18930, 290, '31.jpg', '', 'image/jpeg', 23, 18921, '2020-11-19 05:22:39', 0, 0, 'System', 'கள்வார்க்குத் தள்ளும் உயிர்நிலை கள்வார்க்குத்<br/>\r\nதள்ளாது புத்தே ளுளகு', 1, 0),
(18931, 291, '32.jpg', '', 'image/jpeg', 23, 0, '2020-11-19 05:27:21', 0, 0, 'System', 'வாய்மை எனப்படுவது யாதெனின் யாதொன்றும்<br/>\r\nதீமை இலாத சொலல்', 1, 0),
(18932, 292, '32.jpg', '', 'image/jpeg', 23, 18931, '2020-11-19 05:27:21', 0, 0, 'System', 'பொய்மையும் வாய்மை யிடத்த புரைதீர்ந்த<br/>\r\nநன்மை பயக்கும் எனின்', 1, 0),
(18933, 293, '32.jpg', '', 'image/jpeg', 23, 18931, '2020-11-19 05:27:21', 0, 0, 'System', 'தன்நெஞ் சறிவது பொய்யற்க பொய்த்தபின்<br/>\r\nதன்நெஞ்சே தன்னைச் சுடும்', 1, 0),
(18934, 294, '32.jpg', '', 'image/jpeg', 23, 18931, '2020-11-19 05:27:21', 0, 0, 'System', 'உள்ளத்தாற் பொய்யா தொழுகின் உலகத்தார்<br/>\r\nஉள்ளத்து ளெல்லாம் உளன்', 1, 0),
(18935, 295, '32.jpg', '', 'image/jpeg', 23, 18931, '2020-11-19 05:27:21', 0, 0, 'System', 'மனத்தொடு வாய்மை மொழியின் தவத்தொடு<br/>\r\nதானஞ்செய் வாரின் தலை', 1, 0),
