(19524, 628, '65.jpg', '', 'image/jpeg', 23, 19517, '2021-05-29 08:28:20', 0, 0, 'System', 'இன்பம் விழையான் இடும்பை இயல்பென்பான்<br/>\r\nதுன்பம் உறுதல் இலன்', 1, 0),
(19525, 629, '65.jpg', '', 'image/jpeg', 23, 19517, '2021-05-29 08:28:20', 0, 0, 'System', 'இன்பத்துள் இன்பம் விழையாதான் துன்பத்துள்<br/>\r\nதுன்பம் உறுதல் இலன்', 1, 0),
(19526, 630, '65.jpg', '', 'image/jpeg', 23, 19517, '2021-05-29 08:28:20', 0, 0, 'System', 'இன்னாமை இன்பம் எனக்கொளின் ஆகுந்தன்<br/>\r\nஒன்னார் விழையுஞ் சிறப்பு', 1, 0),
(19527, 631, '66.jpg', '', 'image/jpeg', 23, 0, '2021-05-29 08:36:12', 0, 0, 'System', 'கருவியும் காலமும் செய்கையும் செய்யும்<br/>\r\nஅருவினையும் மாண்டது அமைச்சு', 1, 0),
