(19849, 953, '98.jpg', '', 'image/jpeg', 23, 19847, '2021-07-16 03:00:28', 0, 0, 'System', 'நகைஈகை இன்சொல் இகழாமை நான்கும்<br/>\r\nவகையென்ப வாய்மைக் குடிக்கு', 1, 0),
(19850, 954, '98.jpg', '', 'image/jpeg', 23, 19847, '2021-07-16 03:00:28', 0, 0, 'System', 'அடுக்கிய கோடி பெறினும் குடிப்பிறந்தார்<br/>\r\nகுன்றுவ செய்தல் இலர்', 1, 0),
(19851, 955, '98.jpg', '', 'image/jpeg', 23, 19847, '2021-07-16 03:00:28', 0, 0, 'System', 'வழங்குவ துள்வீழ்ந்தக் கண்ணும் பழங்குடி<br/>\r\nபண்பில் தலைப்பிரிதல் இன்று', 1, 0),
(19852, 956, '98.jpg', '', 'image/jpeg', 23, 19847, '2021-07-16 03:00:28', 0, 0, 'System', 'சலம்பற்றிச் சால்பில செய்யார்மா சற்ற<br/>\r\nகுலம்பற்றி வாழ்தும் என்பார்', 1, 0),
(19853, 957, '98.jpg', '', 'image/jpeg', 23, 19847, '2021-07-16 03:00:28', 0, 0, 'System', 'குடிப்பிறந்தார் கண்விளங்கும் குற்றம் விசும்பின்<br/>\r\nமதிக்கண் மறுப்போல் உயர்ந்து', 1, 0),
(19854, 958, '98.jpg', '', 'image/jpeg', 23, 19847, '2021-07-16 03:00:28', 0, 0, 'System', 'நலத்தின்கண் நாரின்மை தோன்றின் அவனைக்<br/>\r\nகுலத்தின்கண் ஐயப் படும்', 1, 0),
(19855, 959, '98.jpg', '', 'image/jpeg', 23, 19847, '2021-07-16 03:00:28', 0, 0, 'System', 'நிலத்தில் கிடந்தமை கால்காட்டும் காட்டும்<br/>\r\nகுலத்தில் பிறந்தார்வாய்ச் சொல்', 1, 0),
(19856, 960, '98.jpg', '', 'image/jpeg', 23, 19847, '2021-07-16 03:00:28', 0, 0, 'System', 'நலம்வேண்டின் நாணுடைமை வேண்டும் குலம்வேண்டின்<br/>\r\nவேண்டுக யார்க்கும் பணிவு', 1, 0),
(19857, 961, '99.jpg', '', 'image/jpeg', 23, 0, '2021-07-16 03:06:58', 0, 0, 'System', 'இன்றி அமையாச் சிறப்பின ஆயினும்<br/>\r\nகுன்ற வருப விடல்', 1, 0),
(19858, 962, '99.jpg', '', 'image/jpeg', 23, 19857, '2021-07-16 03:06:58', 0, 0, 'System', 'சீரினும் சீரல்ல செய்யாரே சீரொடு<br/>\r\nபேராண்மை வேண்டு பவர்', 1, 0);
