(20598, 747, '145.jpg', '', 'image/jpeg', 25, 20594, '2023-05-19 05:10:22', 0, 0, 'System', 'மற்றுஎன் கிளவி வினைமாற்று அசைநிலை<br/>\r\nஅப்பால் இரண்டுஎன மொழிமனார் புலவர்', 1, 0),
(20599, 748, '146.jpg', '', 'image/jpeg', 25, 0, '2023-05-19 05:11:48', 0, 0, 'System', 'எற்றுஎன் கிளவி இறந்த பொருட்டே', 1, 0),
(20600, 749, '146.jpg', '', 'image/jpeg', 25, 20599, '2023-05-19 05:11:48', 0, 0, 'System', 'மற்றையது என்னும் கிளவி தானே<br/>\r\nசுட்டுநிலை ஒழிய இனம்குறித் தன்றே', 1, 0),
(20601, 750, '146.jpg', '', 'image/jpeg', 25, 20599, '2023-05-19 05:11:48', 0, 0, 'System', 'மன்றஎன் கிளவி தேற்றம் செய்யும்', 1, 0),
(20602, 751, '146.jpg', '', 'image/jpeg', 25, 20599, '2023-05-19 05:11:48', 0, 0, 'System', 'தஞ்சக் கிளவி எண்மைப் பொருட்டே', 1, 0),
(20603, 752, '146.jpg', '', 'image/jpeg', 25, 20599, '2023-05-19 05:11:48', 0, 0, 'System', 'அந்தில் ஆங்கு அசைநிலைக் கிளவிஎன்று<br/>\r\nஆயிரண்டு ஆகும் இயற்கைத்து என்ப', 1, 0),
