(21907, 1571, '86a.jpg', '', 'image/jpeg', 27, 21905, '2023-08-07 02:27:11', 0, 0, 'System', 'குரங்கின் ஏற்றினைக் கடுவன் என்றலும் <br/>\r\nமரம் பயில் கூகையைக் கோட்டான் என்றலும் <br/>\r\nசெவ் வாய்க் கிள்ளையைத் தத்தை என்றலும் <br/>\r\nவெவ் வாய் வெருகினைப் பூசை என்றலும் <br/>\r\nகுதிரையுள் ஆணினைச் சேவல் என்றலும் <br/>\r\nஇருள் நிறப் பன்றியை ஏனம் என்றலும் <br/>\r\nஎருமையுள் ஆணினைக் கண்டி என்றலும்<br/> \r\nமுடிய வந்த வழக்கின் உண்மையின் <br/>\r\nகடியல் ஆகா கடன் அறிந்தோர்க்கே', 1, 0),
(21908, 1572, '86a.jpg', '', 'image/jpeg', 27, 21905, '2023-08-07 02:27:11', 0, 0, 'System', 'பெண்ணும் ஆணும் பிள்ளையும் அவையே', 1, 0),
(21909, 1573, '86a.jpg', '', 'image/jpeg', 27, 21905, '2023-08-07 02:27:11', 0, 0, 'System', 'நூலே கரகம் முக்கோல் மணையே <br/>\r\nஆயும் காலை அந்தணர்க்கு உரிய', 1, 0),
(21910, 1574, '86a.jpg', '', 'image/jpeg', 27, 21905, '2023-08-07 02:27:11', 0, 0, 'System', 'படையும் குடையும் கொடியும் முரசும் <br/>\r\nநடை நவில் புரவியும் களிறும் தேரும் <br/>\r\nதாரும் முடியும் நேர்வன பிறவும் <br/>\r\nதெரிவு கொள் செங்கோல் அரசர்க்கு உரிய', 1, 0),
(21911, 1575, '86a.jpg', '', 'image/jpeg', 27, 21905, '2023-08-07 02:27:11', 0, 0, 'System', 'அந்தணாளர்க்கு உரியவும் அரசர்க்கு <br/>\r\nஒன்றிய வரூஉம் பொருளுமார் உளவே', 1, 0),
(21912, 1576, '87.jpg', '', 'image/jpeg', 27, 0, '2023-08-07 02:33:31', 0, 0, 'System', 'பரிசில் பாடாண் திணைத் துறைக் கிழமைப்பெயர் <br/>\r\nநெடுந்தகை செம்மல் என்று இவை பிறவும் <br/>\r\nபொருந்தச் சொல்லுதல் அவர்க்கு உரித்தன்றே', 1, 0),
(21913, 1577, '87.jpg', '', 'image/jpeg', 27, 21912, '2023-08-07 02:33:31', 0, 0, 'System', 'ஊரும் பெயரும் உடைத்தொழிற் கருவியும் <br/>\r\nயாரும் சார்த்தி அவை அவை பெறுமே', 1, 0),
(21914, 1578, '87.jpg', '', 'image/jpeg', 27, 21912, '2023-08-07 02:33:31', 0, 0, 'System', 'தலைமைக் குணச் சொலும் தம்தமக்கு உரியதோர் <br/>\r\nநிலைமைக்கு ஏற்ப நிகழ்த்துப என்ப', 1, 0),
(21915, 1579, '87.jpg', '', 'image/jpeg', 27, 21912, '2023-08-07 02:33:31', 0, 0, 'System', 'இடை இரு வகையோர் அல்லது நாடின் <br/>\r\nபடை வகை பெறாஅர் என்மனார் புலவர்', 1, 0),
(21916, 1580, '87.jpg', '', 'image/jpeg', 27, 21912, '2023-08-07 02:33:31', 0, 0, 'System', 'வைசியன் பெறுமே வாணிகம் வாழ்க்கை', 1, 0),
(21917, 1581, '87.jpg', '', 'image/jpeg', 27, 21912, '2023-08-07 02:33:31', 0, 0, 'System', 'மெய் தெரி வகையின் எண் வகை உணவின்<br/> \r\nசெய்தியும் வரையார் அப் பாலான', 1, 0),
(21918, 1582, '87.jpg', '', 'image/jpeg', 27, 21912, '2023-08-07 02:33:31', 0, 0, 'System', 'கண்ணியும் தாரும் எண்ணினர் ஆண்டே', 1, 0),
(21919, 1583, '87.jpg', '', 'image/jpeg', 27, 0, '2023-08-07 02:36:46', 0, 0, 'System', 'வேளாண் மாந்தர்க்கு உழுதூண் அல்லது <br/>\r\nஇல் என மொழிப பிற வகை நிகழ்ச்சி', 1, 0),
(21920, 1584, '87.jpg', '', 'image/jpeg', 27, 21919, '2023-08-07 02:36:46', 0, 0, 'System', 'வேந்து விடு தொழிலின் படையும் கண்ணியும் <br/>\r\nவாய்ந்தனர் என்ப அவர் பெறும் பொருளே', 1, 0),
(21921, 1585, '87.jpg', '', 'image/jpeg', 27, 21919, '2023-08-07 02:36:46', 0, 0, 'System', 'அந்தணாளர்க்கு அரசு வரைவு இன்றே', 1, 0),
(21922, 1586, '87.jpg', '', 'image/jpeg', 27, 21919, '2023-08-07 02:36:46', 0, 0, 'System', 'வில்லும் வேலும் கழலும் கண்ணியும் <br/>\r\nதாரும் ஆரமும் தேரும் வாளும் <br/>\r\nமன் பெறு மரபின் ஏனோர்க்கும் உரிய', 1, 0),
(21923, 1587, '87a.jpg', '', 'image/jpeg', 27, 0, '2023-08-07 04:39:56', 0, 0, 'System', 'அன்னர் ஆயினும் இழந்தார்க்கு இல்லை', 1, 0),
(21924, 1588, '87a.jpg', '', 'image/jpeg', 27, 21923, '2023-08-07 04:39:56', 0, 0, 'System', 'புறக் காழனவே புல் என மொழிப', 1, 0),
(21925, 1589, '87a.jpg', '', 'image/jpeg', 27, 21923, '2023-08-07 04:39:56', 0, 0, 'System', 'அகக் காழனவே மரம் என மொழிப', 1, 0),
(21926, 1590, '87a.jpg', '', 'image/jpeg', 27, 21923, '2023-08-07 04:39:56', 0, 0, 'System', 'தோடே மடலே ஓலை என்றா <br/>\r\nஏடே இதழே பாளை என்றா <br/>\r\nஈர்க்கே குலை என நேர்ந்தன பிறவும் <br/>\r\nபுல்லொடு வரும் எனச் சொல்லினர் புலவர்', 1, 0),
(21927, 1591, '87a.jpg', '', 'image/jpeg', 27, 21923, '2023-08-07 04:39:56', 0, 0, 'System', 'இலையே தளிரே முறியே தோடே <br/>\r\nசினையே குழையே பூவே அரும்பே <br/>\r\nநனையே உள்ளுறுத்து அனையவை எல்லாம் <br/>\r\nமரனொடு வரூஉம் கிளவி என்ப', 1, 0),
(21928, 1592, '87a.jpg', '', 'image/jpeg', 27, 21923, '2023-08-07 04:39:56', 0, 0, 'System', 'காயே பழமே தோலே செதிளே <br/>\r\nவீழோடு என்று ஆங்கு அவையும் அன்ன', 1, 0),
(21929, 1593, '87a.jpg', '', 'image/jpeg', 27, 21923, '2023-08-07 04:39:56', 0, 0, 'System', 'நிலம் தீ நீர் வளி விசும்போடு ஐந்தும் <br/>\r\nகலந்த மயக்கம் உலகம் ஆதலின் <br/>\r\nஇரு திணை ஐம் பால் இயல் நெறி வழாஅமைத் <br/>\r\nதிரிவு இல் சொல்லொடு தழாஅல் வேண்டும்', 1, 0);
INSERT INTO `sv_songs` (`id`, `fid`, `fname`, `filename`, `filetype`, `cid`, `group_id`, `upload_date`, `down_counts`, `view_counts`, `author`, `description`, `status`, `trash`) VALUES
(21930, 1594, '87a.jpg', '', 'image/jpeg', 27, 21923, '2023-08-07 04:39:56', 0, 0, 'System', 'மரபு நிலை திரிதல் செய்யுட்கு இல்லை <br/>\r\nமரபு வழிப்பட்ட சொல்லினான', 1, 0),
(21931, 1595, '87a.jpg', '', 'image/jpeg', 27, 0, '2023-08-07 04:54:21', 0, 0, 'System', 'மரபு நிலை திரியின் பிறிது பிறிது ஆகும்', 1, 0),
(21932, 1596, '87a.jpg', '', 'image/jpeg', 27, 21931, '2023-08-07 04:54:21', 0, 0, 'System', 'வழக்கு எனப்படுவது உயர்ந்தோர் மேற்றே <br/>\r\nநிகழ்ச்சி அவர்கட்டு ஆகலான', 1, 0),
(21933, 1597, '87a.jpg', '', 'image/jpeg', 27, 21931, '2023-08-07 04:54:21', 0, 0, 'System', 'மரபு நிலை திரியா மாட்சிய ஆகி <br/>\r\nஉரை படு நூல்தாம் இரு வகை இயல <br/>\r\nமுதலும் வழியும் என நுதலிய நெறியின', 1, 0),
(21934, 1598, '87a.jpg', '', 'image/jpeg', 27, 21931, '2023-08-07 04:54:21', 0, 0, 'System', 'வினையின் நீங்கிய விளங்கிய அறிவின் <br/>\r\nமுனைவன் கண்டது முதல் நூல் ஆகும்', 1, 0),
(21935, 1599, '87a.jpg', '', 'image/jpeg', 27, 21931, '2023-08-07 04:54:21', 0, 0, 'System', 'வழி எனப்படுவது அதன் வழித்து ஆகும்', 1, 0),
(21936, 1600, '87a.jpg', '', 'image/jpeg', 27, 21931, '2023-08-07 04:54:21', 0, 0, 'System', 'வழியின் நெறியே நால் வகைத்து ஆகும்', 1, 0),
(21937, 1601, '88.jpg', '', 'image/jpeg', 27, 0, '2023-08-07 04:57:20', 0, 0, 'System', 'தொகுத்தல் விரித்தல் தொகைவிரி மொழிபெயர்த்து <br/>\r\nஅதர்ப்பட யாத்தலொடு அனை மரபினவே', 1, 0),
(21938, 1602, '88.jpg', '', 'image/jpeg', 27, 21937, '2023-08-07 04:57:20', 0, 0, 'System', 'ஒத்த சூத்திரம் உரைப்பின் காண்டிகை <br/>\r\nமெய்ப்படக் கிளந்த வகையது ஆகி <br/>\r\nஈர் ஐங் குற்றமும் இன்றி நேரிதின் <br/>\r\nமுப்பத்திருவகை உத்தியொடு புணரின்<br/> \r\nநூல் என மொழிப நுணங்கு மொழிப் புலவர்', 1, 0),
(21939, 1603, '88.jpg', '', 'image/jpeg', 27, 21937, '2023-08-07 04:57:20', 0, 0, 'System', 'உரை எடுத்து அதன் முன் யாப்பினும் சூத்திரம் <br/>\r\nபுரை தப உடன்படக் காண்டிகை புணர்ப்பினும் <br/> \r\nவிதித்தலும் விலக்கலும் என இரு வகையொடு <br/>\r\nபுரை தப நாடிப் புணர்க்கவும் படுமே', 1, 0),
(21940, 1604, '88.jpg', '', 'image/jpeg', 27, 21937, '2023-08-07 04:57:20', 0, 0, 'System', 'மேற் கிளந்தெடுத்த யாப்பினுள் பொருளொடு <br/>\r\nசில் வகை எழுத்தின் செய்யுட்டு ஆகிச் <br/>\r\nசொல்லும் காலை உரை அகத்து அடக்கி <br/>\r\nநுண்மையொடு புணர்ந்த ஒண்மைத்து ஆகித் <br/>\r\nதுளக்கல் ஆகாத் துணைமை எய்தி <br/>\r\nஅளக்கல் ஆகா அரும் பொருட்டு ஆகிப் <br/>\r\nபல் வகையானும் பயன் தெரிபு உடையது <br/>\r\nசூத்திரத்து இயல்பு என யாத்தனர் புலவர்', 1, 0),
(21941, 1605, '88.jpg', '', 'image/jpeg', 27, 21937, '2023-08-07 04:57:20', 0, 0, 'System', 'பழிப்பு இல் சூத்திரம் பட்ட பண்பின் <br/>\r\nகரப்பு இன்றி முடிவது காண்டிகை ஆகும்', 1, 0),
(21942, 1606, '88.jpg', '', 'image/jpeg', 27, 21937, '2023-08-07 04:57:20', 0, 0, 'System', 'விட்டு அகல்வு இன்றி விரிவொடு பொருந்திச் <br/>\r\nசுட்டிய சூத்திரம் முடித்தல் பொருட்டா <br/>\r\nஏது நடையினும் எடுத்துக்காட்டினும்  <br/>\r\nமேவாங்கு அமைந்த மெய்ந் நெறித்து அதுவே', 1, 0),
(21943, 1607, '88a.jpg', '', 'image/jpeg', 27, 0, '2023-08-07 04:59:53', 0, 0, 'System', 'சூத்திரத்துட் பொருள் அன்றியும் யாப்புற<br/> \r\nஇன்றியமையாது இயைபவை எல்லாம் <br/>\r\nஒன்ற உரைப்பது உரை எனப்படுமே', 1, 0),
(21944, 1608, '88a.jpg', '', 'image/jpeg', 27, 21943, '2023-08-07 04:59:53', 0, 0, 'System', 'மறுதலைக் கடாஅ மாற்றமும் உடைத்தாய்த் <br/>\r\nதன் நூலானும் முடிந்த நூலானும்  <br/>\r\nஐயமும் மருட்கையும் செவ்விதின் நீக்கித் <br/>\r\nதெற்றென ஒரு பொருள் ஒற்றுமை கொளீஇத் <br/>\r\nதுணிவொடு நிற்றல் என்மனார் புலவர்', 1, 0),
(21945, 1609, '88a.jpg', '', 'image/jpeg', 27, 21943, '2023-08-07 04:59:53', 0, 0, 'System', 'சொல்லப்பட்டன எல்லா மாண்பும் <br/>\r\nமறுதலை ஆயின் மற்று அது சிதைவே', 1, 0),
(21946, 1610, '88a.jpg', '', 'image/jpeg', 27, 21943, '2023-08-07 04:59:53', 0, 0, 'System', 'சிதைவு இல என்ப முதல்வன்கண்ணே', 1, 0),
(21947, 1611, '88a.jpg', '', 'image/jpeg', 27, 21943, '2023-08-07 04:59:53', 0, 0, 'System', 'முதல் வழி ஆயினும் யாப்பின் உள் சிதையும் <br/>\r\nவல்லோன் புணரா வாரம் போன்றே', 1, 0),
(21948, 1612, '88a.jpg', '', 'image/jpeg', 27, 21943, '2023-08-07 04:59:53', 0, 0, 'System', 'சிதைவு எனப்படுபவை வசை அற நாடின் <br/>\r\nகூறியது கூறல் மாறு கொளக் கூறல் <br/>\r\nகுன்றக் கூறல் மிகை படக் கூறல் <br/>\r\nபொருள் இல கூறல் மயங்கக் கூறல் <br/>\r\nகேட்போர்க்கு இன்னா யாப்பிற்று ஆதல் <br/>\r\nபழித்த மொழியான் இழுக்கம் கூறல் <br/>\r\nதன்னான் ஒரு பொருள் கருதிக் கூறல் <br/>\r\nஎன்ன வகையினும் மனங்கோள் இன்மை <br/>\r\nஅன்ன பிறவும் அவற்று விரி ஆகும்', 1, 0),
(21949, 1613, '88a.jpg', '', 'image/jpeg', 27, 21943, '2023-08-07 04:59:53', 0, 0, 'System', 'எதிர் மறுத்து உணரின் அத் திறத்தவும் அவையே', 1, 0),
(21950, 1614, '1614.jpg', '', 'image/jpeg', 27, 0, '2023-08-07 05:07:23', 0, 0, 'System', 'ஒத்த காட்சி உத்தி வகை விரிப்பின் <br/>\r\nநுதலியது அறிதல் அதிகார வகையே <br/>\r\nதொகுத்துக் கூறல் வகுத்து மெய்ந் நிறுத்தல் <br/>\r\nமொழிந்த பொருளோடு ஒன்ற அவ் வயின் <br/> \r\nமொழியாததனை முட்டு இன்றி முடித்தல் <br/>\r\nவாராததனான் வந்தது முடித்தல் <br/>\r\nவந்தது கொண்டு வாராதது முடித்தல் <br/>\r\nமுந்து மொழிந்ததன் தலைதடுமாற்றே <br/>\r\nஒப்பக் கூறல் ஒருதலை மொழிதல்<br/> \r\nதன் கோள் கூறல் முறை பிறழாமை <br/>\r\nபிறன் உடம்பட்டது தான் உடம்படுதல் <br/>\r\nஇறந்தது காத்தல் எதிரது போற்றல் <br/>\r\nமொழிவாம் என்றல் கூறிற்று என்றல் <br/>\r\nதான் குறியிடுதல் ஒருதலை அன்மை <br/>\r\nமுடிந்தது காட்டல் ஆணை கூறல் <br/>\r\nபல் பொருட்கு ஏற்பின் நல்லது கோடல் <br/>\r\nதொகுத்த மொழியான் வகுத்தனர் கோடல் <br/>\r\nமறுதலை சிதைத்துத் தன் துணிபு உரைத்தல் <br/>\r\nபிறன் கோள் கூறல் அறியாது உடம்படல் <br/>\r\nபொருள் இடையிடுதல் எதிர் பொருள் உணர்த்தல் <br/>\r\nசொல்லின் எச்சம் சொல்லியாங்கு உணர்த்தல் <br/>\r\nதந்து புணர்ந்து உரைத்தல் ஞாபகம் கூறல் <br/>\r\nஉய்த்துக்கொண்டு உணர்த்தலொடு மெய்ப்பட நாடிச் <br/>\r\nசொல்லிய அல்ல பிற அவண் வரினும்  <br/>\r\nசொல்லிய வகையான் சுருங்க நாடி <br/>\r\nமனத்தின் எண்ணி மாசு அறத் தெரிந்து கொண்டு <br/>\r\nஇனத்தின் சேர்த்தி உணர்த்தல் வேண்டும் <br/>\r\nநுனித்தகு புலவர் கூறிய நூலே', 1, 0),
(21951, 1, '1.jpg', '', 'image/jpeg', 28, 0, '2023-08-17 03:09:27', 0, 0, 'System', 'சென்ற புகழ்செல்வ மீக்கூற்றம் சேவகம்<br/>\r\nநின்ற நிலைகல்வி வள்ளன்மை என்றும்<br/>\r\nவழிவந்தார் பூங்கோதா யாறு மறை இன்<br/>\r\nவழிவந்தார் கண்ணே வனப்பு	', 1, 0),
(21952, 2, '1.jpg', '', 'image/jpeg', 28, 21951, '2023-08-17 03:09:27', 0, 0, 'System', 'கொலைபுரியான் கொல்லான் புலான்மயங்கான் கூர்த்த<br/>\r\nஅலைபுரியான் வஞ்சியான் யாதும் - நிலைதிரியான்<br/>\r\nமண்ணவர்க்கு மன்றி மதுமலிபூங் கோதாய்<br/>\r\nவிண்ணவர்க்கு மேலாய் விடும்', 1, 0),
(21953, 3, '1.jpg', '', 'image/jpeg', 28, 21951, '2023-08-17 03:09:27', 0, 0, 'System', 'தவமெளிது தான மரிதுதக் கார்க்கேல்<br/>\r\nஅவமரி தாத லெளிதால் அவமிலா<br/>\r\nஇன்பம் பிறழி னியைவெளிது மற்றதன்<br/>\r\nதுன்பந் துடைத்த லரிது', 1, 0),
(21954, 4, '1.jpg', '', 'image/jpeg', 28, 21951, '2023-08-17 03:09:27', 0, 0, 'System', 'இடர்தீர்த்த லெள்ளாமை கீழினஞ் சேராமை<br/>\r\nபடர்தீர்த்தல் யார்க்கும் பழிப்பின் - நடைதீர்த்தல்<br/>\r\nகண்டவர் காமுறுஞ்சொற் காணிற் கலவியின்கண்<br/>\r\nவிண்டவர்நூல் வேண்டா விடும்', 1, 0),
(21955, 5, '1.jpg', '', 'image/jpeg', 28, 21951, '2023-08-17 03:09:27', 0, 0, 'System', 'தனக்கென்று மோர்பாங்கற் பொய்யான் மெய்யாக்கும்<br/>\r\nஎனக்கென் றியையான் யாதொன்றும் புனக்கொன்றை<br/>\r\nபோலு மிழையார்சொற் றேறான் களியானேல்<br/>\r\nசாலும் பிறநூலின் சார்பு', 1, 0),
(21956, 6, '1A.jpg', '', 'image/jpeg', 28, 0, '2023-08-17 04:01:59', 0, 0, 'System', 'நிறையுடைமை நீர்மை யுடைமை கொடையே<br/>\r\nபொறையுடைமை பொய்மை புலாற்கண் - மறையுடைமை<br/>\r\nவேயன்ன தோளா யிவையுடையான் பல்லுயிர்க்கும்<br/>\r\nதாயன்ன னென்னத் தகும்', 1, 0),
(21957, 7, '1A.jpg', '', 'image/jpeg', 28, 21956, '2023-08-17 04:01:59', 0, 0, 'System', 'இன்சொ லளாவ லிடமினிதூண் யாவர்க்கும் <br/>\r\nவன்சொற் களைந்து வகுப்பானேல் மென்சொல்<br/>\r\nமுருந்தேய்க்கு முட்போ லெயிற்றினாய் நாளும்<br/>\r\nவிருந்தேற்பர் விண்ணோர் விரைந்து', 1, 0),
(21958, 8, '1A.jpg', '', 'image/jpeg', 28, 21956, '2023-08-17 04:01:59', 0, 0, 'System', 'உடன்படான் கொல்லா னுடன்றார்நோய் தீர்த்து<br/>\r\nமடம்படான் மாண்டார்நூன் மாண்ட - இடம்பட<br/>\r\nநோக்கும்வாய் நோக்கி நுழைவானேன் மற்றவனை<br/>\r\nயாக்குமவர் யாக்கு மணைந்து', 1, 0),
(21959, 9, '2.jpg', '', 'image/jpeg', 28, 0, '2023-08-17 04:03:03', 0, 0, 'System', 'கற்றாரைக் கற்ற துணரா ரெனமதியா<br/>\r\nருற்றாரை யன்னண மோராமல் - அற்றார்கட்<br/>\r\nகுண்டி யுறையு ளுடுக்கை யிவை யீந்தார்<br/>\r\nபண்டிதராய் வாழ்வர் பயின்று', 1, 0),
(21960, 10, '2.jpg', '', 'image/jpeg', 28, 21959, '2023-08-17 04:03:03', 0, 0, 'System', 'செங்கோலான் கீழ்க்குடிகள் செல்வமுஞ் சீரிலா<br/>\r\nவெங்கோலான் கீழ்க்குடிகள் வீந்துகவும் - வெங்கோல்<br/>\r\nஅமைச்சர் தொழிலு மறியலமொன் றாற்ற<br/>\r\nஎனைத்து மறியாமை யான்', 1, 0),
(21961, 11, '2A.jpg', '', 'image/jpeg', 28, 0, '2023-08-18 10:24:16', 0, 0, 'System', 'அவாவறுக்க லுற்றான் றளரானவ் வைந்தின்<br/>\r\nஅவாவறுப்பி னாற்ற வமையும் - அவாவறான்<br/>\r\nஆகு மவனாயி னைங்களிற்றி னாட்டுண்டு<br/>\r\nபோகும் புழையுட் புலந்து ', 1, 0),
(21962, 12, '2A.jpg', '', 'image/jpeg', 28, 21961, '2023-08-18 10:24:16', 0, 0, 'System', 'கொலைக்களம் வார்குத்துச் சூதாடு மெல்லை<br/>\r\nஅலைக்களம் போர்யானை யாக்கு - நிலைக்களம்<br/>\r\nமுச்சா ரிகையொதுங்கு மோரிடத்து மின்னவை<br/>\r\nநச்சாமை நோக்காமை நன்று', 1, 0),
(21963, 13, '3.jpg', '', 'image/jpeg', 28, 0, '2023-08-18 10:24:51', 0, 0, 'System', 'விளையாமை யுண்ணாமை யாடாமை யாற்ற<br/>\r\n		உளையாமை யுட்குடைத்தா வென்று - களையாமை<br/>\r\n		நூற்பட்டார் பூங்கோதாய் நோக்கி னிவையாறும்<br/>\r\n		பாற்பட்டார் கொண்டொழுகும் பண்பு', 1, 0),
(21964, 14, '3A.jpg', '', 'image/jpeg', 28, 0, '2023-08-18 10:26:18', 0, 0, 'System', 'பொய்யான் புலாலொடு கட்போக்கித் தீயன<br/>\r\n		செய்யான் சிறியா ரினஞ்சேரான் - வையான்<br/>\r\n		கயலியலூண் கண்ணாய் கருதுங்கா லென்றும்<br/>\r\n		அயல வயலவா நூல்', 1, 0),
(21965, 15, '3A.jpg', '', 'image/jpeg', 28, 21964, '2023-08-18 10:26:18', 0, 0, 'System', 'கண்போல்வார்க் காயாமை கற்றா ரினஞ்சேர்தல்<br/>\r\n		பண்போல் கிளவியார்ப் பற்றாமை - பண்போலும்<br/>\r\n		சொல்லார்க் கருமறை சோராமை சிறிதெனினும்<br/>\r\n		இல்லார்க் கிடர்தீர்த்த னன்று', 1, 0),
(21966, 16, '3A.jpg', '', 'image/jpeg', 28, 21964, '2023-08-18 10:26:18', 0, 0, 'System', 'துறந்தார்கட் டுன்னித் துறவார்க் கிடுதல்<br/>\r\n		இறந்தார்க் கினிய விசைத்தல் - இறந்தார்<br/>\r\n		மறுதலை சுற்ற மதித்தோம்பு வானேல் <br/>\r\n		இறுதலில் வாழ்வே இனிது', 1, 0),
(21967, 17, '4.jpg', '', 'image/jpeg', 28, 0, '2023-08-21 10:15:27', 0, 0, 'System', 'குடியோம்பல் வன்கண்மை நூல்வன்மை கூடம்<br/>\r\n		மடியோம்பு மாற்ற லுடைமை - முடியோம்பி <br/>\r\n		நாற்றஞ் சுவைகேள்வி நல்லா ரினஞ்சேர்தல்<br/>\r\n		தேற்றானேற் றேறு மமைச்சு', 1, 0),
(21968, 18, '4A.jpg', '', 'image/jpeg', 28, 0, '2023-08-21 10:16:16', 0, 0, 'System', 'போகம் பொருள்கேடு மான்வேட்டம் பொல்லாக்கள்<br/>\r\n		சோகம் படுஞ்சூதே சொல்வன்மை சோகக்<br/>\r\n		கடுங்கதத்துத தண்ட மடங்காமை காப்பின் <br/>\r\n		அடுங்கதமி லேனை யரசு', 1, 0),
(21969, 19, '4A.jpg', '', 'image/jpeg', 28, 21968, '2023-08-21 10:16:16', 0, 0, 'System', 'கொல்லான் கொலைபுரியான் பொய்யான் பிறர்மனைமேல்<br/>\r\n		செல்லான் சிறியா ரினஞ்சேரான் - சொல்லும்<br/>\r\n		மறையிற் செவியிலன் றீச்சொற்கண் மூங்கை<br/>\r\n		இறையிற் பெரியாற் கிவை', 1, 0),
(21970, 20, '5.jpg', '', 'image/jpeg', 28, 0, '2023-08-21 10:16:51', 0, 0, 'System', 'மின்னே ரிடையார்சொற் றேறான் விழைவோரான்<br/>\r\n		கொன்னே வெகுளான் கொலைபுரியான் - பொன்னே<br/>\r\n		உறுப்பறுத் தன்ன கொடையுவப்பான் றன்னின்<br/>\r\n		வெறுப்பறுத்தான் விண்ணகத்து மில்', 1, 0),
(21971, 21, '5.jpg', '', 'image/jpeg', 28, 21970, '2023-08-21 10:16:51', 0, 0, 'System', 'இளமை கழியும் பிணிமூப் பியையும்<br/>\r\n		வளமை வலியிவை வாடும் - உளநாளால்<br/>\r\n		பாடே புரியாது பால்போலுஞ் சொல்லினாய்<br/>\r\n		வீடே புரிதல் விதி', 1, 0),
(21972, 22, '5A.jpg', '', 'image/jpeg', 28, 0, '2023-08-21 10:18:22', 0, 0, 'System', 'வாளஞ்சான் வன்கண்மை யஞ்சான் வனப்பஞ்சான்<br/>\r\n		ஆளஞ்சா னாம்பொருடா னஞ்சான் நாளெஞ்சாக்<br/>\r\n		காலன் வரவொழிதல் காணின்வீ டெய்திய<br/>\r\n		பாலினூ லெய்தப் படும்', 1, 0),
(21973, 23, '5A.jpg', '', 'image/jpeg', 28, 21972, '2023-08-21 10:18:22', 0, 0, 'System', 'குணநோக்கான் கூழ்நோக்கான் கோலமு நோக்கான்<br/>\r\n		மணநோக்கான் மங்கலமு நோக்கான் கணநோக்கான்<br/>\r\n		கால்காப்பு வேண்டான் பெரியார்நூல் காலற்கு<br/>\r\n		வாய்காப்புக் கோடல் வனப்பு', 1, 0),
(21974, 24, '6.jpg', '', 'image/jpeg', 28, 0, '2023-08-21 10:18:46', 0, 0, 'System', 'பிணிபிறப்பு மூப்பொடு சாக்காடு துன்பம் <br/>\r\n		தணிவி னிரப்பிவை தாழா - அணியின்<br/>\r\n		அரங்கின்மே லாடுநர்போ லாகாம னன்றாம்<br/>\r\n		நிறம்புமேல் வீட்டு நெறி', 1, 0),
(21975, 25, '6A.jpg', '', 'image/jpeg', 28, 0, '2023-08-21 10:53:35', 0, 0, 'System', 'பாடகஞ் சாராமை பாத்திலார் தாம்விழையும்<br/>\r\n		நாடகஞ் சாராமை நாடுங்கால் - நாடகம்<br/>\r\n		சேர்ந்தாற் பகைபழி தீச்சொல்லே சாக்காடே<br/>\r\n		தீர்ந்தாற்போற் றீரா வரும்', 1, 0),
(21976, 26, '6A.jpg', '', 'image/jpeg', 28, 21975, '2023-08-21 10:53:35', 0, 0, 'System', 'மாண்டமைந்தா ராய்ந்த மதிவனப்பே வன்கண்மை<br/>\r\n		ஆண்டமைந்த கல்வியே சொல்லாற்றல் - பூண்டமைந்த<br/>\r\n		கால மறிதல் கருதுங்காற் றூதுவர்க்கு<br/>\r\n		ஞால மறிந்த புகழ்', 1, 0),
(21977, 27, '6A.jpg', '', 'image/jpeg', 28, 21975, '2023-08-21 10:53:35', 0, 0, 'System', 'அஃகுநீ செய்ய லெனவறிந் தாராய்ந்தும் <br/>\r\n		வெஃகல் வெகுடலே தீக்காட்சி - வெஃகுமான்<br/>\r\n		கள்ளத்த வல்ல கருதி னிவைமூன்றும்<br/>\r\n		உள்ளத்த வாக வுரை', 1, 0),
(21978, 28, '7.jpg', '', 'image/jpeg', 28, 0, '2023-08-21 03:24:17', 0, 0, 'System', 'மையேர் தடங்கண் மயிலன்ன சாயலே<br/>\r\n		மெய்யே யுணர்ந்தார் மிகவுரைப்பார் - பொய்யே<br/>\r\n		குறளை கடுஞ்சொற் பயனிலசொ னான்கும் <br/>\r\n		மறலையின் வாயினவா மற்று', 1, 0),
(21979, 29, '7.jpg', '', 'image/jpeg', 28, 21978, '2023-08-21 03:24:17', 0, 0, 'System', 'நிலையளவி னின்ற நெடியவர்தா நேரா<br/>\r\n		கொலைகளவு காமத்தீ வாழ்க்கை - அலையளவி<br/>\r\n		மையெனநீள் கண்ணாய் மறுதலைய விம்மூன்றும்<br/>\r\n		மெய்யள வாக விதி', 1, 0),
(21980, 30, '7A.jpg', '', 'image/jpeg', 28, 0, '2023-08-21 03:25:04', 0, 0, 'System', 'மாண்டவர் மாண்ட வறிவினான் மக்களைப்<br/>\r\n		பூண்டவர்ப் போற்றிப் புரக்குங்கால் - பூண்ட<br/>\r\n		ஒளரதனே கேத்திரசன் கானீனன் கூடன்<br/>\r\n		கிரிதன்பௌ நற்பவன் பேர்', 1, 0),
(21981, 31, '7A.jpg', '', 'image/jpeg', 28, 21980, '2023-08-21 03:25:04', 0, 0, 'System', 'மத்த மயிலன்ன சாயலாய் மன்னியசீர்த் <br/>\r\n		தத்தன் சகோடன் கிருத்திரமன் - புத்திரி<br/>\r\n		புத்ரனப வித்தனொடு பொய்யி லுபகிருதன்<br/>\r\n		இத்திறத்த வெஞ்சினார் பேர்', 1, 0),
(21982, 32, '8.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 12:37:49', 0, 0, 'System', 'உரையான் குலன்குடிமை யூனம் பிறரை<br/>\r\n		உரையான் பொருளொடுவாழ் வாயு - உரையானாய்ப்<br/>\r\n		பூவாதி வண்டுதேர்ந் துண்குழலா யீத்துண்பான்<br/>\r\n		தேவாதி தேவனாத் தேறு', 1, 0),
(21983, 33, '8.jpg', '', 'image/jpeg', 28, 21982, '2023-08-22 12:37:49', 0, 0, 'System', 'பொய்யுரையான் வையான் புறங்கூறான் யாவரையும்<br/>\r\n		மெய்யுரையா னுள்ளனவும் விட்டுரையான் - எய்யுரையான் <br/>\r\n		கூந்தன்மயி லன்னாய் குழீஇயவான் விண்ணோர்க்கு <br/>\r\n		வேந்தனா மிவ்வுலகம் விட்டு', 1, 0),
(21984, 34, '8.jpg', '', 'image/jpeg', 28, 21982, '2023-08-22 12:37:49', 0, 0, 'System', 'சிதையுரையான் செற்ற முரையான் சீறில்லான்<br/>\r\n		இயல்புரையா னீன முரையான் - நசையவர்க்கு<br/>\r\n		கூடுவ தீவானைக் கொவ்வைபோல் செவ்வாயாய்<br/>\r\n		நாடுவர் விண்ணோர் நயந்து', 1, 0),
(21985, 35, '8.jpg', '', 'image/jpeg', 28, 21982, '2023-08-22 12:37:49', 0, 0, 'System', 'துறந்தார் துறவாதார் துப்பிலார் தோன்றா<br/>\r\n		திறந்தா ரீடற்றா ரிளையர் - சிறந்தவர்க்கும்<br/>\r\n		பண்ணாளுஞ் சொல்லாய் பழியிலூண் பாற்படுத்தான்<br/>\r\n		மண்ணாளு மன்னனாய் மற்று', 1, 0),
(21986, 36, '8.jpg', '', 'image/jpeg', 28, 21982, '2023-08-22 12:37:49', 0, 0, 'System', 'காலில்லார் கண்ணில்லார் நாவில்லார் யாரையும்<br/>\r\n		பாலில்லார் பற்றிய நூலில்லார் - சாலவும்<br/>\r\n		ஆழப் படுமூ ணமைத்தா ரிமையவரால் <br/>\r\n		வீழப் படுவார் விரைந்து\r\n', 1, 0),
(21987, 37, '8A.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 12:38:55', 0, 0, 'System', 'அழப்போகா னஞ்சா னலறினாற் கேளான்<br/>\r\n		எழப்போகா னீடற்றா ரென்றும் - தொழப்போகான்<br/>\r\n		என்னேயிக காலனீ டோரான் தவமுயலான்<br/>\r\n		கொன்னே யிருத்தல் குறை', 1, 0),
(21988, 38, '8A.jpg', '', 'image/jpeg', 28, 21987, '2023-08-22 12:38:55', 0, 0, 'System', 'எழுத்தினா னீங்காதெண் ணாலொழியா தேத்தி<br/>\r\n		வழுத்தினான் மாறாது மாண்ட - ஒழுக்கினால்<br/>\r\n		நேராமை சால வுணர்வார் பெருந்தவம்<br/>\r\n		போகாமை சாலப் புலை', 1, 0),
(21989, 39, '8A.jpg', '', 'image/jpeg', 28, 21987, '2023-08-22 12:38:55', 0, 0, 'System', 'சாவ தெளிதரிது சான்றாண்மை நல்லது<br/>\r\n		மேவ லெளிதரிது மெய்போற்றல் - ஆவதன்கண்<br/>\r\n		சேற லெளிது நிலையரிது தெள்ளியராய்<br/>\r\n		வேற லெளிதரிது சொல்', 1, 0),
(21990, 40, '8A.jpg', '', 'image/jpeg', 28, 21987, '2023-08-22 12:38:55', 0, 0, 'System', 'உலையாமை யுற்றதற் கோடி யுயிரை<br/>\r\n		அலையாமை யையப் படாமை - நிலையாமை<br/>\r\n		தீர்க்கும்வாய் தேர்ந்து பசியுண்டி நீக்குவான்<br/>\r\n		நோக்கும்வாய் விண்ணி ணுயர்வு', 1, 0),
(21991, 41, '9.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 12:40:04', 0, 0, 'System', 'குறுகான் சிறியாரைக் கொள்ளான் புலால்பொய்<br/>\r\n		மறுகான் பிறர்பொருள் வெளவான் - இறுகானாய்<br/>\r\n		ஈடற் றவர்க்கீவா னாயி னெறிநூல்கள்<br/>\r\n		பாடிறப்ப பன்னு மிடத்து\r\n', 1, 0),
(21992, 42, '9.jpg', '', 'image/jpeg', 28, 21991, '2023-08-22 12:40:04', 0, 0, 'System', 'கொல்லா னுடன்படான் கொல்வா ரினஞ்சேரான்<br/>\r\nபுல்லான் பிறர்பாற் புலான்மயங்கல் - செல்லான்<br/>\r\nகுடிப்படுத்துக் கூழீந்தான் கொல்யானை யேறி <br/>\r\nஅடிப்படுப்பான் மண்ணாண் டரசு', 1, 0),
(22031, 1, '3.jpg', '', 'image/jpeg', 30, 0, '2023-08-24 02:46:11', 0, 0, 'System', 'அருந்ததிக் கற்பினா டோளுந் திருந்திய<br/>\r\nதொல்குடியின் மாண்டார் தொடர்ச்சியுஞ் - சொல்லி<br/>\r\nனரிலகற்றுங் கேள்வியார் நட்புமிம் மூன்றுந்<br/>\r\nதிரிகடுகம் போலு மருந்து', 1, 0),
(21993, 43, '9A.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 12:41:13', 0, 0, 'System', 'சூதுவவான் பேரான் சுலாவுரையான் யார்திறத்தும்<br/>\r\n		வாதுவவான் மாதரார் சொற்றேறான் - காதுதாழ்<br/>\r\n		வான்மகர வார்குழையாய் மாதவர்க் கூணீந்தான் <br/>						தான்மகர வாய்மாடத் தான்', 1, 0),
(21994, 44, '9A.jpg', '', 'image/jpeg', 28, 21993, '2023-08-22 12:41:13', 0, 0, 'System', 'பொய்யான்பொய் மேவான் புலால்லுண்ணான் யாவரையும்<br/>\r\nவையான் வழிசீத்து வாலடிசில் நையாதே<br/>\r\nஈத்துண்பா னாகு மிருங்கடல்சூழ் மண்ணரசாய்ப்<br/>\r\nபாத்துண்பா னேத்துண்பான் பாடு\r\n', 1, 0),
(21995, 45, '10.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 12:43:37', 0, 0, 'System', 'இழுக்கா னியனெறி யின்னாத வெஃகான்<br/>\r\nவழுக்கான் மனைபொருள் வெளவான் - ஒழுக்கத்தால்<br/>\r\nசெல்வான் செயிரிலூ ணீவா னரசாண்டு<br/>\r\nவெல்வான் விடுப்பான் விரைந்து\r\n', 1, 0),
(21996, 46, '10.jpg', '', 'image/jpeg', 28, 21995, '2023-08-22 12:43:37', 0, 0, 'System', 'களியான்கள் ளுண்ணான் களிப்பாரைக் காணான்<br/> \r\n		ஒளியான் விருந்திற் குலையான் - எளியாரை<br/>\r\n		எள்ளானீத் துண்பானே லேதமின் மண்ணாண்டு<br/>\r\n		கொள்வான் குடிவாழ்வான் கூர்ந்து', 1, 0),
(21997, 47, '10A.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 12:46:14', 0, 0, 'System', 'பெரியார்சொற் பேணிப் பிறழாது நின்று<br/>\r\n		பரியா வடியார்ப் பறியான் - கரியார்சொல்<br/>\r\n		தேறா னியையான் தெளிந்தடிசி லீத்துண்பான்<br/>\r\n		மாறான்மண் ணாளுமா மற்று', 1, 0),
(21998, 48, '10A.jpg', '', 'image/jpeg', 28, 21997, '2023-08-22 12:46:14', 0, 0, 'System', 'வேற்றரவஞ் சேரான் விருந்தொளியான் தன்னில்லுள்<br/>\r\n		சோற்றரவஞ் சொல்லியுண் பானாயின் - மாற்றரவங்<br/>\r\n		கேளான் கிளையோம்பிற் கேடி லரசனாய்<br/>\r\n		வாளான்மண் ணாண்டு வரும்', 1, 0),
(21999, 49, '10A.jpg', '', 'image/jpeg', 28, 21997, '2023-08-22 12:46:14', 0, 0, 'System', 'யானை குதிரைபொன் கன்னியே யானிரையோ<br/>\r\n		டேனை யொழிந்த விவையெல்லாம் - ஆனெய்யால்<br/>\r\n		எண்ணனாய் மாதவர்க் கூணீந்தான் வைசிர<br/>\r\n		வண்ணனாய் வாழ்வான் வகுத்து', 1, 0),
(22000, 50, '10A.jpg', '', 'image/jpeg', 28, 21997, '2023-08-22 12:46:14', 0, 0, 'System', 'எள்ளே பருத்தியே யெண்ணெ யுடுத்தாடை<br/>\r\n		வள்ளே துணியே யிவற்றோடு - கொள்ளென<br/>\r\n		அன்புற் றசனங் கொடுத்தான் றுணையினோ<br/>\r\n		டின்புற்று வாழ்வா னியைந்து', 1, 0),
(22001, 51, '10A.jpg', '', 'image/jpeg', 28, 21997, '2023-08-22 12:46:14', 0, 0, 'System', 'உண்ணீர் வளங்குளங் கூவல் வழிப்புரை<br/>\r\n		தண்ணீரே யம்பலந்தான் பாற்படுத்தான் - பண்ணீர<br/>\r\n		பாடலொ டாடல் பயின்றுயர் செல்வனாய்க்<br/>\r\n		கூடலொ டூடலுளான் கூர்ந்து', 1, 0),
(22002, 52, '10A.jpg', '', 'image/jpeg', 28, 21997, '2023-08-22 12:46:14', 0, 0, 'System', 'இல்லிழந்தார் கண்ணிழந்தா ரீண்டியசெல் வம்மிழந்தார்<br/>\r\n		நெல்லிழந்தா ரானிரை தானிழந்தார்க் - கெல்லுழந்து<br/>\r\n		பண்ணியூ ணீய்ந்தவர் பல்யானை மன்னராய்<br/>\r\n		எண்ணியூ ணார்வா ரியைந்து', 1, 0),
(22003, 53, '11.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 02:10:34', 0, 0, 'System', 'கடம்பட்டார் காப்பில்லார் கைத்தில்லார் தங்கான்<br/>\r\n		முடம்பட்டார் மூத்தார் மூப்பில்லார்க் - குடம்பட்<br/>\r\n		டுடையரா யில்லுளூ ணீத்துண்பார் மண்மேல்<br/>\r\n		படையராய் வாழ்வார் பயின்று', 1, 0),
(22004, 54, '11.jpg', '', 'image/jpeg', 28, 22003, '2023-08-22 02:10:35', 0, 0, 'System', 'பார்ப்பார் பசித்தார் தவசிகள் பாலர்கள்<br/>\r\n		கார்ப்பார் தமையாதுங் காப்பிலார் - தூப்பால<br/>\r\n		நீண்டாரா லெண்ணாது நீத்தவர் மண்ணாண்டு<br/>\r\n		பண்டாரம் பற்றவாழ் வார்', 1, 0),
(22005, 55, '11.jpg', '', 'image/jpeg', 28, 22003, '2023-08-22 02:10:35', 0, 0, 'System', 'ஈன்றாரின் காற்றளர்வார் சூலார் குழவிகள்<br/>\r\n		மான்றார் வளியான் மயங்கினார்க் - கானாரென்<br/>\r\n		றூணீய்த் துறுநோய் களைந்தார் பெருஞ்செல்வம்<br/>\r\n		காணீய்த்து வாழ்வார் கலந்து', 1, 0),
(22006, 56, '11A.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 03:10:34', 0, 0, 'System', 'தளையாளர் தாப்பாளர் தாழ்ந்தவர் பெண்டீ<br/>\r\n		ருளையாள ரூணொன்று மில்லார் - கிளைஞராய்<br/>\r\n		மாவலர்ந்த நோக்கினா யூணீய்ந்தார் மாக்கடல்சூழ்<br/>\r\n		நாவலந்தீ வாள்வாரே நன்கு', 1, 0),
(22007, 57, '11A.jpg', '', 'image/jpeg', 28, 22006, '2023-08-22 03:10:34', 0, 0, 'System', 'கருஞ்சிரங்கு வெண்டொழுநோய் கல்வளி காயும்<br/>\r\n		பெருஞ்சிரங்கு பேர்வயிற்றுத் தீயார்க் - கருஞ்சிரம<br/>\r\n		மாற்றியூ ணீத்தவை தீர்த்தா ரரசராய்ப்<br/>\r\n		போற்றியூ  ணுண்பார் புரந்து\r\n', 1, 0),
(22008, 58, '12.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 03:11:17', 0, 0, 'System', 'காமாடார் காமியார் கல்லா ரினஞ்சேரா<br/>\r\n		ராமாடா ராய்ந்தார் நெறிநின்று - தாமாடா<br/>\r\n		தேற்றாரை யின்புற வீய்ந்தார்முன் னிம்மையான்<br/>\r\n		மாற்றாரை மாற்றி வாழ்வார்', 1, 0),
(22009, 59, '12.jpg', '', 'image/jpeg', 28, 22008, '2023-08-22 03:11:17', 0, 0, 'System', 'வணங்கி வழியொழுகி மாண்டார் சொற்கொண்டு<br/>\r\n		நுணங்கிய நூனோக்கு நுழையா - விணங்கிய<br/>\r\n		பானோக்கி வாழ்வான் பழியில்லா மன்னனாய்<br/>\r\n		நூனோக்கி வாழ்வா னுனித்து', 1, 0),
(22010, 60, '12A.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 03:12:19', 0, 0, 'System', 'பெருமை புகழறம் பேணாமை சீற்றம்<br/>\r\n		அருமைநூல் சால்பில்லார் சாரி - னிருமைக்கும்<br/>\r\n		பாவம் பழிபகை சாக்காடே கேடச்சம்<br/>\r\n		சாபம்போற் சாருஞ் சலித்து', 1, 0),
(22011, 61, '12A.jpg', '', 'image/jpeg', 28, 22010, '2023-08-22 03:12:19', 0, 0, 'System', 'ஆர்வமே  செற்றங் கதமே யறையுங்கால்<br/>\r\n		ஓர்வமே செய்யு முலோபமே - சீர்சாலா<br/>\r\n		மானமே மாய வுயிர்க்கூன மென்னுமே<br/>\r\n		ஊனமே தீர்ந்தவ ரோத்து', 1, 0),
(22012, 62, '13.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 03:26:44', 0, 0, 'System', 'கூத்தும் விழவு மணமுங் கொலைக்களமு<br/>\r\n		மார்த்த முனையுள்ளும் வேறிடத்தும் - ஓத்தும்<br/>\r\n		ஒழுக்கு முடையவர் செல்லாரே செல்லின்<br/>\r\n		இழுக்கு  மிழவுந் தரும் ', 1, 0),
(22013, 63, '13.jpg', '', 'image/jpeg', 28, 22012, '2023-08-22 03:26:44', 0, 0, 'System', 'ஊணொடு கூறை யெழுத்தாணி புத்தகம்<br/>\r\n		பேணொடு மெண்ணு மெழுத்திவை - மாணொடு<br/>\r\n		கேட்டெழுதி  யோதிவாழ் வார்க்கீய்ந்தா  ரிம்மையான்<br/>\r\n		வேட்டெழுத வாழ்வார் விரிந்து', 1, 0),
(22014, 64, '13A.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 03:27:32', 0, 0, 'System', 'உயர்ந்தான் றலைவனென் றொப்புடைத் தானோக்கி<br/>\r\nஉயர்ந்தா னூலோதி  யொடுங்கி - உயர்ந்தான்<br/>\r\nஅருந்தவ மாற்றச் செயின்வீடா மென்றார்<br/>\r\nபெருந்தவஞ் செய்தார் பெரிது', 1, 0),
(22015, 65, '13A.jpg', '', 'image/jpeg', 28, 22014, '2023-08-22 03:27:32', 0, 0, 'System', 'காலனா  ரீடறுத்தல் காண்குறின் முற்றுணர்ந்த<br/>\r\n		பாலனார் நூலமர்ந்து பாராது - வாலிதா<br/>\r\n		ஊறுபா டில்லா வுயர்தவந் தான்புரியின்<br/>\r\n		ஏறுமோ மேலுலக மோர்ந்து', 1, 0),
(22016, 66, '14.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 04:19:49', 0, 0, 'System', 'பொய்தீர் புலவர் பொருள்புரிந் தாராய்ந்த<br/>\r\n		மைதீ ருயர்கதியின் மாண்புரைப்பின் - மைதீர்<br/>\r\n		சுடரின்று  சொல்லின்று  மாறின்று சோர்வின்<br/>\r\n		றிடரின் றினிதுயிலு மின்று\r\n', 1, 0),
(22017, 67, '14.jpg', '', 'image/jpeg', 28, 22016, '2023-08-22 04:19:49', 0, 0, 'System', 'கூரம்பு வெம்மண லீர்மணி தூய்கலும்<br/>\r\n		ஈரும் புகையிரு ளோடிருணூல் - ஆராய்ந்<br/>\r\n		தழிகதி யிம்முறையா னான்றா ரறைந்தார்<br/>\r\n		இழிகதி யிம்முறையா னேழு	', 1, 0),
(22018, 68, '14A.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 04:21:06', 0, 0, 'System', 'சாதல் பொருள்கொடுத்த லின்சொற் புணர்வுவத்தல்<br/>\r\n		நோதற் பிரிவிற் கவறலே - ஓதலின்<br/>\r\n		அன்புடையார்க்  குள்ளன வாறு குணமாக<br/>\r\n		மென்புடையார் வைத்தார் விரித்து', 1, 0),
(22019, 69, '14A.jpg', '', 'image/jpeg', 28, 22018, '2023-08-22 04:21:06', 0, 0, 'System', 'எடுத்தன் முடக்க னிமிர்த்த னிலையே<br/>\r\n		படுத்தலோ டாடல் பகரின் - அடுத்துயிர்<br/>\r\n		ஆறு தொழிலென் றறைந்தா ருயர்ந்தவர்<br/>\r\n		வேறு தொழிலாய் விரித்து', 1, 0),
(22020, 70, '15.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 04:21:42', 0, 0, 'System', 'ஐயமே பிச்சை யருந்தவர்க் கூணாடை<br/>\r\n		ஐயமே யின்றி  யறிந்தீந்தான் - வையமும்<br/>\r\n		வானும் வரிசையாற் றானாளு நாளுமே<br/>\r\n		யீனமே யின்றி யினிது', 1, 0),
(22021, 71, '15.jpg', '', 'image/jpeg', 28, 22020, '2023-08-22 04:21:42', 0, 0, 'System', 'நடப்பார்க்கூ ணல்ல பொறைதாங்கி னார்க்கூண்<br/>\r\nகிடப்பார்க்கூண்  கேளிர்க்கூண்  கேடின் –று-ற்சார்ந்த <br/>\r\nவானகத்தார்க் கூணே  மறுதலையார்க்  கூணமைத்தான்<br/>\r\nதானகத்தே வாழ்வான் றக', 1, 0),
(22022, 72, '15A.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 04:22:41', 0, 0, 'System', 'உணராமை யாற்குற்ற மோத்தான் வினையாம்<br/>\r\n		உணரான் வினைப்பிறப்புச் செய்யும் - உணராத<br/>\r\n		தொண்டிருந் துன்பந் தொடரும் பிறப்பினான்<br/>\r\n		மண்டிலமும் மாகு மதி', 1, 0),
(22023, 73, '16.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 04:23:20', 0, 0, 'System', 'மனைவாழ்க்கை மாதவ மென்றிரண்டும் மாண்ட<br/> \r\nவினைவாழ்க்கை யாக விழைப – மனைவாழ்க்கை<br/>\r\nபற்றுதல் லின்றி விடுதல்முற் சொல்லுமேல்<br/>\r\nபற்றுதல் பாத்திற வம்', 1, 0),
(22024, 74, '16.jpg', '', 'image/jpeg', 28, 22023, '2023-08-22 04:23:20', 0, 0, 'System', 'இடைவனப்புந் தோள்வனப்பு மீடின் வனப்பும்<br/>\r\n		நடைவனப்பு நாணின் வனப்பும் - புடைசால்<br/>\r\n		கழுத்தின் வனப்பும் வனப்பல்ல வெண்ணோ<br/>\r\n		டெழுத்தின் வனப்பே வனப்பு', 1, 0),
(22025, 75, '16A.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 04:23:57', 0, 0, 'System', 'அறுவர் தந்நூலு மறிந்துணர்வு பற்றி<br/>\r\n		மறுவரவு மாறான நீக்கி - மறுவரவின்<br/>\r\n		மாசா ரியனா மறுதலைச்சொல் மாற்றுதலே<br/>\r\n		ஆசா ரியன தமைவு', 1, 0),
(22026, 76, '16A.jpg', '', 'image/jpeg', 28, 22025, '2023-08-22 04:23:57', 0, 0, 'System', 'ஒல்லுவ நல்ல ருவவேற் கண்ணினாய்<br/>\r\n		வல்லுவ நாடி வகையினால் - சொல்லின்<br/>\r\n		கொடையினாற் போகஞ் சுவர்க்கந் தவத்தால்<br/>\r\n		அடையாத் தவத்தினால் வீடு', 1, 0),
(22027, 77, '17.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 04:24:41', 0, 0, 'System', 'நாற்கதியுந் துன்ப நவைதீர்த்தல் வேண்டுவான்<br/>\r\n		பாற்கதியின் பாற்பட  வாராய்ந்து - நூற்கதியின்<br/> \r\n		எல்லை யுயர்ந்தார் தவமுயலின் மூன்றைந்தேழ்<br/>\r\n		வல்லைவீ டாகும் வகு', 1, 0),
(22028, 78, '17.jpg', '', 'image/jpeg', 28, 22027, '2023-08-22 04:24:41', 0, 0, 'System', 'தாயிழந்த பிள்ளை தலையிழந்த பெண்டாட்டி<br/>\r\n		வாயிழந்த வாழ்வினார் வாணிகம் - போயிழந்தார்<br/>\r\n		கைத்தூண் பொருளிழந்தார் கண்ணிலவர்க் கீய்ந்தார்<br/>\r\n		வைத்து வழங்கி வாழ்வார்', 1, 0),
(22029, 79, '17A.jpg', '', 'image/jpeg', 28, 0, '2023-08-22 04:25:11', 0, 0, 'System', 'சாக்காடு கேடு பகைதுன்ப மின்பமே<br/>\r\n		நாக்காடு நாட்டறை போக்குமென - நாக்காட்ட<br/>\r\n		நட்டார்க் கியையிற் றமக்கியைந்த கூறுடம்<br/>\r\n		பட்டார்வாய்ப் பட்டது பண்பு', 1, 0),
(22030, 80, '17A.jpg', '', 'image/jpeg', 28, 22029, '2023-08-22 04:25:11', 0, 0, 'System', 'புலையாளர் புண்பட்டார் கண்கெட்டார் போக்கில்<br/>\r\n		நிலையாளர் நீர்மை யிழந்தார் - தலையாளர்க் <br/>\r\n		கூண்கொடுத் தூற்றா யுதவினார் மன்னராய்க்<br/>\r\n		காண்கொடுத்து வாழ்வார் கலந்து', 1, 0),
(22032, 2, '3.jpg', '', 'image/jpeg', 30, 22031, '2023-08-24 02:46:11', 0, 0, 'System', 'தன்குணங் குன்றாத் தகைமையுந் தாவில்சீ<br/>\r\nரின்குணத்தா ரேவின செய்தலு - நன்குணர்வி<br/>\r\nனான்மறை யாளர் வழிச்செலவு மிம்மூன்று<br/>\r\nமேன்முறை யாளர் தொழில்', 1, 0),
(22033, 3, '4.jpg', '', 'image/jpeg', 30, 0, '2023-08-24 05:24:52', 0, 0, 'System', 'கல்லார்க் கினனா யொழுகலுங் காழ்கொண்ட<br/>\r\nவில்லாளைக் கோலாற் புடைத்தலு - மில்லஞ்<br/>\r\nசிறியாரைக் கொண்டு புகலுமிம் மூன்று<br/>\r\nமறியாமை யான்வருங் கேடு', 1, 0),
(22034, 4, '4.jpg', '', 'image/jpeg', 30, 22033, '2023-08-24 05:24:52', 0, 0, 'System', 'பகைமுன்னர் வாழ்க்கை செயலுந் தொகைநின்ற<br/>\r\nபெற்றத்துட் கோலின்றிச் சேறலு - முற்றன்னைக்<br/>\r\nகாய்வானைக் கைவாங்கிக் கோடலு மிம்மூன்றுஞ்<br/>\r\nசாவ வுறுவான் றொழில்', 1, 0),
(22035, 5, '4.jpg', '', 'image/jpeg', 30, 22033, '2023-08-24 05:24:52', 0, 0, 'System', 'வழங்காத் துறையிழிந்து நீர்ப்போக்கு மொப்ப<br/>\r\nவிழைவிலாப் பெண்டீர்தோள் சேர்வு - முழந்து<br/>\r\nவிருந்தினனாய் வேற்றூர் புகலுமிம் மூன்று<br/>\r\nமருந்துயரங் காட்டு நெறி	', 1, 0),
(22036, 6, '4.jpg', '', 'image/jpeg', 30, 22033, '2023-08-24 05:24:52', 0, 0, 'System', 'பிறர்தன்னைப் பேணுங்கா னாணலும் பேணார்<br/>\r\nதிறன்வேறு கூறிற் பொறையு - மறவினையைக்<br/>\r\nகாராண்மை போல வொழுகலு மிம்மூன்று<br/>\r\nமூராண்மை யென்னுஞ் செருக்கு', 1, 0),
(22037, 7, '5.jpg', '', 'image/jpeg', 30, 0, '2023-08-24 05:25:47', 0, 0, 'System', 'வாளைமீ னுள்ள றலைப்படலு மாளல்லான்<br/>\r\nசெல்வக் குடியுட் பிறத்தலும் - பல்லவையு<br/>\r\nளஞ்சுவான் கற்ற வருநூலு மிம்மூன்றுந்<br/>\r\nதுஞ்சூமன் கண்ட கனா', 1, 0),
(22038, 8, '5.jpg', '', 'image/jpeg', 30, 22037, '2023-08-24 05:25:47', 0, 0, 'System', 'தொல்லவையுட் டோன்றுங் குடிமையுந் தொக்கிருந்த<br/>\r\nநல்லவையுண் மேம்பட்ட கல்வியும் - வெல்சமத்து<br/>\r\nவேந்துவப்ப வட்டார்த்த வென்றியு மிம்மூன்றுந்<br/>\r\nதாந்தம்மைக் கூறாப் பொருள்', 1, 0),
(22039, 9, '5.jpg', '', 'image/jpeg', 30, 22037, '2023-08-24 05:25:47', 0, 0, 'System', 'பெருமை யுடையா ரினத்தி னகற<br/>\r\nலுரிமையில் பெண்டீரைக் காமுற்று வாழ்தல்<br/>\r\nவிழுமிய வல்ல துணிதலிம் மூன்று<br/>\r\nமுழுமக்கள் காத லவை', 1, 0),
(22040, 10, '6.jpg', '', 'image/jpeg', 30, 0, '2023-08-24 05:27:01', 0, 0, 'System', 'கணக்காய ரில்லாத வூரும் பிணக்கறுக்கு<br/>\r\nமூத்தோரை யில்லா வவைக்களனும் - பாத்துண்ணுந்<br/>\r\nதன்மையி லாள ரயலிருப்பு மிம்மூன்று<br/>\r\nநன்மை பயத்த லில', 1, 0),
(22041, 11, '6.jpg', '', 'image/jpeg', 30, 22040, '2023-08-24 05:27:01', 0, 0, 'System', 'விளியாதான் கூத்தாட்டுக் காண்டலும் வீழக்<br/>\r\nகளியாதான் காவா துரையுந் - தெளியாதான்<br/>\r\nகூரையுட் பல்காலுஞ் சேறலு மிம்மூன்று<br/>\r\nமூரெல்லா நோவ துடைத்து', 1, 0),
(22042, 12, '6.jpg', '', 'image/jpeg', 30, 22040, '2023-08-24 05:27:01', 0, 0, 'System', 'தாளாள னென்பான் கடன்படா வாழ்பவன்<br/>\r\nவேளாள னென்பான் விருந்திருக்க வுண்ணாதான்<br/>\r\nகோளாள னென்பான் மறவாதா னிம்மூவர்<br/>\r\nகேளாக வாழ்த லினிது', 1, 0),
(22043, 13, '7.jpg', '', 'image/jpeg', 30, 0, '2023-08-24 05:29:48', 0, 0, 'System', 'சீல மறிவா னிளங்கிளை சாலக்<br/>\r\nகுடியோம்பல் வல்லா னரசன் - வடுவின்றி<br/>\r\nமாண்ட குணத்தான் றவசியென் றிம்மூவர்<br/>\r\nயாண்டும் பெறற்கரி யார்', 1, 0),
(22044, 14, '7.jpg', '', 'image/jpeg', 30, 22043, '2023-08-24 05:29:48', 0, 0, 'System', 'இழுக்க லியல்பிற் றிளமை பழித்தவை<br/>\r\nசொல்லுதல் வற்றாகும் பேதைமை - யாண்டுஞ்<br/>\r\nசெறுவொடு நிற்குஞ் சிறுமையிம் மூன்றுங்<br/>\r\nகுறுகா ரறிவுடை யார்', 1, 0),
(22045, 15, '7.jpg', '', 'image/jpeg', 30, 22043, '2023-08-24 05:29:48', 0, 0, 'System', 'பொய்வழங்கி வாழும் பொறியறையுங் கைதிரிந்து<br/>\r\nதாழ்விடத்து நேர்கருதுந் தட்டையு - மூழினா<br/>\r\nலொட்டி வினைநலம் பார்ப்பானு மிம்மூவர்<br/>\r\nநட்கப் படாஅ தவர்', 1, 0),
(22046, 16, '8.jpg', '', 'image/jpeg', 30, 0, '2023-08-24 05:42:16', 0, 0, 'System', 'மண்ணின்மேல் வான்புகழ் நட்டானு மாசில்சீர்ப்<br/>\r\nபெண்ணினுட் கற்புடையாட் பெற்றானு - முண்ணுநீர்<br/>\r\nகூவல் குறைவின்றித் தொட்டானு மிம்மூவர்<br/>\r\nசாவா வுடம்பெய்தி னார்', 1, 0),
(22047, 17, '8.jpg', '', 'image/jpeg', 30, 22046, '2023-08-24 05:42:16', 0, 0, 'System', 'மூப்பின்க ணன்மைக் ககன்றானுங் கற்புடையாட்<br/>\r\nபூப்பின்கட் சாராத் தலைமகனும் - வாய்ப்பகையுட்<br/>\r\nசொல்வென்றி வேண்டு மிலிங்கியு மிம்மூவர்<br/>\r\nகல்விப் புணைகைவிட் டார்', 1, 0),
(22048, 18, '8.jpg', '', 'image/jpeg', 30, 22046, '2023-08-24 05:42:16', 0, 0, 'System', 'ஒருதலையான் வந்துறூஉ மூப்பும் புணர்ந்தார்க்<br/>\r\nகிருதலையு மின்னாப் பிரிவு - முருவினை<br/>\r\nயுள்ளுருக்கித் தின்னும் பெரும்பிணியு மிம்மூன்றுங்<br/>\r\nகள்வரி னஞ்சப் படும்', 1, 0),
(22049, 19, '9.jpg', '', 'image/jpeg', 30, 0, '2023-08-24 05:47:21', 0, 0, 'System', 'கொல்யானைக் கோடுங் குணமிலியு மெல்லிற்<br/>\r\nபிறன்கடை நின்றொழுகு வானு - மறந்தெரியா<br/>\r\nதாடும்பாம் பாட்டு மறிவிலியு மிம்மூவர்<br/>\r\nநாடுங்காற் றூங்கு பவர்', 1, 0),
(22050, 20, '9.jpg', '', 'image/jpeg', 30, 22049, '2023-08-24 05:47:21', 0, 0, 'System', 'ஆசை பிறன்கட் படுதலும் பாசம்<br/>\r\nபசிப்ப மடியைக் கொளலுங் - கதித்தொருவன்<br/>\r\nகல்லானென் றெள்ளப் படுதலு மிம்மூன்று<br/>\r\nமெல்லார்க்கு மின்னா தன', 1, 0),
(22051, 21, '9.jpg', '', 'image/jpeg', 30, 22049, '2023-08-24 05:47:21', 0, 0, 'System', 'வருவாயுட் கால்வழங்கி வாழ்தல் செருவாய்ப்பச்<br/>\r\nசெய்தவை நாடாச் சிறப்புடைமை - யெய்தப்<br/>\r\nபலநாடி நல்லவை கற்றலிம் மூன்று<br/>\r\nநலமாட்சி நல்லவர் கோள்', 1, 0),
(22052, 22, '9.jpg', '', 'image/jpeg', 30, 22049, '2023-08-24 05:47:21', 0, 0, 'System', 'பற்றென்னும் பாசத் தளையும் பலவழியும்<br/>\r\nபற்றறா தோடு மவாத்தேருந் - தெற்றெனப்<br/>\r\nபொய்த்துரை யென்னும் பகையிருளு மிம்மூன்றும்<br/>\r\nவித்தற வீடும் பிறப்பு', 1, 0),
(22053, 23, '10.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 11:44:58', 0, 0, 'System', 'தானங் கொடுக்குந் தகைமையு மானத்தார்<br/>\r\nகுற்றங் கடிந்த வொழுக்கமுந் - தெற்றெனப்<br/>\r\nபல்பொரு ணீங்கிய சிந்தையு மிம்மூன்று<br/>\r\nநல்வினை யார்க்குங் கயிறு.	', 1, 0),
(22054, 24, '10.jpg', '', 'image/jpeg', 30, 22053, '2023-08-26 11:44:58', 0, 0, 'System', 'காண்டகு மென்றோட் கணிகைவா யின்சொல்லுந்<br/>\r\nதூண்டிலி னுட்பொதிந்த தேரையு - மாண்டசீர்க்<br/>\r\nகாழ்த்த பகைவர் வணக்கமு மிம்மூன்று<br/>\r\nமாழ்ச்சிப் படுக்கு மளறு.	', 1, 0),
(22055, 25, '10.jpg', '', 'image/jpeg', 30, 22053, '2023-08-26 11:44:58', 0, 0, 'System', 'செருக்கினால் வாழுஞ் சிறியவனும் பைத்தகன்ற<br/>\r\nவல்குல் விலைபகரு மாய்தொடியு - நல்லவர்க்கு<br/>\r\nவைத்த வறப்புறங் கொண்டானு மிம்மூவர்<br/>\r\nகைத்துண்ணார் கற்றறிந் தார்.	', 1, 0),
(22056, 26, '11.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 11:46:45', 0, 0, 'System', 'ஒல்வ தறியும் விருந்தினனு மாருயிரைக்<br/>\r\nகொல்வ திடைநீக்கி வாழ்வானும் - வல்லிதிற்<br/>\r\nசீல மினிதுடைய வாசானு மிம்மூவர்<br/>\r\nஞால மெனப்படு வார்.', 1, 0),
(22057, 27, '11.jpg', '', 'image/jpeg', 30, 22056, '2023-08-26 11:46:45', 0, 0, 'System', 'உண்பொழுது நீராடி யுண்டலு மென்பெறினும்<br/>\r\nபால்பற்றிச் சொல்லா விடுதலுந் - தோல்வற்றிச்<br/>\r\nசாயினுஞ் சான்றாண்மை குன்றாமை யிம்மூன்றுந்<br/>\r\nதூஉய மென்பார் தொழில்.', 1, 0),
(22058, 28, '11.jpg', '', 'image/jpeg', 30, 22056, '2023-08-26 11:46:45', 0, 0, 'System', 'வெல்வது வேண்டி வெகுண்டுரைக்கு நோன்பிலியு<br/>\r\nமில்லது காமுற் றிருப்பானுங் - கல்வி<br/>\r\nசெவிக்குற்றம் பார்த்திருப் பானுமிம் மூவ<br/>\r\nருமிக்குத்திக் கைவருந்து வார்.	', 1, 0),
(22059, 29, '11.jpg', '', 'image/jpeg', 30, 22056, '2023-08-26 11:46:45', 0, 0, 'System', 'பெண்விழைந்து பின்செலினுந் தன்செலவிற் குன்றாமை<br/>\r\nகண்விழைந்து கையுறினுங் காதல் பொருட்கின்மை<br/>\r\nமண்விழைந்து வாழ்நாண் மதியாமை யிம்மூன்று<br/>\r\nநுண்விழைந்த நூலவர் நோக்கு.', 1, 0),
(22060, 30, '12.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 11:49:45', 0, 0, 'System', 'தன்னச்சிச் சென்றாரை யெள்ளா வொருவனு<br/>\r\nமன்னிய செல்வத்துப் பொச்சாப்பு நீத்தானு<br/>\r\nமென்று மழுக்கா றிகந்தானு மிம்மூவர்<br/>\r\nநின்ற புகழுடை யார்', 1, 0),
(22061, 31, '12.jpg', '', 'image/jpeg', 30, 22060, '2023-08-26 11:49:45', 0, 0, 'System', 'பல்லவையு ணல்லவை கற்றலும் பாத்துண்டாங்<br/>\r\nகில்லற முட்டா தியற்றலும் - வல்லிதிற்<br/>\r\nறாளி னொருபொரு ளாக்கலு மிம்மூன்றுங்<br/>\r\nகேள்வியு ளெல்லாந் தலை', 1, 0),
(22062, 32, '12.jpg', '', 'image/jpeg', 30, 22060, '2023-08-26 11:49:45', 0, 0, 'System', 'நுண்மொழி நோக்கிப் பொருள்கொளலு நூற்கேலா<br/>\r\nவெண்மொழி வேண்டினுஞ் சொல்லாமை - நன்மொழியைச்<br/>\r\nசிற்றின மல்லார்கட் சொல்லலு மிம்மூன்றுங்<br/>\r\nகற்றறிந்தார் பூண்ட கடன்', 1, 0),
(22063, 33, '13.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 11:51:09', 0, 0, 'System', 'கோலஞ்சி வாழுங் குடியுங் குடிதழீஇ<br/>\r\nயாலம்வீழ் போலு மமைச்சனும் - வேலின்<br/>\r\nகடைமணிபோற் றிண்ணியான் காப்புமிம் மூன்றும்<br/>\r\nபடைவேந்தன் பற்று விடல்', 1, 0),
(22064, 34, '13.jpg', '', 'image/jpeg', 30, 22063, '2023-08-26 11:51:09', 0, 0, 'System', 'மூன்று கடன்கழித்த பார்ப்பானு மோர்ந்து<br/>\r\nமுறைநிலை கோடா வரசுஞ் - சிறைநின்<br/>\r\nறலவலை யில்லாக் குடியுமிம் மூவ<br/>\r\nருலக மெனப்படு வார்', 1, 0),
(22065, 35, '13.jpg', '', 'image/jpeg', 30, 22063, '2023-08-26 11:51:09', 0, 0, 'System', 'முந்நீர்த் திரையி னெழுந்தியங்கா மேதையு<br/>\r\nநுண்ணூற் பெருங்கேள்வி நூற்கரை கண்டானு<br/>\r\nமைந்நீர்மை யின்றி மயலறுப்பா னிம்மூவர்<br/>\r\nமெய்ந்நீர்மை மேனிற் பவர்', 1, 0),
(22066, 36, '14.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 11:53:16', 0, 0, 'System', 'ஊனுண் டுயிர்கட் கருளுடையே மென்பானுந்<br/>\r\nதானுடன்பா டின்றி வினையாக்கு மென்பானுங்<br/>\r\nகாமுறு வேள்வியிற் கொல்வானு மிம்மூவர்<br/>\r\nதாமறிவர் தாங்கண்ட வாறு', 1, 0),
(22067, 37, '14.jpg', '', 'image/jpeg', 30, 22066, '2023-08-26 11:53:16', 0, 0, 'System', 'குறளையு ணட்பளவு தோன்று முறலினிய<br/>\r\nசால்பினிற் றோன்றுங் குடிமையும் - பால்போலுந்<br/>\r\nதூய்மையுட் டோன்றும் பிரமாண மிம்மூன்றும்<br/>\r\nவாய்மை யுடையார் வழக்கு', 1, 0),
(22068, 38, '14.jpg', '', 'image/jpeg', 30, 22066, '2023-08-26 11:53:16', 0, 0, 'System', 'தன்னை வியந்து தருக்கலுந் தாழ்வின்றிக்<br/>\r\nகொன்னே வெகுளி பெருக்கலு - முன்னிய<br/>\r\nபல்பொருள் வெஃகுஞ் சிறுமையு மிம்மூன்றுஞ்<br/>\r\nசெல்வ முடைக்கும் படை', 1, 0),
(22069, 39, '15.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:12:03', 0, 0, 'System', 'புலைமயக்கம் வேண்டிப் பொருட்பெண்டிர்த் தோய்தல்<br/>\r\nகலமயக்கங் கள்ளுண்டு வாழ்தல் - சொலைமுனிந்து<br/>\r\nபொய்ம்மயக்கஞ் சூதின்கட் டங்க லிம்மூன்று<br/>\r\nநன்மையி லாளர் தொழில்', 1, 0),
(22070, 40, '15.jpg', '', 'image/jpeg', 30, 22069, '2023-08-26 12:12:03', 0, 0, 'System', 'வெகுளி நுணுக்கும் விறலு மகளீர்கட்<br/>\r\nகொத்த வொழுக்க முடைமையும் - பாத்துண்ணு<br/>\r\nநல்லறி வாண்மை தலைப்படலு மிம்மூன்றுந்<br/>\r\nதொல்லறி வாளர் தொழில்', 1, 0),
(22071, 41, '15.jpg', '', 'image/jpeg', 30, 22069, '2023-08-26 12:12:03', 0, 0, 'System', 'அலந்தார்க்கொன் றீந்த புகழுந் துளங்கினுந்<br/>\r\nதன்குடிமை குன்றாத் தகைமையு - மன்போடி<br/>\r\nநாணாளு நட்டார்ப் பெருக்கலு மிம்மூன்றுங்<br/>\r\nகேள்வியு ளெல்லாந் தலை', 1, 0),
(22072, 42, '15.jpg', '', 'image/jpeg', 30, 22069, '2023-08-26 12:12:03', 0, 0, 'System', 'கழகத்தால் வந்த பொருள்கா முறாமை<br/>\r\nபழகினும் பார்ப்பாரைத் தீப்போ லொழுக<br/>\r\nலுழவின்கட் காமுற்று வாழ்தலிம் மூன்று<br/>\r\nமழகென்ப வேளாண் குடிக்கு', 1, 0),
(22073, 43, '16.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:13:46', 0, 0, 'System', 'வாயி னடங்குத றுப்புரவா மாசற்ற<br/>\r\nசெய்கை யடங்குத றிப்பியமாம் - பொய்யின்றி<br/>\r\nநெஞ்ச மடங்குதல் வீடாகு மிம்மூன்றும்<br/>\r\nவஞ்சத்திற் றீர்ந்த பொருள்', 1, 0),
(22074, 44, '16.jpg', '', 'image/jpeg', 30, 22073, '2023-08-26 12:13:46', 0, 0, 'System', 'விருந்தின்றி யுண்ட பகலுந் திருந்திழையார்<br/>\r\nபுல்லப் புடைபெயராக் கங்குலு - மில்லார்க்கொன்<br/>\r\nறீயா தொழிந்தகன்ற காலையு மிம்மூன்று<br/>\r\nநோயே யுரனுடை யார்க்கு', 1, 0),
(22075, 45, '16.jpg', '', 'image/jpeg', 30, 22073, '2023-08-26 12:13:46', 0, 0, 'System', 'ஆற்றானை யாற்றென் றலைப்பானு மன்பின்றி<br/>\r\nயேற்றார்க் கியைவ கரப்பானுங் - கூற்றம்<br/>\r\nவரவுண்மை சிந்தியா தானுமிம் மூவர்<br/>\r\nநிரயத்துச் சென்றுவீழ் வார்', 1, 0),
(22076, 46, '17.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:15:15', 0, 0, 'System', 'காறூய்மை யில்லாக் கலிமாவுங் காழ்கடிந்து<br/>\r\nமேறூய்மை யில்லாத வெல்களிறுஞ் - சீறிக்<br/>\r\nகறுவி வெகுண்டுரைப்பான் பள்ளியிம் மூன்றுங்<br/>\r\nகுறுகா ரறிவுடை யார்', 1, 0),
(22077, 47, '17.jpg', '', 'image/jpeg', 30, 22076, '2023-08-26 12:15:15', 0, 0, 'System', 'சில்சொற் பெருந்தோண் மகளிரும் பல்வகையுந்<br/>\r\nதாளினாற் றந்த விழுநிதியு - நாடோறு<br/>\r\nநாத்தளிர்ப்ப வாக்கிய வுண்டியு மிம்மூன்றுங்<br/>\r\nகாப்பிகழ லாகாப் பொருள்', 1, 0),
(22078, 48, '17.jpg', '', 'image/jpeg', 30, 22076, '2023-08-26 12:15:15', 0, 0, 'System', 'வைததனை யின்சொல்லாக் கொள்வானு நெய்பெய்த<br/>\r\nசோறென்று கூழை மதிப்பானு - மூறிய<br/>\r\nகைப்பதனைக் கட்டியென் றுண்பானு மிம்மூவர்<br/>\r\nமெய்ப்பொருள் கண்டுவாழ் வார்', 1, 0),
(22079, 49, '18.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:17:14', 0, 0, 'System', 'ஏவாது மாற்று மிளங்கிளையுங் காவாது<br/>\r\nவைதெள்ளிச் சொல்லுந் தலைமகனும் - பொய்தெள்ளி<br/>\r\nயம்மனை தேய்க்கு மனையாளு மிம்மூவ<br/>\r\nரிம்மைக் குறுதியில் லார்', 1, 0),
(22080, 50, '18.jpg', '', 'image/jpeg', 30, 22079, '2023-08-26 12:17:14', 0, 0, 'System', 'கொள்பொருள் வெஃகிக் குடியலைக்கும் வேந்தனு<br/>\r\nமுள்பொருள் சொல்லாச் சலமொழி மாந்தரு<br/>\r\nமில்லிருந் தெல்லை கடப்பாளு மிம்மூவர்<br/>\r\nவல்லே மழையருக்குங் கோள்', 1, 0),
(22081, 51, '18.jpg', '', 'image/jpeg', 30, 22079, '2023-08-26 12:17:14', 0, 0, 'System', 'தூர்ந்தொழுகிக் கண்ணுந் துணைக டுணைகளே<br/>\r\nசார்ந்தொழுகிக் கண்ணுஞ் சலவர் சலவரே<br/>\r\nயீர்ந்தகல் லின்னாக் கயவ ரிவர்மூவர்,<br/>\r\nதேர்ந்தக்காற் றோன்றும் பொருள்', 1, 0),
(22082, 52, '18.jpg', '', 'image/jpeg', 30, 22079, '2023-08-26 12:17:14', 0, 0, 'System', 'கண்ணுக் கணிகலங் கண்ணோட்டங் காமுற்ற<br/>\r\nபெண்ணுக் கணிகல நாணுடைமை - நண்ணு<br/>\r\nமறுமைக் கணிகலங் கல்வியிம் மூன்றுங்<br/>\r\nகுறியுடையார் கண்ணே யுள', 1, 0),
(22083, 53, '19.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:18:51', 0, 0, 'System', 'குருடன் மனையா ளழகு மிருடீரக்<br/>\r\nகற்றறி வில்லான் கதழ்ந்துரையும் - பற்றிய<br/>\r\nபண்ணிற் றெரியாதான் யாழ்கேட்பு மிம்மூன்று<br/>\r\nமெண்ணிற் றெரியாப் பொருள்', 1, 0),
(22084, 54, '19.jpg', '', 'image/jpeg', 30, 22083, '2023-08-26 12:18:51', 0, 0, 'System', 'தன்பயந் தூக்காரைச் சார்தலுந் தாம்பயவா<br/>\r\nநன்பயங் காய்வின்கட் கூறலும் - பின்பயவாக்<br/>\r\nகுற்றம் பிறர்மே லுரைத்தலு மிம்மூன்றுந்<br/>\r\nதெற்றென வில்லார் தொழில்', 1, 0),
(22085, 55, '19.jpg', '', 'image/jpeg', 30, 22083, '2023-08-26 12:18:51', 0, 0, 'System', 'அருமறை காவாத நட்பும் பெருமையை<br/>\r\nவேண்டாது விட்டொழிந்த பெண்பாலும் - யாண்டானுஞ்<br/>\r\nசெற்றங்கொண் டாடுஞ் சிறுதொழும்பு மிம்மூவ<br/>\r\nரொற்றா ளெனப்படு வார்', 1, 0),
(22086, 56, '20.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:45:42', 0, 0, 'System', 'முந்தை யெழுத்தின் வரவுணர்ந்து பிற்பாடு<br/>\r\nதந்தையுந் தாயும் வழிபட்டு - வந்த<br/>\r\nவொழுக்கம் பெருநெறி சேர்தலிம் மூன்றும்<br/>\r\nவிழுப்ப நெறிதூரா வாறு', 1, 0),
(22087, 57, '20.jpg', '', 'image/jpeg', 30, 22086, '2023-08-26 12:45:42', 0, 0, 'System', 'கொட்டி யளந்தமையாப் பாடலுந் தட்டித்துப்<br/>\r\nபிச்சைபுக் குண்பான் பிளிற்றலுந் - துச்சிருந்தா<br/>\r\nனாளுங் கலங்கா முறுதலு மிம்மூன்றுங்<br/>\r\nகேள்வியு ளின்னா தன', 1, 0),
(22088, 58, '20.jpg', '', 'image/jpeg', 30, 22086, '2023-08-26 12:45:42', 0, 0, 'System', 'பழமையை நோக்கி யளித்தல் கிழமையாற்<br/>\r\nகேளீ ருவப்பத் தழுவுதல் - கேளீராய்த்<br/>\r\nதுன்னிய சொல்லா லினந்திரட்ட லிம்மூன்று<br/>\r\nமன்னற் கிளையான் றொழில்', 1, 0),
(22089, 59, '21.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:46:49', 0, 0, 'System', 'கிளைஞர்க் குதவாதான் செல்வமும் பைங்கூழ்<br/>\r\nவிளைவின்கட் போற்றா  னுழவு - மிளையனாய்க்<br/>\r\nகள்ளுண்டு வாழ்வான் குடிமையு மிம்மூன்று<br/>\r\nமுள்ளன போலக் கெடும்', 1, 0),
(22090, 60, '21.jpg', '', 'image/jpeg', 30, 22089, '2023-08-26 12:46:49', 0, 0, 'System', 'பேஎய்ப் பிறப்பிற் பெரும்பசியும் பாஅய்<br/>\r\nவிலங்கின் பிறப்பின் வெருவும் - புலந்தெரியா<br/>\r\nமக்கட் பிறப்பி னிரப்பிடும்பை யிம்மூன்றுந்<br/>\r\nதுக்கப் பிறப்பாய் விடும்', 1, 0),
(22091, 61, '21.jpg', '', 'image/jpeg', 30, 22089, '2023-08-26 12:46:49', 0, 0, 'System', 'ஐயறிவுந் தம்மை யடைய வொழுகுத<br/>\r\nலெய்துவ தெய்தாமை முற்காத்தல் - வைகலு<br/>\r\nமாறேற்கு மன்னர் நிலையறித லிம்மூன்றுஞ்<br/>\r\nசீரேற்ற பேரமைச்சர் கோள்', 1, 0),
(22092, 62, '21.jpg', '', 'image/jpeg', 30, 22089, '2023-08-26 12:46:49', 0, 0, 'System', 'நன்றிப் பயன்றூக்கா நாணிலியுஞ் சான்றோர்முன்<br/>\r\nமன்றிற் கொடும்பா டுரைப்பானு - நன்றின்றி<br/>\r\nவைத்த வடைக்கலங் கொள்வானு மிம்மூவ<br/>\r\nரெச்ச மிழந்துவாழ் வார்', 1, 0),
(22093, 63, '22.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:48:14', 0, 0, 'System', 'நோவஞ்சா தாரோடு நட்பும் விருந்தஞ்சு<br/>\r\nமீர்வளையை யில்லத் திருத்தலுஞ் - சீர்பயவாத்<br/>\r\nதன்மையி லாள ரயலிருப்பு மிம்மூன்று<br/>\r\nநன்மை பயத்த லில', 1, 0),
(22094, 64, '22.jpg', '', 'image/jpeg', 30, 22093, '2023-08-26 12:48:14', 0, 0, 'System', 'நல்விருந் தோம்பலி னட்டாளாம் வைகலு<br/>\r\nமில்புறஞ் செய்தலி னீன்றதாய் - தொல்குடியின்<br/>\r\nமக்கட் பெறலின் மனைக்கிழத்தி யிம்மூன்றுங்<br/>\r\nகற்புடையாள் பூண்ட கடன்', 1, 0),
(22095, 65, '22.jpg', '', 'image/jpeg', 30, 22093, '2023-08-26 12:48:14', 0, 0, 'System', 'அச்ச மலைகடலிற் றோன்றலு மார்வுற்ற<br/>\r\nவிட்டகல கில்லாத வேட்கையுங் - கட்டிய<br/>\r\nமெய்ந்நிலை காணா வெகுளியு மிம்மூன்றுந்<br/>\r\nதந்நெய்யிற் றாம்பொரியு மாறு', 1, 0),
(22096, 66, '23.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:49:37', 0, 0, 'System', 'கொழுநனை யில்லாள் கறையும் வழிநிற்குஞ்<br/>\r\nசிற்றாளில் லாதான்கைம் மோதிரமும் - பற்றிய<br/>\r\nகோல்கோடி வாழு மரசனு மிம்மூன்றுஞ்<br/>\r\nசால்போடு பட்ட தில', 1, 0),
(22097, 67, '23.jpg', '', 'image/jpeg', 30, 22096, '2023-08-26 12:49:37', 0, 0, 'System', 'எதிர்நிற்கும் பெண்ணு மியல்பி றொழும்புஞ்<br/>\r\nசெயிர்நிற்குஞ் சுற்றமு மாகி - மயிர்நரைப்ப<br/>\r\nமுந்தைப் பழவினையாய்த் தின்னு மிவைமூன்று<br/>\r\nநொந்தார் செயக்கிடந்த தில்', 1, 0),
(22098, 68, '23.jpg', '', 'image/jpeg', 30, 22096, '2023-08-26 12:49:37', 0, 0, 'System', 'இல்லார்க்கொன் றீயு முடைமையு மிவ்வுலகி<br/>\r\nனில்லாமை யுள்ளு நெறிப்பாடு மெவ்வுயிர்க்குந்<br/>\r\nதுன்புறுவ செய்யாத தூய்மையு - மிம்மூன்று<br/>\r\nநன்றறியு மாந்தர்க் குள', 1, 0),
(22099, 69, '24.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:50:58', 0, 0, 'System', 'அருந்தொழி லாற்றும் பகடுந் திருந்திய<br/>\r\nமெய்நிறைந்து நீடிருந்த கன்னியு- நொந்து<br/>\r\nநெறிமாறி வந்த விருந்துமிம் மூன்றும்<br/>\r\nபெறுமா றரிய பொருள்', 1, 0),
(22100, 70, '24.jpg', '', 'image/jpeg', 30, 22099, '2023-08-26 12:50:58', 0, 0, 'System', 'காவோ டறக்குளந் தொட்டானு நாவினால்<br/>\r\nவேதங் கரைகண்ட பார்ப்பானுந் - தீதிகந்<br/>\r\nதொல்வதுபாத் துண்ணு மொருவனு மிம்மூவர்<br/>\r\nசெல்வ ரெனப்படு வார்', 1, 0),
(22101, 71, '24.jpg', '', 'image/jpeg', 30, 22099, '2023-08-26 12:50:58', 0, 0, 'System', 'உடுத்தாடை யில்லாதார் நீராட்டும் பெண்டீர்<br/>\r\nதொடுத்தாண்ட வைப்போர் புகலுங் - கொடுத்தளிக்கு<br/>\r\nமாண்மை யுடையவர் நல்குரவு மிம்மூன்றுங்<br/>\r\nகாண வரியவென் கண்', 1, 0),
(22102, 72, '24.jpg', '', 'image/jpeg', 30, 22099, '2023-08-26 12:50:58', 0, 0, 'System', 'நிறைநெஞ் சுடையானை நல்குர வஞ்சு<br/>\r\nமறனை நினைப்பானை யல்பொரு ளஞ்சு<br/>\r\nமறவனை யெவ்வுயிரு மஞ்சுமிம் மூன்றுந்<br/>\r\nதிறவதிற் றீர்ந்த பொருள்', 1, 0),
(22103, 73, '25.jpg', '', 'image/jpeg', 30, 0, '2023-08-26 12:56:27', 0, 0, 'System', 'இரந்துகொண் டொண்பொருள் செய்வ லென்பானும்<br/>\r\nபரந்தொழுகும் பெண்பாலைப் பாசமென் பானும்<br/>\r\nவிரிகட லூடுசெல் வானுமிம் மூவ<br/>\r\nரரிய துணிந்துவாழ் வார்', 1, 0),
(22104, 74, '25.jpg', '', 'image/jpeg', 30, 22103, '2023-08-26 12:56:27', 0, 0, 'System', 'கொலைநின்று தின்றொழுகு வானும் பெரியவர்<br/>\r\nபுல்லுங்காற் றான்புல்லும் பேதையு - மில்லெனக்கொன்<br/>\r\nறீகென் பவனை நகுவானு மிம்மூவர்<br/>\r\nயாதுங் கடைப்பிடியா தார்', 1, 0),
(22105, 75, '25.jpg', '', 'image/jpeg', 30, 22103, '2023-08-26 12:56:27', 0, 0, 'System', 'வள்ளன்மை பூண்டான்கட் செல்வமு முள்ளத்<br/>\r\nதுணர்வுடையா னோதிய நூலும் - புணர்வின்கட்<br/>\r\nடக்க தறியுந் தலைமகனு மிம்மூவர்<br/>\r\nபொத்தின்றிக் காழ்த்த மரம்', 1, 0),
(22106, 76, '26.jpg', '', 'image/jpeg', 30, 0, '2023-09-11 02:04:50', 0, 0, 'System', 'மாரிநாள் வந்த விருந்து மனம்பிறிதாய்க்<br/>\r\nகாரியத்திற் குன்றாக் கணிகையும் - வீரியத்து<br/>\r\nமாற்ற மறுத்துரைக்குஞ் சேவகனு மிம்மூவர்<br/>\r\nபோற்றற் கரியார் புரிந்து', 1, 0),
(22107, 77, '26.jpg', '', 'image/jpeg', 30, 22106, '2023-09-11 02:04:50', 0, 0, 'System', 'கயவரைக் கையிகழ்ந்து வாழ்த னயவரை<br/>\r\nநள்ளிருளுங் கைவிடா நட்டொழுக - றெள்ளி<br/>\r\nவடுவான வாராமற் காத்தலிம் மூன்றுங்<br/>\r\nகுடிமாசி லார்க்கே யுள', 1, 0),
(22108, 78, '26.jpg', '', 'image/jpeg', 30, 22106, '2023-09-11 02:04:50', 0, 0, 'System', 'தூய்மை யுடைமை துணிவாந் தொழிலகற்றும்<br/>\r\nவாய்மை யுடைமை வனப்பாகுந் - தீமை<br/>\r\nமனத்தினும் வாயினுஞ் சொல்லாமை மூன்றுந்<br/>\r\nதவத்திற் றருக்கினார் கோள்', 1, 0),
(22109, 79, '26.jpg', '', 'image/jpeg', 30, 22106, '2023-09-11 02:04:50', 0, 0, 'System', 'பழியஞ்சான் வாழும் பசுவு மழிவினாற்<br/>\r\nகொண்ட வருந்தவம் விட்டானுங் - கொண்டிருந்<br/>\r\nதில்லஞ்சி வாழு மெருது மிவர்மூவர்<br/>\r\nநெல்லுண்ட னெஞ்சிற்கோர் நோய்', 1, 0),
(22110, 80, '27.jpg', '', 'image/jpeg', 30, 0, '2023-09-11 02:28:41', 0, 0, 'System', 'முறைசெய்யான் பெற்ற தலைமையு நெஞ்சி<br/>\r\nனிறையிலான் கொண்ட தவமு - நிறையொழுக்கந்<br/>\r\nதேற்றாதான் பெற்ற வனப்பு மிவைமூன்றுந்<br/>\r\nதூற்றின்கட் டூவிய வித்து', 1, 0),
(22111, 81, '27.jpg', '', 'image/jpeg', 30, 22110, '2023-09-11 02:28:41', 0, 0, 'System', 'தோள்வழங்கி வாழுந் துறைபோற் கணிகையு<br/>\r\nநாள்கழகம் பார்க்கு நயமிலாச் சூதனும்<br/>\r\nவாசிகொண் டொண்பொருள் செய்வானு மிம்மூவ<br/>\r\nராசைக் கடலுளாழ் வார்', 1, 0),
(22112, 82, '27.jpg', '', 'image/jpeg', 30, 22110, '2023-09-11 02:28:41', 0, 0, 'System', 'சான்றாருட் சான்றா னெனப்படுத லெஞ்ஞான்றுந்<br/>\r\nதோய்ந்தாருட் டோய்ந்தா னெனப்படுதல் - பாய்ந்தெழுந்து<br/>\r\nகொள்ளாருட் கொள்ளாத கூறாமை யிம்மூன்று<br/>\r\nநல்லாள் வழங்கு நெறி', 1, 0),
(22113, 83, '28.jpg', '', 'image/jpeg', 30, 0, '2023-09-11 02:31:15', 0, 0, 'System', 'உப்பின் பெருங்குப்பை நீர்படியி னில்லாகு<br/>\r\nநட்பின் கொழுமுளை பொய்வழங்கி னில்லாகுஞ்<br/>\r\nசெப்ப முடையார் மழையனைய ரிம்மூன்றுஞ்<br/>\r\nசெப்ப நெறிதூரா வாறு', 1, 0),
(22114, 84, '28.jpg', '', 'image/jpeg', 30, 22113, '2023-09-11 02:31:15', 0, 0, 'System', 'வாய்நன் கமையாக் குளனும் வயிறாரத்<br/>\r\nதாய்முலை யுண்ணாக் குழவியுஞ் - சேய்மரபிற்<br/>\r\nகல்விமாண் பில்லாத மாந்தரு மிம்மூவர்<br/>\r\nநல்குரவு சேரப்பட் டார்', 1, 0),
(22115, 85, '28.jpg', '', 'image/jpeg', 30, 22113, '2023-09-11 02:31:15', 0, 0, 'System', 'எள்ளப் படுமரபிற் றாகலு முள்பொருளைக்<br/>\r\nகேட்டு மறவாத கூர்மையு முட்டின்றி<br/>\r\nயுள்பொருள் சொல்லு முணர்ச்சியு மிம்மூன்று<br/>\r\nமொள்ளிய வொற்றாட் குணம்', 1, 0),
(22116, 86, '28.jpg', '', 'image/jpeg', 30, 22113, '2023-09-11 02:31:15', 0, 0, 'System', 'அற்புப் பெருந்தளை யாப்பு நெகிழ்ந்தொழிதல்<br/>\r\nகற்புப் பெரும்புணை காதலிற் கைவிடுதல்<br/>\r\nநட்பி னயநீர்மை நீங்க லிவைமூன்றுங்<br/>\r\nகுற்றந் தரூஉம் பகை', 1, 0),
(22117, 87, '29.jpg', '', 'image/jpeg', 30, 0, '2023-09-11 02:32:52', 0, 0, 'System', 'கொல்வது தானஞ்சான் வேண்டலுங் கல்விக்<br/>\r\nககன்ற வினம்புகு வானு மிருந்து<br/>\r\nவிழுநிதி குன்றுவிப் பானுமிம் மூவர்<br/>\r\nமுழுமக்க ளாகற்பா லார்', 1, 0),
(22118, 88, '29.jpg', '', 'image/jpeg', 30, 22117, '2023-09-11 02:32:52', 0, 0, 'System', 'பிணிதன்னைத் தின்னுங்காற் றான்வருந்து மாறுந்<br/>\r\nதணிவில் பெருங்கூற் றுயிருண்ணு மாறும்<br/>\r\nபிணைசெல்வ மாண்பின் றியங்க லிவைமூன்றும்<br/>\r\nபுணையி னிலைகலக்கு மாறு', 1, 0),
(22119, 89, '29.jpg', '', 'image/jpeg', 30, 22117, '2023-09-11 02:32:52', 0, 0, 'System', 'அருளினை நெஞ்சத் தடைகொடா தானும்<br/>\r\nபொருளினைத் துவ்வான் புதைத்துவைப் பானு<br/>\r\nமிறந்தின்னா சொல்லகிற் பானுமிம் மூவர்<br/>\r\nபிறந்தும் பிறந்திலா தார்', 1, 0),
(22120, 90, '30.jpg', '', 'image/jpeg', 30, 0, '2023-09-11 02:34:45', 0, 0, 'System', 'ஈதற்குச் செய்க பொருளை யறநெறி<br/>\r\nசேர்தற்குச் செய்க பெருநூலை - யாது<br/>\r\nமருள்புரிந்து சொல்லுக சொல்லையிம் மூன்று<br/>\r\nமிருளுலகஞ் சேராத வாறு', 1, 0);
INSERT INTO `sv_songs` (`id`, `fid`, `fname`, `filename`, `filetype`, `cid`, `group_id`, `upload_date`, `down_counts`, `view_counts`, `author`, `description`, `status`, `trash`) VALUES
(22121, 91, '30.jpg', '', 'image/jpeg', 30, 22120, '2023-09-11 02:34:45', 0, 0, 'System', 'பெறுதிக்கட் பொச்சாந் துரைத்த லுயிரை<br/>\r\nயிறுதிக்கண் யாமிழந்தே மென்றன் - மறுவந்து<br/>\r\nதன்னுடம்பு கன்றுங்கா னாணுத லிம்மூன்று<br/>\r\nமன்னா வுடம்பின் குறி', 1, 0),
(22122, 92, '30.jpg', '', 'image/jpeg', 30, 22120, '2023-09-11 02:34:45', 0, 0, 'System', 'விழுத்திணைத் தோன்றா தவனு மெழுத்தினை<br/>\r\nயொன்று முணராத வேழையு - மென்று<br/>\r\nமிறந்துரை காமுறு வானுமிம் மூவர்<br/>\r\nபிறந்தும் பிறவா தவர்', 1, 0),
(22123, 93, '30.jpg', '', 'image/jpeg', 30, 22120, '2023-09-11 02:34:45', 0, 0, 'System', 'இருளாய்க் கழியு முலகமும் யாதுந்<br/>\r\nதெரியா துரைக்கும் வெகுள்வும் - பொருளல்ல<br/>\r\nகாதற் படுக்கும் விழைவு மிவைமூன்றும்<br/>\r\nபேதைமை வாழு முயிர்க்கு', 1, 0),
(22124, 94, '31.jpg', '', 'image/jpeg', 30, 0, '2023-09-11 02:37:31', 0, 0, 'System', 'நண்பிலார் மாட்டு நசைக்கிழமை செய்வானும்<br/>\r\nபெண்பாலைக் காப்பிகழும் பேதையும் - பண்பி<br/>\r\nலிழுக்கான சொல்லாடு வானுமிம் மூவ<br/>\r\nரொழுக்கங் கடைப்பிடியா தார்', 1, 0),
(22125, 95, '31.jpg', '', 'image/jpeg', 30, 22124, '2023-09-11 02:37:31', 0, 0, 'System', 'அறிவழுங்கத் தின்னும் பசிநோயு மாந்தர்<br/>\r\nசெறிவழுங்கத் தோன்றும் விழைவுஞ் - செறுநரின்<br/>\r\nவெவ்வுரை நோனா வெகுள்வு மிவைமூன்று<br/>\r\nநல்வினை நீக்கும் படை', 1, 0),
(22126, 96, '31.jpg', '', 'image/jpeg', 30, 22124, '2023-09-11 02:37:31', 0, 0, 'System', 'கொண்டான் குறிப்பறிவாள் பெண்டாட்டி கொண்டன<br/>\r\nசெய்வகை செய்வான் றவசி கொடிதொரீஇ<br/>\r\nநல்லவை செய்வா னரச னிவர்மூவர்<br/>\r\nபெய்யெனப் பெய்யு மழை', 1, 0),
(22127, 97, '32.jpg', '', 'image/jpeg', 30, 0, '2023-09-11 02:38:24', 0, 0, 'System', 'ஐங்குரவ ராணை மறுத்தலு மார்வுற்ற<br/>\r\nவெஞ்சாத நட்பினுட் பொய்வழக்கு - நெஞ்சமர்ந்த<br/>\r\nகற்புடை யாளைத் துறத்தலு மிம்மூன்று<br/>\r\nநற்புடையி லாளர் தொழில்', 1, 0),
(22128, 98, '32.jpg', '', 'image/jpeg', 30, 22127, '2023-09-11 02:38:24', 0, 0, 'System', 'செந்தீ முதல்வ ரறநினைந்து வாழ்தலும்<br/>\r\nவெஞ்சின வேந்தன் முறைநெறியிற் சேர்தலும்<br/>\r\nபெண்பால் கொழுநன் வழிச்செலவு மிம்மூன்றுந்<br/>\r\nதிங்கண்மும் மாரிக்கு வித்து', 1, 0),
(22129, 99, '32.jpg', '', 'image/jpeg', 30, 22127, '2023-09-11 02:38:24', 0, 0, 'System', 'கற்றாரைக் கைவிட்டு வாழ்தலுங் காமுற்ற<br/>\r\nபெட்டாங்கு செய்தொழுகும் பேதையு - முட்டின்றி<br/>\r\nயல்லவை செய்யு மலவலையு மிம்மூவர்<br/>\r\nநல்லுலகஞ் சேரா தவர்', 1, 0),
(22130, 100, '33.jpg', '', 'image/jpeg', 30, 0, '2023-09-11 02:39:17', 0, 0, 'System', 'பத்திமை சான்ற படையும் பலர்தொகினு<br/>\r\nமெத்துணையு மஞ்சா வெயிலரணும் - வைத்தமைந்த<br/>\r\nவெண்ணி னுலவா விழுநிதியு மிம்மூன்று<br/>\r\nமண்ணாளும் வேந்தர்க் குறுப்பு', 1, 0),
(22131, 1, '1.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 02:21:22', 0, 0, 'System', 'மன்னிய நாண்மீன் மதிகனலி யென்றிவற்றை<br/>\r\nமுன்னம் படைத்த முதல்வனைப் – பின்னரு<br/>\r\nமாதிரையா னாதிரையா னென்றென் றயருமா<br/>\r\nலூர்திரைநீர் வேலி யுலகு', 1, 0),
(22132, 2, '1.jpg', '', 'image/jpeg', 29, 22131, '2023-09-12 02:21:22', 0, 0, 'System', 'அள்ளற் பழனத் தரக்காம்பல் வாயவிழ<br/>\r\nவெள்ளந்தீப் பட்ட தெனவெரீஇப் – புள்ளினந்தங்<br/>\r\nகைச்சிறகாற் பார்ப்பொடுக்குங் கவ்வை யுடைத்தரோ<br/>\r\nநச்சிலைவேற் கோக்கோதை நாடு', 1, 0),
(22133, 3, '1.jpg', '', 'image/jpeg', 29, 22131, '2023-09-12 02:21:22', 0, 0, 'System', 'நந்தி னிளஞ்சினையும் புன்னைக் குவிமொட்டும்<br/>\r\nபந்த ரிளங்கமுகின் பாளையுஞ் – சிந்தித்<br/>\r\nதிகழ்முத்தம் போற்றோன்றுஞ் செம்மற்றே தென்ன<br/>\r\nனகைமுத்த வெண்குடையா னாடு', 1, 0),
(22134, 4, '1.jpg', '', 'image/jpeg', 29, 22131, '2023-09-12 02:21:22', 0, 0, 'System', 'காவ லுழவர் களத்தகத்துப் போரேறி<br/>\r\nநாவலோஒ வென்றழைக்கு நாளோதை – காவலன்றன்<br/>\r\nகொல்யானை மேலிருந்து கூற்றிசைத்தாற் போலுமே<br/>\r\nநல்யானைக் கோக்கிள்ளி நாடு', 1, 0),
(22135, 5, '1.jpg', '', 'image/jpeg', 29, 22131, '2023-09-12 02:21:22', 0, 0, 'System', 'களிகள் களிகட்கு நீட்டத்தங் கையாற்<br/>\r\nகளிகள் விதிர்த்திட்ட செங்கட் – டுளிகலந்<br/>\r\nதோங்கெழில் யானை மிதிப்பச்சே றாயிற்றே<br/>\r\nபூம்புனல் வஞ்சி யகம்', 1, 0),
(22136, 6, '1.jpg', '', 'image/jpeg', 29, 22131, '2023-09-12 02:21:22', 0, 0, 'System', 'மாலை விலைபகர்வார் கிள்ளிக் களைந்தபூச்<br/>\r\nசால மிகுவதோர் தன்மைத்தாய்க் – காலையே<br/>\r\nவிற்பயில் வானகம் போலுமே வேல்வளவன்<br/>\r\nபொற்பா ருறந்தை யகம்', 1, 0),
(22137, 7, '1.jpg', '', 'image/jpeg', 29, 22131, '2023-09-12 02:21:22', 0, 0, 'System', 'மைந்தரொ டூடி மகளிர் திமிர்ந்திட்ட<br/>\r\nகுங்கும வீர்ஞ்சாந்தின் சேறிழுக்கி – யெங்குந்<br/>\r\nதடுமாற லாகிய தன்மைத்தே தென்னன்<br/>\r\nநெடுமாடக் கூட லகம்', 1, 0),
(22138, 8, '1.jpg', '', 'image/jpeg', 29, 22131, '2023-09-12 02:21:22', 0, 0, 'System', 'மைந்தரொ டூடி மகளிர் திமிர்ந்திட்ட<br/>\r\nகுங்கும வீர்ஞ்சாந்தின் சேறிழுக்கி – யெங்குந்<br/>\r\nதடுமாற லாகிய தன்மைத்தே தென்னன்<br/>\r\nநெடுமாடக் கூட லகம்', 1, 0),
(22139, 9, 'null.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 02:22:31', 0, 0, 'System', 'வேரறுகை பம்பிச் சுரைபடர்ந்து வேளைபூத்<br/>\r\nதூரறிய லாகா கிடந்தனவே – போரின்<br/>\r\nமுகையவிழ்தார்க் கோதை முசிறியார் கோமா<br/>\r\nனகையிலைவேல் காய்த்தினார் நாடு', 1, 0),
(22140, 10, '1.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 02:23:54', 0, 0, 'System', 'இரியன் மகளி ரிலைஞெமலு ளீன்ற<br/>\r\nவரியிளஞ் செங்காற் குழவி – யரையிரவி<br/>\r\nலூமன்பா ராட்ட வுறங்கிற்றே செம்பியன்ற<br/>\r\nனாமம்பா ராட்டாதார் நாடு', 1, 0),
(22141, 11, '1a.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 02:25:01', 0, 0, 'System', 'வாகை வனமாலை சூடி யரசுறையு<br/>\r\nமோகை யுயர்மாடத் துள்ளிருந்து – கூகை<br/>\r\nபடுபேய்க்குப் பாட்டயரும் பண்பிற்றே தென்னன்<br/>\r\nவிடுமாற்றங் கொள்ளாதார் நாடு', 1, 0),
(22142, 12, '1a.jpg', '', 'image/jpeg', 29, 22141, '2023-09-12 02:25:01', 0, 0, 'System', 'பறைநிறை கொல்யானைப் பஞ்சவர்க்குப் பாங்காய்த்<br/>\r\nதிறைமுறையி னுய்யாதார் தேய – முறைமுறையி<br/>\r\nனான்போ யரிவையர்போ யாடவர்போ யாயீன்ற<br/>\r\nவீன்போ யுறையு மிடம்', 1, 0),
(22143, 13, '1a.jpg', '', 'image/jpeg', 29, 22141, '2023-09-12 02:25:01', 0, 0, 'System', 'பல்யானை மன்னர் படுதிறை தந்துய்ம்மின்<br/>\r\nமல்ல னெடுமதில் வாங்குவிற் பூட்டுமின்<br/>\r\nவள்ளிதழ் வாடாத வானோரும் வானவன்<br/>\r\nவில்லெழுதி வாழ்வர் விசும்பு', 1, 0),
(22144, 14, '1a.jpg', '', 'image/jpeg', 29, 22141, '2023-09-12 02:25:01', 0, 0, 'System', 'நேமி நிமிர்தோ ணிலவுதார்த் தென்னவன்<br/>\r\nகாமர் நெடுங்குடைக் காவல னாணையா<br/>\r\nலேம மணிப்பூ ணிமையார் திருந்தடி<br/>\r\n பூமி மிதியாப் பொருள்', 1, 0),
(22145, 15, 'null.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 02:25:17', 0, 0, 'System', 'நிறைமதிபோல் யானைமே னீலத்தார் மாறன்<br/>\r\nகுடைதோன்ற ஞாலத் தரசர் – திறைகொ<br/>\r\nளிறையோ வெனவந் திடம்பெறுத லின்றி<br/>\r\nமுறையோ வெனநின்றார் மொய்த்து', 1, 0),
(22146, 16, '1a.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 02:25:48', 0, 0, 'System', 'நின்றீமின் மன்னீர் நெருநற் றிறைகொணர்ந்து<br/>\r\nமுன்றந்த மன்னர் முடிதாக்க – வின்றுந்<br/>\r\nதிருந்தடி புண்ணாகிச் செவ்வி யிலனே<br/>\r\nபெருந்தண் ணுறந்தையார் கோ', 1, 0),
(22147, 17, 'null.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 02:26:30', 0, 0, 'System', 'செருவெங் கதிர்வேற் சினவெம்போர் மாற<br/>\r\nனுருமி னிடிமுர சார்ப்ப – வரவுறழ்ந்<br/>\r\nதாமா வுகளு மணிவரையி னப்புறம்போய்<br/>\r\nவேமால் வயிறெரிய வேந்து', 1, 0),
(22148, 18, 'null.jpg', '', 'image/jpeg', 29, 22147, '2023-09-12 02:26:30', 0, 0, 'System', 'நிரைகதிர்வேன் மாறனை நேர்நின்றார் யானைப்<br/>\r\nபுரைசை யறநிமிர்ந்து பொங்கா – வரசர்த<br/>\r\nமுன்முன்னா வீழ்ந்த முடிக ளுதைத்தமாப்<br/>\r\nபொன்னுரைகற் போன்ற குளம்பு', 1, 0),
(22149, 19, '1a.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 02:27:40', 0, 0, 'System', 'வீறுசான் மன்னர் விரிதாம வெண்குடையைப்<br/>\r\nபாற வெறிந்த பரிசயத்தாற் – றேறாது<br/>\r\nசெங்கண்மாக் கோதை சினவெங் களியானை<br/>\r\nதிங்கண்மே னீட்டுந்தன் கை', 1, 0),
(22150, 20, '1a.jpg', '', 'image/jpeg', 29, 22149, '2023-09-12 02:27:40', 0, 0, 'System', 'அயிற்கதவம் பாய்ந்துழக்கி யாற்றல்சான் மன்ன<br/>\r\nரெயிற்கதவங் கோத்தெடுத்த கோட்டாற் – பனிக்கடலுட்<br/>\r\nபாய்தோய்ந்த நாவாய்போற் றோன்றுமே யெங்கோமான்<br/>\r\nகாய்சினவேற் கிள்ளி களிறு', 1, 0),
(22151, 21, '2.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 02:31:17', 0, 0, 'System', 'மருப்பூசி யாக மறங்கனல்வேன் மன்ன<br/>\r\nருருத்தகு மார்போலை யாகத் – திருத்தக்க<br/>\r\nவையக மெல்லா மெமதென் றெழுதுமே<br/>\r\nமொய்யிலைவேன் மாறன் களிறு', 1, 0),
(22152, 22, '2.jpg', '', 'image/jpeg', 29, 22151, '2023-09-12 02:31:17', 0, 0, 'System', 'உருவத்தார்த் தென்னவ னோங்கெழில் வேழத்<br/>\r\nதிருகோடுஞ் செய்தொழி லெண்ணி – லொருகோடு<br/>\r\nவேற்றா ரகல முழுமே யொருகோடு<br/>\r\nமாற்றார் மதிறிறக்கு மால்', 1, 0),
(22153, 23, '2.jpg', '', 'image/jpeg', 29, 22151, '2023-09-12 02:31:17', 0, 0, 'System', 'கொடிமதில் பாய்ந்திற்ற கோடு மரசர்<br/>\r\nமுடியிடறித் தேய்ந்த நகமும் – பிடிமுன்பு<br/>\r\nபொல்லாமை நாணிப் புறங்கடை நின்றதே<br/>\r\nகல்லார்தோட் கிள்ளி களிறு', 1, 0),
(22154, 24, '2.jpg', '', 'image/jpeg', 29, 22151, '2023-09-12 02:31:17', 0, 0, 'System', 'கச்சி யொருகான் மிதியா வொருகாலாற்<br/>\r\nறத்துநீர்த் தண்ணுஞ்சை தான்மிதியாப் – பிற்றையு<br/>\r\nமீழ மொருகான் மிதியா வருமேநங்<br/>\r\nகோழியர்கோன் கிள்ளி களிறு', 1, 0),
(22155, 25, '2.jpg', '', 'image/jpeg', 29, 22151, '2023-09-12 02:31:17', 0, 0, 'System', 'பாற்றின மார்ப்பப் பருந்து வழிப்படர<br/>\r\nநாற்றிசையு மோடி நரிகதிப்ப – வாற்ற<br/>\r\nலலங்கலம் பேய்மகளி ராட வருமே<br/>\r\nயிலங்கிலைவேற் கிள்ளி களிறு', 1, 0),
(22156, 26, '2.jpg', '', 'image/jpeg', 29, 22151, '2023-09-12 02:31:17', 0, 0, 'System', 'தோற்ற மலைகட லோசை புயல்கடாஅங்<br/>\r\nகாற்றி னிமிர்ந்த செலவிற்றாய்க் – கூற்றுங்<br/>\r\nகுறியெதிர்ப்பை கொள்ளுந் தகைமைத்தே யெங்கோ<br/>\r\nனெறிகதிர்வேன் மாறன் களிறு', 1, 0),
(22157, 27, '2.jpg', '', 'image/jpeg', 29, 22151, '2023-09-12 02:31:17', 0, 0, 'System', 'அடிமதில் பாய வழிந்தன கோட்டைப்<br/>\r\nபிடிமுன் பழகழித னாணி – முடியுடை<br/>\r\nமன்னர் குடையான் மறைக்குமே செங்கனல்வேற்<br/>\r\nறென்னவர் கோமான் களிறு', 1, 0),
(22158, 28, 'null.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 05:00:28', 0, 0, 'System', 'இ(ள)ங்களி (றொ)ன்ற மடப்பிடி சார<br/>\r\nலி(ல)ங்கருவி நீராற் றெளி(த்தும்) – நலங்கிளர்வேற்<br/>\r\nறுன்னரும்போர்க் கோதை தொடா(அன்) செருக்கின<br/>\r\nமன்னர் மதிலாய வென்று', 1, 0),
(22159, 29, '2.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 05:15:21', 0, 0, 'System', 'வெருவரு வெஞ்சமத்து வேலிலங்க வீழ்ந்தார்<br/>\r\nபுருவ முரிவுகண் டஞ்சி – நரிவெரீஇச்<br/>\r\nசேட்கணித்தாய் நின்றழைக்குஞ் செம்மற்றே தென்னவன்<br/>\r\nவாட்கணித்தாய் வீழ்ந்தார் களம்', 1, 0),
(22160, 30, '2a.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 05:35:08', 0, 0, 'System', 'மரகதப்பூண் மன்னவர் தோள்வளை கீழா<br/>\r\nவயிரக் கடகக்கை வாங்கித் – துயருழந்து<br/>\r\nபுண்ணுற் றழைக்குங் குறுநரித்தே பூழியனைக்<br/>\r\nகண்ணுற்று வீழ்ந்தார் களம்', 1, 0),
(22161, 31, '2a.jpg', '', 'image/jpeg', 29, 22160, '2023-09-12 05:35:08', 0, 0, 'System', 'முடித்தலை வெள்ளோட்டு மூளைநெய் யாகத்<br/>\r\nதடித்த குடர்திரியா மாட்டி – யெடுத்தெடுத்துப்<br/>\r\nபேஎய் விளக்கயரும் பெற்றித்தே செம்பியன்<br/>\r\nசேஎய் பொருத களம்', 1, 0),
(22162, 32, '2.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 05:35:31', 0, 0, 'System', 'ஏனைய பெண்டி ரெரிமூழ்கக் கண்டுதன்<br/>\r\nறானையாற் கண்புதைத்தான் றார்வழுதி – யானையெலாம்<br/>\r\nபுல்லார் பிடிபுலம்பத் தாங்கண் புதைத்தவே<br/>\r\nபல்வாயார் பட்ட களத்து', 1, 0),
(22163, 33, 'null.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 05:35:56', 0, 0, 'System', 'கொடித்தலைத்தார்த் தென்னவன் றேற்றான்போ னின்றான்<br/>\r\nமடித்தவாய் சுட்டிய கையாற் – பிடித்தவேற்<br/>\r\nகண்ணேரா வோச்சிக் களிறணையாக் கண்படுத்த<br/>\r\nமண்ணேரா மன்னரைக் கண்டு', 1, 0),
(22164, 34, '2a.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 05:36:23', 0, 0, 'System', 'தொழிறேற்றாப் பாலகனை முன்னிறீஇப் பின்னின்<br/>\r\nறழலிலைவேல் காய்த்தினார் பெண்டிர் – கழலடைந்து<br/>\r\nமண்ணீத்த லென்ப வயங்குதார் மாமாறன்<br/>\r\nகண்ணீத்தந் தீர்க்கு மருந்து', 1, 0),
(22165, 35, 'null.jpg', '', 'image/jpeg', 29, 0, '2023-09-12 05:36:39', 0, 0, 'System', 'மடங்கா மயிலூர்தி மைந்தனை நாளுங்<br/>\r\nகடம்பம்பூக் கொண்டேத்தி யற்றாற் – றொடங்கமரு<br/>\r\nணின்றிலங்கு வென்றி நிறைகதிர்வேன் மாறனை<br/>\r\nயின்றமிழால் யாம்பாடும் பாட்டு', 1, 0),
(22166, 36, '2a.jpg', '', 'image/jpeg', 29, 0, '2023-09-13 03:15:30', 0, 0, 'System', 'செங்க ணெடியான்மேற் றேர்விசய னேற்றியபூப்<br/>\r\nபைங்கண்வெள் ளேற்றான்பாற் கண்டற்றா – லெங்கு<br/>\r\nமுடிமன்னர் சூடியபூ மொய்ம்மலர்த்தார் மாற<br/>\r\nனடிமிசையே காணப் படும்', 1, 0),
(22167, 37, '2a.jpg', '', 'image/jpeg', 29, 22166, '2023-09-13 03:15:30', 0, 0, 'System', 'கூந்தன்மா கொன்று குடமாடிக் கோவலனாய்ப்<br/>\r\nபூந்தொடியைப் புல்லிய ஞான்றுண்டால் – யாங்கொளித்தாய்<br/>\r\nதென்னவனே தேர்வேந்தே தேறுநீர்க் கூடலார்<br/>\r\nமன்னவனே மார்பின் மறு', 1, 0),
(22168, 38, 'null.jpg', '', 'image/jpeg', 29, 0, '2023-09-13 03:16:11', 0, 0, 'System', 'வானிற்கு வையகம் போன்றது வானத்து<br/>\r\nமீனிற் கனையார் மறமன்னர் – வானத்து<br/>\r\nமீன்சேர் மதியனையன் விண்ணுயர் கொல்லியர்<br/>\r\nகோன்சேரன் கோதையென் பான்', 1, 0),
(22169, 39, '2a.jpg', '', 'image/jpeg', 29, 0, '2023-09-13 03:17:13', 0, 0, 'System', 'மந்தரங் காம்பா மணிவிசும் போலையாத்<br/>\r\nதிங்க ளதற்கோர் திலதமா – வெங்கணு<br/>\r\nமுற்றுநீர் வைய முழுது நிழற்றுமே<br/>\r\nகொற்றப்போர்க் கிள்ளி குடை', 1, 0),
(22170, 40, 'null.jpg', '', 'image/jpeg', 29, 0, '2023-09-13 03:17:53', 0, 0, 'System', 'பார்படுப செம்பொன் பதிபடுப முத்தமிழ்நூ<br/>\r\nனீர்படுப வெண்சங்கு நித்திலமுஞ் – சாரன்<br/>\r\nமலைபடுப யானை வயமாறன் கூர்வேற்<br/>\r\nறலைபடுப தார்வேந்தர் மார்பு', 1, 0),
(22171, 41, 'null.jpg', '', 'image/jpeg', 29, 22170, '2023-09-13 03:17:53', 0, 0, 'System', 'அருமணி யைந்தலை யாடரவம் வானத்<br/>\r\nதுருமேற்றை யஞ்சி யொளிக்குஞ் – செருமிகுதோட்<br/>\r\nசெங்கண்மா மாறன் சினவேல் கனவுமே<br/>\r\nயங்கண்மா ஞாலத் தரசு', 1, 0),
(22172, 42, '2a.jpg', '', 'image/jpeg', 29, 0, '2023-09-13 03:19:09', 0, 0, 'System', 'அரும்பவிழ்தார்க் கோதை யரசெறிந்த வொள்வேல்<br/>\r\nபெரும்புலவுஞ் செஞ்சாந்து நாறிச்  - சுரும்பொடு<br/>\r\nவண்டாடு பக்கமு முண்டு குறுநரி<br/>\r\nகொண்டாடும் பக்கமு முண்டு', 1, 0),
(22173, 43, 'null.jpg', '', 'image/jpeg', 29, 0, '2023-09-13 03:20:07', 0, 0, 'System', 'கண்ணார் கதவந் திறமின் களிறொடுதேர்<br/>\r\nபண்ணார் நடைப்புரவி பண்விடுமி - னண்ணாதீர்<br/>\r\nதேர்வேந்தன் றென்னன் றிருவுத் திராடநாட்<br/>\r\nபோர்வேந்தன் பூச லிலன்', 1, 0),
(22174, 44, 'null.jpg', '', 'image/jpeg', 29, 22173, '2023-09-13 03:20:07', 0, 0, 'System', 'அந்தண ராவொடு பொன்பெற்றார் நாவலர்<br/>\r\nமந்தரம்போன் மாண்ட களிறூர்ந்தா - ரெந்தை<br/>\r\nயிலங்கிலைவேற் கிள்ளி யிரேவதிநா ளென்னோ<br/>\r\nசிலம்பிதன் கூடிழந்த வாறு', 1, 0),
(22175, 45, '2a.jpg', '', 'image/jpeg', 29, 0, '2023-09-13 03:22:47', 0, 0, 'System', 'செய்யா ரெனினுந் தமர்செய்வ ரென்னுஞ்சொன்<br/>\r\nமெய்யாதல் கண்டேன் விளங்கிழாய் - கையார்<br/>\r\nவரிவளை நின்றன வையையார் கோமான்<br/>\r\nபுரிவளை போந்தியம்பக் கேட்டு', 1, 0),
(22176, 46, '3.jpg', '', 'image/jpeg', 29, 0, '2023-09-13 03:39:47', 0, 0, 'System', 'திறந்திடுமின் றீயவை பிற்காண்டு மாத<br/>\r\nரிறந்து படிற்பெரிதா மேத - முறந்தையர்கோன்<br/>\r\nறண்ணார மார்பிற் றமிழர் பெருமானைக்<br/>\r\nகண்ணாரக் காணக் கதவு', 1, 0),
(22177, 47, '3.jpg', '', 'image/jpeg', 29, 22176, '2023-09-13 03:39:47', 0, 0, 'System', 'தாய ரடைப்ப மகளிர் திறந்திடத்<br/>\r\nதேயத் திரிந்த குடுமியவே - யாய்மலர்<br/>\r\nவண்டுலாஅங் கண்ணி வயமான்றேர்க் கோதையைக்<br/>\r\nகண்டுலாஅம் வீதிக் கதவு', 1, 0),
(22178, 48, '3.jpg', '', 'image/jpeg', 29, 22176, '2023-09-13 03:39:47', 0, 0, 'System', 'காப்படங்கென் றன்னை கடிமனை யிற்செறித்<br/>\r\nதியாப்படங்க வோடி யடைத்தபின்  - மாக்கடுங்கோ<br/>\r\nனன்னலங் காணக் கதவங் துளைதொட்டார்க்<br/>\r\nகென்னைகொல் கைம்மா றினி', 1, 0),
(22179, 49, '3.jpg', '', 'image/jpeg', 29, 22176, '2023-09-13 03:39:47', 0, 0, 'System', 'துடியடித் தோற்செவித் தூங்குகைந் நால்வாய்ப்<br/>\r\nபிடியேயா னின்னை யிரப்பல் - கடிகமழ்தார்ச்<br/>\r\nசேலேக வண்ணனொடு சேரி புகுதலுமெஞ்<br/>\r\nசாலேகஞ் சார நட', 1, 0),
(22180, 50, '3.jpg', '', 'image/jpeg', 29, 22176, '2023-09-13 03:39:47', 0, 0, 'System', 'எலாஅ மடப்பிடியே யெங்கூடற் கோமான்<br/>\r\nபுலாஅ னெடுநல்வேன் மாற - னுலாஅங்காற்<br/>\r\nபைய நடக்கவுந் தேற்றாயா னின்பெண்மை<br/>\r\nயையப் படுவ துடைத்து', 1, 0),
(22181, 51, '3.jpg', '', 'image/jpeg', 29, 22176, '2023-09-13 03:39:47', 0, 0, 'System', 'நீணீலத் தார்வளவ னின்மேலா னாகவு<br/>\r\nநாணின்மை யின்றி நடத்தியா - னீணீலங்<br/>\r\nகண்டன்ன கொண்டல் வருங்கா விரிநாட்டுப்<br/>\r\nபெண்டன்மை யில்லை பிடி', 1, 0),
(22182, 52, '3.jpg', '', 'image/jpeg', 29, 22176, '2023-09-13 03:39:47', 0, 0, 'System', 'சுடரிலைவேற் சோழன்றன் பாடல மேறிப்<br/>\r\nபடர்தந்தான் பைந்தொடியார் காணத் - தொடர்புடைய<br/>\r\nநீல வலையிற் கயல்போற் பிறழுமே<br/>\r\nசாலேக வாயிறொறுங் கண்', 1, 0),
(22183, 53, '3.jpg', '', 'image/jpeg', 29, 22176, '2023-09-13 03:39:47', 0, 0, 'System', 'போரகத்துப் பாயுமா பாயா துபாயமா<br/>\r\nவூரகத்து மெல்ல நடவாயோ - கூர்வேன்<br/>\r\nமதிவெங் களியானை மாறன்றன் மார்பங்<br/>\r\nகதவங்கொண் டியாமுந் தொழ\r\n', 1, 0),
(22184, 54, '3.jpg', '', 'image/jpeg', 29, 22176, '2023-09-13 03:39:47', 0, 0, 'System', 'ஆடுகோ சூடுகோ வைதாக் கலந்துகொண்<br/>\r\nடேடுகோ டாக வெழுதுகோ - நீடு<br/>\r\nபுனவட்டப் பூந்தெரியற் பொற்றேர் வழுதி<br/>\r\nகனவட்டங் கால்குடைந்த நீறு', 1, 0),
(22185, 55, '3a.jpg', '', 'image/jpeg', 29, 0, '2023-09-13 03:43:16', 0, 0, 'System', 'குடத்து விளக்கேபோற் கொம்பன்னார் காமம்<br/>\r\nபுறப்படா பூந்தார் வழுதி - புறப்படி<br/>\r\nனாபுகு மாலை யணிமலையிற் றீயேபோ<br/>\r\nனாடறி கௌவை தரும்', 1, 0),
(22186, 56, '3a.jpg', '', 'image/jpeg', 29, 22185, '2023-09-13 03:43:16', 0, 0, 'System', 'வரைபொரு நீண்மார்பின் வட்கார் வணக்கு<br/>\r\nநிரைபொரு வேன்மாந்தைக் கோவே - நிரைவளையார்<br/>\r\nதங்கோலம் வௌவுத லாமோ வவர்தாய்மார்<br/>\r\nசெங்கோல னல்ல னென', 1, 0),
(22187, 57, '3a.jpg', '', 'image/jpeg', 29, 22185, '2023-09-13 03:43:16', 0, 0, 'System', 'வாமான்றேர்க் கோதையை மான்றேர்மேற் கண்டவர்<br/>\r\nமாமையே யன்றோ விழப்பது - மாமையிற்<br/>\r\nபன்னூறு கோடி பழுதோவென் மேனியிற்<br/>\r\nபொன்னூறி யன்ன பசப்பு', 1, 0),
(22188, 58, '3a.jpg', '', 'image/jpeg', 29, 22185, '2023-09-13 03:43:16', 0, 0, 'System', 'வழுவிலெம் வீதியுண் மாறன் வருங்காற்<br/>\r\nறொழுதேனைத் தோணலமுங் கொண்டா - னிமிழ்திரைக்<br/>\r\nகார்க்கடற் கொற்கையார் காவலனுந் தானேயால்<br/>\r\nயார்க்கிடுகோ பூச லினி', 1, 0),
(22189, 59, '3a.jpg', '', 'image/jpeg', 29, 22185, '2023-09-13 03:43:16', 0, 0, 'System', 'கண்டன வுண்கண் கலந்தன நன்னெஞ்சந்<br/>\r\nதண்டப் படுவ தடமென்றோள் - கண்டா<br/>\r\nயுலாஅ மறுகி லுறையூர் வளவற்<br/>\r\nகெலாஅ முறைகிடந்த வாறு', 1, 0),
(22190, 60, '3a.jpg', '', 'image/jpeg', 29, 22185, '2023-09-13 03:43:16', 0, 0, 'System', 'மன்னுயிர் காவல் தனதான வவ்வுயிரு<br/>\r\nளென்னுயிரு மெண்ணப் படுமாயி - னென்னுயிர்க்கே<br/>\r\nசீரொழுகு செங்கோற் செழியற்கே தக்கதோ<br/>\r\nநீரொழுகப் பாலொழுகா வாறு', 1, 0),
(22191, 61, '3a.jpg', '', 'image/jpeg', 29, 22185, '2023-09-13 03:43:16', 0, 0, 'System', 'என்னெஞ்சு நாணு நலனு மிவையெல்லா<br/>\r\nமன்னன் புனனாடன் வௌவினா - னென்னே<br/>\r\nயரவக லல்குலா யாறிலொன் றன்றோ<br/>\r\nபுரவலர் கொள்ளும் பொருள்', 1, 0),
(22192, 62, '3a.jpg', '', 'image/jpeg', 29, 22185, '2023-09-13 03:43:16', 0, 0, 'System', 'தானேற் றனிக்குடைக் காவலனாற் காப்பதுவும்<br/>\r\nவானேற்ற வையக மெல்லாமால் - யானோ<br/>\r\nவெளியேனோர் பெண்பாலே னீர்ந்தண்டார் மாற<br/>\r\nனளியானே லன்றென்பா ரார்', 1, 0),
(22193, 63, '4.jpg', '', 'image/jpeg', 29, 0, '2023-09-13 05:40:07', 0, 0, 'System', 'கனவினுட் காண்கொடா கண்ணுங் கலந்த<br/>\r\nநனவினுண் முன்விலக்கு நாணு - மினவங்கம்<br/>\r\nபொங்கோதம் போழும் புகாஅர்ப் பெருமானார்<br/>\r\nசெங்கோல் வடுப்படுப்பச் சென்று', 1, 0),
(22194, 64, '4.jpg', '', 'image/jpeg', 29, 22193, '2023-09-13 05:40:07', 0, 0, 'System', 'தானைகொண் டோடுவ தாயிற்றன் செங்கோன்மை<br/>\r\nசேனை யறியக் கிளவேனோ - யானை<br/>\r\nபிடிவீசும் வண்டடக்கைப் பெய்தண்டார்க் கிள்ளி<br/>\r\nநெடுவீதி நேர்பட்ட போது', 1, 0),
(22195, 65, '4.jpg', '', 'image/jpeg', 29, 22193, '2023-09-13 05:40:07', 0, 0, 'System', 'தெண்ணீர் நறுமலர்த்தார்ச் சென்னி யிளவளவன்<br/>\r\nமண்ணகங் காவலனே யென்பரான் - மண்ணகங்<br/>\r\nகாவலனே யானக்காற் காவானோ மாலைவாய்க்<br/>\r\nகோவலர்வாய் வைத்த குழல்', 1, 0),
(22196, 66, '4.jpg', '', 'image/jpeg', 29, 22193, '2023-09-13 05:40:07', 0, 0, 'System', 'அறைபறை யானை யலங்குதார்க் கிள்ளி<br/>\r\nமுறைசெயு மென்பராற் றோழி - யிறையிறந்த<br/>\r\nவங்கோ லணிவளையே சொல்லாதோ மற்றவன்<br/>\r\nசெங்கோன்மை செந்நின்ற வாறு\r\n', 1, 0),
(22197, 67, '4.jpg', '', 'image/jpeg', 29, 22193, '2023-09-13 05:40:07', 0, 0, 'System', 'களியானைத் தென்னன் கனவின்வந் தென்னை<br/>\r\nயளியா னளிப்பானே போன்றான்  - றெளியாதே<br/>\r\nசெங்காந்தண் மெல்விரலாற் சேக்கை தடவந்தே<br/>\r\nனென்காண்பே னென்னலால் யான்', 1, 0),
(22198, 68, '4.jpg', '', 'image/jpeg', 29, 22193, '2023-09-13 05:40:07', 0, 0, 'System', 'கார்நறு நீலங் கடிக்கயத்து வைகலு<br/>\r\nநீர்நிலை நின்ற தவங்கொலோ - கூர்நுனைவேல்<br/>\r\nவண்டிருக்க நக்கதார் வாமான் வழுதியாற்<br/>\r\nகொண்டிருக்கப் பெற்ற குணம்', 1, 0),
(22199, 69, '4a.jpg', '', 'image/jpeg', 29, 0, '2023-09-14 11:29:09', 0, 0, 'System', 'அறிவாரார் யாமொருநாள் பெண்டிரே மாகச்<br/>\r\nசெறிவார் தலைமேல் நடந்து - மறிதிரை<br/>\r\nமாட முரிஞ்சு மதுரையார் கோமானைக்<br/>\r\nகூட வொருநாள் பெற', 1, 0),
(22200, 70, '4a.jpg', '', 'image/jpeg', 29, 22199, '2023-09-14 11:29:09', 0, 0, 'System', 'அன்னையுங் கோல்கொண் டலைக்கு மயலாரு<br/>\r\nமென்னை யழியுஞ்சொற் சொல்லுவர் - நுண்ணிலைய<br/>\r\nதெங்குண்ட தேரை படுவழிப் பட்டேன்யான்<br/>\r\nறிண்டேர் வளவன் றிறத்து', 1, 0),
(22201, 71, '4a.jpg', '', 'image/jpeg', 29, 22199, '2023-09-14 11:29:09', 0, 0, 'System', 'நீரு நிழலும்போ னீண்ட வருளுடைய<br/>\r\nவூரிரே யென்னை யுயக்கொண்மின் - போரிற்<br/>\r\nபுகலுங் களியானைப் பூழியர்கோக் கோதைக்<br/>\r\nகழலுமென் னெஞ்சங் கிடந்து', 1, 0),
(22202, 72, '4a.jpg', '', 'image/jpeg', 29, 22199, '2023-09-14 11:29:09', 0, 0, 'System', 'புலவி புறக்கொடுப்பன் புல்லிடினா ணிற்பன்<br/>\r\nகலவி களிமயங்கிக் காணே - னிலவியசீர்<br/>\r\nமண்ணாளுஞ் செங்கோன் வளவனை யானிதன்றோ<br/>\r\nகண்ணாரக் கண்டறியா வாறு', 1, 0),
(22203, 73, '4a.jpg', '', 'image/jpeg', 29, 22199, '2023-09-14 11:29:09', 0, 0, 'System', 'கைய தவன்கடலுட் சங்கமாற் பூண்டதுவுஞ்<br/>\r\nசெய்யசங் கீன்ற செழுமுத்தான் - மெய்யதுவு<br/>\r\nமன்பொரு வேன்மாறன் வார்பொதியிற் சந்தனமா<br/>\r\nலென்பெறா வாடுமென் றோள்', 1, 0),
(22204, 74, '4a.jpg', '', 'image/jpeg', 29, 22199, '2023-09-14 11:29:09', 0, 0, 'System', 'நாணாக்காற் பெண்மை நலனழியு முன்னின்று<br/>\r\nகாணாக்காற் கைவளையுஞ் சோருமாற் - காணேனான்<br/>\r\nவண்டெவ்வந் தீர்தார் வயமான் வழுதியைக்<br/>\r\nகண்டெவ்வந் தீர்வதோ ராறு', 1, 0),
(22205, 75, '4a.jpg', '', 'image/jpeg', 29, 22199, '2023-09-14 11:29:09', 0, 0, 'System', 'வாரிய பெண்ணை வருகுரும்பை வாய்த்தனபோ<br/>\r\nலேரிய வாயினு மென்செய்யுங் - கூரிய<br/>\r\nகோட்டானைத் தென்னன் குளிர்சாந் தணியகலங்<br/>\r\nகோட்டுமண் கொள்ளா முலை', 1, 0),
(22206, 76, '4a.jpg', '', 'image/jpeg', 29, 22199, '2023-09-14 11:29:09', 0, 0, 'System', 'ஏற்பக் குடைந்தாடி லேசுவ ரல்லாக்கான்<br/>\r\nமாற்றி யிருந்தா ளெனவுரைப்பர் - வேற்கண்ணாய்<br/>\r\nகொல்யானை மாறன் குளிர்புனல் வையைநீ<br/>\r\nரெல்லா மெனக்கோ ரிடர்', 1, 0),
(22207, 77, '5.jpg', '', 'image/jpeg', 29, 0, '2023-09-14 11:31:09', 0, 0, 'System', 'கூடற் பெருமானைக் கூடலார் கோமானைக்<br/>\r\nகூடப் பெறுவேனேற் கூடென்று - கூட<br/>\r\nலிழைப்பாள்போற் காட்டி யிழையா திருக்கும்<br/>\r\nபிழைப்பிற் பிழைபாக் கறிந்து', 1, 0),
(22208, 78, '5.jpg', '', 'image/jpeg', 29, 22207, '2023-09-14 11:31:09', 0, 0, 'System', 'செங்கான் மடநாராய் தென்னுறந்தை சேறியே<br/>\r\nனின்கான்மேல் வைப்பனென் கையிரண்டும் - நன்பாற்<br/>\r\nகரையுரிஞ்சி மீன்பிறழுங் காவிரிநீர் நாடற்<br/>\r\nகுரையாயோ யானுற்ற நோய்', 1, 0),
(22209, 79, '5.jpg', '', 'image/jpeg', 29, 22207, '2023-09-14 11:31:09', 0, 0, 'System', 'என்னை யுரையலென் பேருரைய லூருரைய<br/>\r\nலன்னையு மின்ன ளெனவுரையல் - பின்னையுந்<br/>\r\nதண்படா யானைத் தமிழ்நர் பெருமாற்கென்<br/>\r\nகண்படா வாறே யுரை', 1, 0),
(22210, 80, '5.jpg', '', 'image/jpeg', 29, 22207, '2023-09-14 11:31:09', 0, 0, 'System', 'கடற்றானைக் கோதையைக் காண்கொடாள் வீணி<br/>\r\nலடைத்தா டனிக்கதவ மன்னை - யடைக்குமே<br/>\r\nலாயிழையா யென்னை யவன்மே லெடுத்துரைப்பார்<br/>\r\nவாயு மடைக்குமோ தான்', 1, 0),
(22211, 81, '5.jpg', '', 'image/jpeg', 29, 22207, '2023-09-14 11:31:09', 0, 0, 'System', 'வளையவாய் நீண்டதோள் வாட்கணா யன்னை<br/>\r\nயிளையளாய் மூத்திலள் கொல்லோ - தளையவிழ்தார்<br/>\r\nமண்கொண்ட தானை மறங்கனல்வேன் மாறனைக்<br/>\r\nகண்கொண்டு நோக்கலென் பாள்', 1, 0),
(22212, 82, '5.jpg', '', 'image/jpeg', 29, 22207, '2023-09-14 11:31:09', 0, 0, 'System', 'கொடிபாடித் தேர்பாடிக் கொய்தண்டார் மாறன்<br/>\r\nமுடிபாடி முத்தாரம் பாடித் - தொடியுலக்கை<br/>\r\nகைம்மனையி லோச்சப் பெறுவெனோ யானுமோ<br/>\r\nரம்மனைக் காவ லுளேன்', 1, 0),
(22213, 83, '5.jpg', '', 'image/jpeg', 29, 22207, '2023-09-14 11:31:09', 0, 0, 'System', 'குதலைப் பருவத்தே கோழிக்கோ மானை<br/>\r\nவதுவை பெறுகென்றா ளன்னை - யதுபோய்<br/>\r\nவிளைந்தவா வின்று வியன்கானல் வெண்டேர்த்<br/>\r\nதுளங்குநீர் மாமருட்டி யற்று', 1, 0),
(22214, 84, '5a.jpg', '', 'image/jpeg', 29, 0, '2023-09-14 11:33:58', 0, 0, 'System', 'அலங்குதார்ச் செம்பிய னாடெழிற்றோ ணோக்கி<br/>\r\nவிலங்கியான் வேண்டா வெனினு - நலந்தொலைந்து<br/>\r\nபீர்மேற் கொளலுற்ற பேதையர்க் கென்வாய்ச்சொ<br/>\r\nனீர்மே லெழுந்த நெருப்பு', 1, 0),
(22215, 85, '5a.jpg', '', 'image/jpeg', 29, 22214, '2023-09-14 11:33:58', 0, 0, 'System', 'கோட்டெங்கு சூழ்கூடற் கோமானைக் கூடவென<br/>\r\nவேட்டாங்குச் சென்றவென் னெஞ்சறியாள் - கூட்டே<br/>\r\nகுறும்பூழ் பறப்பித்த வேட்டுவன்போ லன்னை<br/>\r\nவெறுங்கூடு காவல்கொண் டாள்', 1, 0),
(22216, 86, '5a.jpg', '', 'image/jpeg', 29, 22214, '2023-09-14 11:33:58', 0, 0, 'System', 'புன்னாகச் சோலை புனற்றெங்கு சூழ்மாந்தை<br/>\r\nநன்னாக நின்றலரு நன்னாட - னென்னாகங்<br/>\r\nகங்கு லொருநாட் கனவினுட் டைவந்தா<br/>\r\nனென்கொ லிவரறிந்த வாறு', 1, 0),
(22217, 87, '5a.jpg', '', 'image/jpeg', 29, 22214, '2023-09-14 11:33:58', 0, 0, 'System', 'களியானைத் தென்ன னிளங்கோவென் றெள்ளிப்<br/>\r\nபணியாரே தம்பா ரிழக்க - வணியாகங்<br/>\r\nகைதொழு தேனு மிழக்கோ நறுமாவின்<br/>\r\nகொய்தளி ரன்ன நிறம்', 1, 0),
(22218, 88, '5a.jpg', '', 'image/jpeg', 29, 22214, '2023-09-14 11:33:58', 0, 0, 'System', 'கனவை நனவென் றெதிர்விழிக்குங் காணு<br/>\r\nநனவி லெதிர்விழிக்க நாணும் - புனையிழா<br/>\r\nயென்க ணிவையானா லெவ்வாறோ மாமாறன்<br/>\r\nறன்க ணருள்பெறுமா தான்\r\n', 1, 0),
(22219, 89, '5a.jpg', '', 'image/jpeg', 29, 22214, '2023-09-14 11:33:58', 0, 0, 'System', 'தளையவிழும் பூங்கோதைத் தாயரே யாவி<br/>\r\nகளையினுமென் கைதிறந்து காட்டேன் - வளைகொடுபோம்<br/>\r\nவன்கண்ணன் வாண்மாறன் மால்யானை தன்னுடன்வந்<br/>\r\nதென்கண் புகுந்தா னிரா', 1, 0),
(22220, 90, '5a.jpg', '', 'image/jpeg', 29, 22214, '2023-09-14 11:33:58', 0, 0, 'System', 'ஓராற்ற னென்க ணிமைபொருந்த வந்நிலையே<br/>\r\nகூரார்வேன் மாறனென் கைப்பற்ற - வாரா<br/>\r\nநனவென் றெழுந்திருந்தே னல்வினையொன் றில்லேன்<br/>\r\nகனவு மிழந்திருந்த வாறு', 1, 0),
(22221, 91, '5a.jpg', '', 'image/jpeg', 29, 22214, '2023-09-14 11:33:58', 0, 0, 'System', 'ஊட லெனவொன்று தோன்றி யலருறூஉங்<br/>\r\nகூட லிழந்தேன் கொடியன்னாய் - நீடெங்கின்<br/>\r\nபாளையிற் றேன்றொடுக்கும் பாய்புன னீர்நாட்டுக்<br/>\r\nகாளையைக் கண்படையுட் பெற்று', 1, 0),
(22222, 92, '6.jpg', '', 'image/jpeg', 29, 0, '2023-09-14 11:36:08', 0, 0, 'System', 'ஆய்மணிப் பைம்பூ ணலங்குதார்க் கோதையைக்<br/>\r\nகாணிய சென்று கதவடைத்தே - நாணிப்<br/>\r\nபெருஞ்செல்வ ரில்லத்து நல்கூர்ந்தார் போல<br/>\r\nவருஞ்செல்லும் பேருமென் னெஞ்சு', 1, 0),
(22223, 93, '6.jpg', '', 'image/jpeg', 29, 22222, '2023-09-14 11:36:08', 0, 0, 'System', 'நாணொருபால் வாங்க நலனொருபா லுண்ணெகிழ்ப்பக்<br/>\r\nகாமருதோட் கிள்ளிக்கென் கண்கவற்ற - யாமத்<br/>\r\nதிருதலைக் கொள்ளியி னுள்ளெறும்பு போலத்<br/>\r\nதிரிதரும் பேருமென் னெஞ்சு', 1, 0),
(22224, 94, '6.jpg', '', 'image/jpeg', 29, 22222, '2023-09-14 11:36:08', 0, 0, 'System', 'வரக்கண்டு நாணாதே வல்லையா னெஞ்சே<br/>\r\nமரக்கண்ணோ மண்ணாள்வார் கண்ணென் - றிரக்கண்டாய்<br/>\r\nவாளுழுவை வெல்கொடியான் வண்புனனீர் நாடற்கென்<br/>\r\nறோளழுவந் தோன்றத் தொழுது', 1, 0),
(22225, 95, '6.jpg', '', 'image/jpeg', 29, 22222, '2023-09-14 11:36:08', 0, 0, 'System', 'உகுவாய் நிலத்த துயர்மணன்மே லேறி<br/>\r\nநகுவாய்முத் தீன்றசைந்த சங்கம் - புகுவான்<br/>\r\nறிரைவரவு பார்த்திருக்குந் தென்கொற்கைக் கோமா<br/>\r\nனுரைவரவு பார்த்திருக்கு நெஞ்சு', 1, 0),
(22226, 96, '6.jpg', '', 'image/jpeg', 29, 22222, '2023-09-14 11:36:08', 0, 0, 'System', 'கடும்பனித் திங்கட்டன் கைபோர்வை யாக<br/>\r\nநெடுங்கடை நின்றதுகொ றோழி - நெடுஞ்சினவே<br/>\r\nலாய்மணிப் பைம்பூ ணலங்குதார்க் கோதையைக்<br/>\r\nகாணிய சென்றவென் னெஞ்சு', 1, 0),
(22227, 97, '6.jpg', '', 'image/jpeg', 29, 22222, '2023-09-14 11:36:08', 0, 0, 'System', 'மாறடுபோர் மன்னர் மதிக்குடையுஞ் செங்கோலுங்<br/>\r\nகூறிடுவாய் நீயோ குளிர்வாடாய் - சோறடுவா<br/>\r\nராரத்தாற் றீமூட்டு மம்பொதியிற் கோமாற்கென்<br/>\r\nவாரத்தாற் றோற்றேன் வளை', 1, 0),
(22228, 98, '6.jpg', '', 'image/jpeg', 29, 22222, '2023-09-14 11:36:08', 0, 0, 'System', 'புகுவார்க் கிடங்கொடா போதுவார்க் கொல்கா<br/>\r\nநகுவாரை நாணி மறையா - விகுகரையி<br/>\r\nனேமான் பிணைபோல நின்றதே கூடலார்<br/>\r\nகோமான்பின் சென்றவென் னெஞ்சு', 1, 0),
(22229, 99, '6a.jpg', '', 'image/jpeg', 29, 0, '2023-09-14 11:37:43', 0, 0, 'System', 'பிணிகிடந் தார்க்குப் பிறந்தநாட் போல<br/>\r\nவணியிழை யஞ்ச வருமான் - மணியானை<br/>\r\nமாறன் வழுதி மணவா மருண்மாலைச்<br/>\r\nசீறியோர் வாடை சினந்து', 1, 0),
(22230, 100, '6a.jpg', '', 'image/jpeg', 29, 22229, '2023-09-14 11:37:43', 0, 0, 'System', 'பேயோ பெருந்தண் பனிவாடாய் பெண்பிறந்தா<br/>\r\nரேயோ வுனக்கிங் கிறைக்குடிக - ணீயோ<br/>\r\nகளிபடுமால் யானைக் கடுமான்றேர்க் கிள்ளி<br/>\r\nயளியிடை யற்றம்பார்ப் பாய்', 1, 0),
(22231, 101, '6a.jpg', '', 'image/jpeg', 29, 22229, '2023-09-14 11:37:43', 0, 0, 'System', 'நாம நெடுவேல் நலங்கிள்ளி சோணாட்டுத்<br/>\r\nதாமரையு நீலமுந் தைவந் - தியாமத்து<br/>\r\nவண்டொன்று வந்தது வாரல் பனிவாடாய்<br/>\r\nபண்டன்று பட்டினங் காப்பு', 1, 0),
(22232, 102, '6a.jpg', '', 'image/jpeg', 29, 22229, '2023-09-14 11:37:43', 0, 0, 'System', 'மாணார்க் கடந்த மறவெம்போர் மாறனைக்<br/>\r\nகாணாக்கா லாயிரமுஞ் சொல்லுவேன்  கண்டக்காற்<br/>\r\nபூணாகந் தாவென்று புல்லப் பெறுவேனோ<br/>\r\nநாணோ டுடன்பிறந்த நான்', 1, 0),
(22233, 103, '6a.jpg', '', 'image/jpeg', 29, 22229, '2023-09-14 11:37:43', 0, 0, 'System', 'வருக குடநாடன் வஞ்சிக்கோ மானென்<br/>\r\nறருகல ரெல்லா மறிய - வொருகலா<br/>\r\nமுண்டா யிருக்கவவ் வொண்டொடியாண் மற்றவனைக்<br/>\r\nகண்டா ளொழிந்தாள் கலாம்', 1, 0),
(22234, 104, '6a.jpg', '', 'image/jpeg', 29, 22229, '2023-09-14 11:37:43', 0, 0, 'System', 'புல்லாதார் வல்லே புலர்கென்பர் புல்லினார்<br/>\r\nநில்லா யிரவே நெடிதென்பர் - நல்ல<br/>\r\nவிராஅமலர்த் தார்மாறன் வெண்சாந் தகல<br/>\r\nமிராவளிப் பட்ட திது', 1, 0),
(22235, 105, '6a.jpg', '', 'image/jpeg', 29, 22229, '2023-09-14 11:37:43', 0, 0, 'System', 'இப்பியீன் றிட்ட வெறிகதிர் நித்திலங்<br/>\r\nகொற்கையே யல்ல படுவது - கொற்கைக்<br/>\r\nகுருதிவேன் மாறன் குளிர்சாந் தகலங்<br/>\r\nகருதியார் கண்ணும் படும்', 1, 0),
(22236, 106, '6a.jpg', '', 'image/jpeg', 29, 22229, '2023-09-14 11:37:43', 0, 0, 'System', 'இவனென் னலங்கவர்ந்த கள்வ னிவனெனது<br/>\r\nநெஞ்ச  நிறையழித்த கள்வனென் - றஞ்சொலாய்<br/>\r\nசெல்லு நெறியெலாஞ் சேரலர்கோக் கோதைக்குச்<br/>\r\nசொல்லும் பழியோ பெரிது', 1, 0),
(22237, 107, '7.jpg', '', 'image/jpeg', 29, 0, '2023-09-14 11:38:24', 0, 0, 'System', 'காராட் டுதிரந்துாஉ யன்னை களனிழைத்து<br/>\r\nநீராட்டி நீங்கென்றால் நீங்குமோ - போராட்டு<br/>\r\nவென்று களங்கொண்ட வெஞ்சினவேற் கோதைக்கெ<br/>\r\nனெஞ்சங் களங்கொண்ட நோய்', 1, 0),
(22238, 108, '7.jpg', '', 'image/jpeg', 29, 22237, '2023-09-14 11:38:24', 0, 0, 'System', 'யானூடத் தானுணர்த்த யானுணரா விட்டதற்பின்<br/>\r\nறானூட யானுணர்த்தத் தானுணரான் - றேனூறு<br/>\r\nகொய்தார் வழுதி குளிர்சாந் தணியகல<br/>\r\nமெய்தா திராக்கழிந்த வாறு', 1, 0),
(22239, 109, '7.jpg', '', 'image/jpeg', 29, 22237, '2023-09-14 11:38:24', 0, 0, 'System', 'மல்லனீர் மாந்தையார் மாக்கடுங்கோக் காயினுஞ்<br/>\r\nசொல்லவே வேண்டு நமகுறை - நல்ல<br/>\r\nதிலகங் கிடந்த திருநுதலா யஃதா<br/>\r\nலுலகங் கிடந்த வியல்பு', 1, 0),
